    #[test]
    fn migration_delta_ops_include_windowed_same_shard_mutations() {
        let engine = test_engine();
        let shard = 77u16;
        let same_shard = tx_key_for_shard(shard, 1);
        let other_shard = tx_key_for_shard(shard + 1, 2);
        let redo_dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(1024 * 1024, 4096).unwrap());
        let redo = Arc::new(ParkingMutex::new(
            RedoLog::open(redo_dev, 0, 1024 * 1024).unwrap(),
        ));
        // The delta collection reads via the engine's merged reader; attach the
        // redo handle so it is visible (single representative handle, no
        // per-store logs).
        engine.set_redo_log(redo.clone());

        let snapshot_seq = redo.lock().current_sequence();
        redo.lock()
            .append_and_flush(crate::redo::RedoOp::SetLocked {
                tx_key: same_shard,
                value: true,
            })
            .unwrap();
        redo.lock()
            .append_and_flush(crate::redo::RedoOp::SetLocked {
                tx_key: other_shard,
                value: false,
            })
            .unwrap();
        let fence_seq = redo.lock().current_sequence();
        let redo_log = Some(redo);

        let ops = collect_migration_delta_ops(&redo_log, snapshot_seq, fence_seq, shard, &engine)
            .expect("delta collection should succeed");
        assert_eq!(ops.len(), 1);
        match &ops[0] {
            crate::replication::protocol::ReplicaOp::SetLocked {
                tx_key,
                value,
                master_generation,
            } => {
                assert_eq!(*tx_key, same_shard);
                assert!(*value);
                assert_eq!(*master_generation, 0);
            }
            other => panic!("expected SetLocked delta, got {other:?}"),
        }
    }

    /// CRITICAL FIX: a multi-txid `SetMinedBatch` landing in the migration
    /// delta window must ship every txid it carries as its own
    /// `ReplicaOp::SetMined`, not vanish. Pre-fix, `collect_migration_delta_ops`
    /// used `redo_entry_to_replica_op` (single-op) via `filter_map`, which
    /// returns `None` for any `SetMinedBatch` of more than one txid — the
    /// migration target would never receive the mutation, permanently
    /// diverging from the source for every txid in the batch.
    #[test]
    fn migration_delta_ops_include_multi_txid_set_mined_batch() {
        let engine = test_engine();
        let shard = 88u16;
        let k1 = tx_key_for_shard(shard, 1);
        let k2 = tx_key_for_shard(shard, 2);
        let k3 = tx_key_for_shard(shard, 3);
        let other_shard = tx_key_for_shard(shard + 1, 4);
        let redo_dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(1024 * 1024, 4096).unwrap());
        let redo = Arc::new(ParkingMutex::new(
            RedoLog::open(redo_dev, 0, 1024 * 1024).unwrap(),
        ));
        engine.set_redo_log(redo.clone());

        let snapshot_seq = redo.lock().current_sequence();
        redo.lock()
            .append_and_flush(crate::redo::RedoOp::SetMinedBatch {
                block_id: 12,
                block_height: 820_000,
                subtree_idx: 1,
                on_longest_chain: true,
                current_block_height: 820_010,
                block_height_retention: 288,
                unset: false,
                // A same-store batch may still span shards (store split ≠
                // shard split) — include a foreign-shard txid to confirm it
                // is excluded while the 3 same-shard txids all ship.
                txids: vec![k1, k2, other_shard, k3],
            })
            .unwrap();
        let fence_seq = redo.lock().current_sequence();
        let redo_log = Some(redo);

        let ops = collect_migration_delta_ops(&redo_log, snapshot_seq, fence_seq, shard, &engine)
            .expect("delta collection should succeed");
        // Task 14: the same-shard txids now ship as ONE coalesced
        // `ReplicaOp::SetMinedBatch`, not one `ReplicaOp::SetMined` per txid.
        assert_eq!(
            ops.len(),
            1,
            "every same-shard txid must coalesce into a single batch op, got {ops:?}"
        );
        match &ops[0] {
            crate::replication::protocol::ReplicaOp::SetMinedBatch {
                block_id, txids, ..
            } => {
                assert_eq!(*block_id, 12);
                for expected in [k1, k2, k3] {
                    assert!(
                        txids.contains(&expected),
                        "missing txid {expected:?} from migration delta: {txids:?}"
                    );
                }
                assert!(
                    !txids.contains(&other_shard),
                    "the foreign-shard txid must not ship in this shard's delta"
                );
                assert_eq!(txids.len(), 3, "no extra/foreign txids");
            }
            other => panic!("expected SetMinedBatch delta, got {other:?}"),
        }
    }

    /// #35 regression: the manifest/late-key fast-path must treat a shard
    /// whose key SET churned in the snapshot→fence window as "changed" so the
    /// caller rescans the live index. The pre-fix `shard_record_count`-equality
    /// fast-path was unsound under a balanced delete-one + create-another
    /// (count unchanged, membership changed): the stale snapshot omitted the
    /// newly created key, so the manifest under-counted and the COMPLETE
    /// handshake was rejected for a record-count mismatch (sc09 saw
    /// "expected N, got N+1") — the handoff never converged.
    #[test]
    fn shard_membership_change_detected_for_windowed_create_or_delete() {
        let shard = 81u16;
        let created = tx_key_for_shard(shard, 1);
        let deleted = tx_key_for_shard(shard, 2);
        let other_shard_key = tx_key_for_shard(shard + 1, 3);
        let redo_dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(1024 * 1024, 4096).unwrap());
        let redo = Arc::new(ParkingMutex::new(
            RedoLog::open(redo_dev, 0, 1024 * 1024).unwrap(),
        ));

        // Window: a balanced delete-one + create-another on the target shard
        // (count nets to unchanged) plus a same-shard mutation and an
        // unrelated-shard create. Only Create/Delete for THIS shard must flip
        // the membership flag.
        let snapshot_seq = redo.lock().current_sequence();
        redo.lock()
            .append_and_flush(crate::redo::RedoOp::Delete {
                tx_key: deleted,
                record_offset: 0,
                record_size: 0,
                cause: crate::ops::tombstone::DeleteCause::ClientDelete,
            })
            .unwrap();
        redo.lock()
            .append_and_flush(crate::redo::RedoOp::ReplicaCreate {
                tx_key: created,
                device_id: 0,
                record_offset: 0,
                utxo_count: 1,
            })
            .unwrap();
        redo.lock()
            .append_and_flush(crate::redo::RedoOp::SetLocked {
                tx_key: created,
                value: true,
            })
            .unwrap();
        let fence_seq = redo.lock().current_sequence();
        // Attach the redo handle to an engine; the window check reads through
        // the engine's merged reader (which falls back to this single
        // representative handle when no per-store logs are attached).
        let redo_engine = test_engine();
        redo_engine.set_redo_log(redo.clone());
        let redo_log = Some(redo);

        assert!(
            shard_membership_changed_in_window(
                &redo_log,
                snapshot_seq,
                fence_seq,
                shard,
                &redo_engine
            )
            .unwrap(),
            "a windowed create/delete on the shard must flag the membership as changed",
        );

        // A window with ONLY a same-shard mutation (no create/delete) must not
        // flip the flag — the snapshot key set is provably exact and the
        // fast-path stays valid.
        let mutate_dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(1024 * 1024, 4096).unwrap());
        let mutate_redo = Arc::new(ParkingMutex::new(
            RedoLog::open(mutate_dev, 0, 1024 * 1024).unwrap(),
        ));
        let mutate_snapshot = mutate_redo.lock().current_sequence();
        mutate_redo
            .lock()
            .append_and_flush(crate::redo::RedoOp::SetLocked {
                tx_key: created,
                value: false,
            })
            .unwrap();
        // An unrelated-shard create in the window must also be ignored.
        mutate_redo
            .lock()
            .append_and_flush(crate::redo::RedoOp::ReplicaCreate {
                tx_key: other_shard_key,
                device_id: 0,
                record_offset: 0,
                utxo_count: 1,
            })
            .unwrap();
        let mutate_fence = mutate_redo.lock().current_sequence();
        let mutate_engine = test_engine();
        mutate_engine.set_redo_log(mutate_redo.clone());
        let mutate_log = Some(mutate_redo);

        assert!(
            !shard_membership_changed_in_window(
                &mutate_log,
                mutate_snapshot,
                mutate_fence,
                shard,
                &mutate_engine
            )
            .unwrap(),
            "a window with no same-shard create/delete must keep the fast-path valid",
        );

        // No window (snapshot == fence) means nothing could have changed.
        assert!(
            !shard_membership_changed_in_window(
                &mutate_log,
                mutate_fence,
                mutate_fence,
                shard,
                &mutate_engine
            )
            .unwrap(),
            "an empty window must report no membership change",
        );

        // No evidence (absent redo log, or no anchoring snapshot sequence)
        // must conservatively report "changed" so the caller rescans the live
        // index instead of trusting a possibly-stale snapshot.
        let absent_engine = test_engine();
        assert!(
            shard_membership_changed_in_window(&None, 10, 20, shard, &absent_engine).unwrap(),
            "an absent redo log must conservatively report a membership change",
        );
        assert!(
            shard_membership_changed_in_window(&mutate_log, 0, 20, shard, &mutate_engine).unwrap(),
            "a zero snapshot sequence must conservatively report a membership change",
        );
    }

