    /// Scenario 17 — the cleanup gate must be PER-SHARD, not global: a failed
    /// task on ONE shard must not suppress reclamation of an UNRELATED settled
    /// shard. Observed: 5 failed shards held ~1000 settled shards hostage on
    /// node1, leaving 1401/2000 records at 3 holders under RF=2. Both shards
    /// carry committed-handoff evidence here, so retention of the failed shard
    /// is attributable ONLY to its unresolved task.
    #[test]
    fn run_orphan_cleanup_failed_shard_does_not_block_unrelated_settled_shard() {
        let old_table =
            ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2), NodeId(3)], 2, 10, 1);
        let new_table = ShardTable::compute_with_epoch(&[NodeId(2), NodeId(3)], 2, 11, 1);
        let unowned = |s: u16| {
            let old = old_table.target_assignment(s);
            let new = new_table.target_assignment(s);
            (old.master == NodeId(1) || old.replicas.contains(&NodeId(1)))
                && new.master != NodeId(1)
                && !new.replicas.contains(&NodeId(1))
        };
        let failed_shard = (0..NUM_SHARDS as u16)
            .find(|&s| unowned(s))
            .expect("node1 should hold a shard it no longer owns after removal");
        let settled_shard = (0..NUM_SHARDS as u16)
            .find(|&s| s != failed_shard && unowned(s))
            .expect("a second unowned shard must exist");

        let engine = Arc::new(test_engine());
        create_test_record(&engine, tx_key_for_shard(failed_shard, 50));
        create_test_record(&engine, tx_key_for_shard(settled_shard, 51));

        let shard_table = Arc::new(ShardTableLock::new(new_table.clone()));
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        {
            let mut mgr = migration.lock();
            mgr.record_committed_handoff(failed_shard, new_table.version);
            mgr.record_committed_handoff(settled_shard, new_table.version);
            let task = MigrationTask {
                shard: failed_shard,
                from_node: NodeId(1),
                to_node: NodeId(2),
                is_master: true,
            };
            mgr.start_outbound(
                std::slice::from_ref(&task),
                NodeId(1),
                &std::collections::HashSet::from([failed_shard]),
            );
            mgr.mark_failed(&task);
            assert_eq!(mgr.failed_count(), 1, "precondition: one failed task");
        }

        run_orphan_cleanup(
            NodeId(1),
            &engine,
            &shard_table,
            &migration,
            new_table.version,
        );

        assert_eq!(
            engine.shard_record_count(settled_shard),
            0,
            "a failed task on shard {failed_shard} must not block cleanup of \
             settled shard {settled_shard}",
        );
        assert_eq!(
            engine.shard_record_count(failed_shard),
            1,
            "the shard with the unresolved task must be retained",
        );
    }

    /// Integration-style reproduction of the task #28 data-loss bug, driving
    /// the REAL completion + REAL orphan-cleanup paths.
    ///
    /// Scenario: under epoch N this node (node2) is the handoff source for a
    /// shard whose only copy it holds. The topology bumps to N+1 before the
    /// completion is processed, so the completion is DISCARDED AS STALE
    /// (`complete_migration_task_current_epoch` returns false at the epoch
    /// guard — no `commit_shard`, no committed-handoff record). The epoch-(N+1)
    /// re-home is still in flight, so node2 is the last holder. `run_orphan_cleanup`
    /// then runs on node2 at epoch N+1. It MUST NOT delete the record.
    ///
    /// Fail-before: cleanup deleted node2's only copy → the record is stranded
    /// (holders=[N,N,N]). Pass-after: cleanup retains it; the record stays
    /// readable on node2 until a real handoff completes.
    #[test]
    fn stale_discarded_handoff_does_not_strand_last_copy_under_orphan_cleanup() {
        let _guard = migration_metrics_test_guard();
        let _metrics = install_test_migration_metrics();

        // Epoch N: node1, node2, node3. Find a shard node2 holds (master or
        // replica) so it has a real local copy to lose.
        let table_n = ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2), NodeId(3)], 2, 3, 1);
        // Epoch N+1: a different membership/term that strips node2 of the shard.
        let table_n1 = ShardTable::compute_with_epoch(&[NodeId(1), NodeId(3)], 2, 4, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                let a = table_n.target_assignment(s);
                let b = table_n1.target_assignment(s);
                (a.master == NodeId(2) || a.replicas.contains(&NodeId(2)))
                    && b.master != NodeId(2)
                    && !b.replicas.contains(&NodeId(2))
            })
            .expect("node2 must hold a shard at N that it loses at N+1");

        let engine = Arc::new(test_engine());
        let key = tx_key_for_shard(shard, 77);
        create_test_record(&engine, key);
        assert_eq!(engine.shard_record_count(shard), 1);

        // node2's live shard table starts at epoch N with the handoff fenced.
        let shard_table = Arc::new(ShardTableLock::new(table_n.clone()));
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let fenced = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        // Epoch-N outbound handoff source → node3, fenced and streaming.
        let task_n = MigrationTask {
            shard,
            from_node: NodeId(2),
            to_node: NodeId(3),
            is_master: true,
        };
        {
            let mut mgr = migration.lock();
            mgr.start_outbound(
                std::slice::from_ref(&task_n),
                NodeId(2),
                &std::collections::HashSet::from([shard]),
            );
            mgr.mark_fenced(&task_n, 0);
        }
        fenced.set(shard);
        migrating.set(shard);

        // Topology bumps to N+1 BEFORE the completion is processed.
        *shard_table.write() = table_n1.clone();

        // The epoch-N completion now arrives: discarded as stale (epoch guard).
        let accepted = complete_migration_task_current_epoch(
            &migration,
            &shard_table,
            &fenced,
            &migrating,
            &task_n,
            /* task_epoch */ table_n.version,
            /* commit */ true,
        );
        assert!(
            !accepted,
            "epoch-N completion must be discarded as stale once N+1 is active",
        );
        assert!(
            !migration
                .lock()
                .has_committed_handoff(shard, table_n1.version),
            "a stale-discarded completion must NOT record committed-handoff evidence",
        );

        // The epoch-(N+1) re-home is still in flight; node2 is the last holder.
        // Mirror production activation, which marks the stale epoch-N task
        // failed then `cleanup_completed`s it away — leaving active_count and
        // failed_count at 0 (exactly the bug's observed state). This proves the
        // committed-handoff gate, NOT the active/failed guards, is what now
        // protects the data. `cleanup_completed` does not touch the
        // committed-handoff record.
        {
            let mut mgr = migration.lock();
            mgr.mark_failed(&task_n);
            mgr.cleanup_completed();
        }
        assert_eq!(migration.lock().active_count(), 0);
        assert_eq!(migration.lock().failed_count(), 0);

        // Orphan cleanup runs on node2 at epoch N+1.
        run_orphan_cleanup(
            NodeId(2),
            &engine,
            &shard_table,
            &migration,
            table_n1.version,
        );

        assert_eq!(
            engine.shard_record_count(shard),
            1,
            "orphan cleanup must NOT strand the last copy of a stale-discarded handoff",
        );
        // And the record is still readable on node2.
        assert!(
            engine.read_metadata(&key).is_ok(),
            "the retained record must remain readable on the source",
        );
    }

    /// The completion path records committed-handoff evidence only when it
    /// actually commits the master move (`commit == true`). A non-committing
    /// completion (e.g. replica-only fan-out) leaves no evidence, so a later
    /// orphan sweep cannot delete the shard. Pins the wiring between
    /// `complete_migration_task_current_epoch` and the cleanup gate.
    #[test]
    fn committed_handoff_recorded_only_when_master_move_commits() {
        let _guard = migration_metrics_test_guard();
        let _metrics = install_test_migration_metrics();
        let members = vec![NodeId(1), NodeId(2)];
        let table = ShardTable::compute_with_epoch(&members, 1, 10, 1);
        let shard_table: Arc<ShardTableLock<ShardTable>> = Arc::new(ShardTableLock::new(table));
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let fenced = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        // commit == false: no evidence recorded.
        let task_no_commit = make_outbound_master_task(200, NodeId(1), NodeId(2));
        migration.lock().start_outbound(
            std::slice::from_ref(&task_no_commit),
            NodeId(1),
            &std::collections::HashSet::new(),
        );
        assert!(complete_migration_task_current_epoch(
            &migration,
            &shard_table,
            &fenced,
            &migrating,
            &task_no_commit,
            10,
            false,
        ));
        assert!(
            !migration.lock().has_committed_handoff(200, 10),
            "non-committing completion must NOT record committed-handoff evidence",
        );

        // commit == true: evidence recorded.
        let task_commit = make_outbound_master_task(201, NodeId(1), NodeId(2));
        migration.lock().start_outbound(
            std::slice::from_ref(&task_commit),
            NodeId(1),
            &std::collections::HashSet::new(),
        );
        assert!(complete_migration_task_current_epoch(
            &migration,
            &shard_table,
            &fenced,
            &migrating,
            &task_commit,
            10,
            true,
        ));
        assert!(
            migration.lock().has_committed_handoff(201, 10),
            "committing completion must record committed-handoff evidence",
        );
    }

    /// Task #31: an ABORTED outbound handoff (the failure path that sends a
    /// `send_migration_abort_completion_best_effort`) must NOT record a
    /// committed handoff — an abort means the handoff did NOT complete, so the
    /// source stays authoritative and the #25/#28 gates (relinquish /
    /// orphan-cleanup), which both key off `has_committed_handoff`, must NOT
    /// be allowed to let the source drop the shard.
    #[test]
    fn aborted_handoff_does_not_record_committed_handoff() {
        let _guard = migration_metrics_test_guard();
        let _metrics = install_test_migration_metrics();
        let members = vec![NodeId(1), NodeId(2)];
        let table = ShardTable::compute_with_epoch(&members, 1, 10, 1);
        let shard_table: Arc<ShardTableLock<ShardTable>> = Arc::new(ShardTableLock::new(table));
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let fenced = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        let task = make_outbound_master_task(205, NodeId(1), NodeId(2));
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            NodeId(1),
            &std::collections::HashSet::new(),
        );

        // The abort path: fail the task (rollback to self), exactly as the
        // streaming/manifest/commit failure branches do after emitting the
        // abort frame. This MUST NOT record committed-handoff evidence.
        assert!(fail_migration_task_current_epoch(
            &migration,
            &shard_table,
            &fenced,
            &migrating,
            &task,
            10,
            FailedTaskTableAction::Rollback,
        ));
        assert!(
            !migration.lock().has_committed_handoff(205, 10),
            "an aborted handoff must NOT record committed-handoff evidence",
        );
    }

    /// Task #31: the relinquish disposition that drops `self`'s mastership is
    /// reachable ONLY when `self` holds NO records (Cond 5). On an abort where
    /// the source still holds the shard's records, the disposition is
    /// RollbackToSelf — the source stays the authoritative master+holder, so an
    /// aborted handoff can never hand a non-empty shard away and lose it.
    #[test]
    fn aborted_handoff_with_records_stays_authoritative_rollback() {
        let members = vec![NodeId(1), NodeId(2)];
        let table = ShardTable::compute_with_epoch(&members, 1, 10, 1);
        // Find a shard whose committed master is NodeId(2) so the only thing
        // blocking a relinquish is the self-holds-records guard.
        let shard = (0..crate::cluster::shards::NUM_SHARDS as u16)
            .find(|&s| table.target_assignment(s).master == NodeId(2))
            .expect("some shard masters to NodeId(2) in a 2-member table");
        let task = make_outbound_master_task(shard, NodeId(1), NodeId(2));
        let live: std::collections::HashSet<NodeId> = [NodeId(1), NodeId(2)].into_iter().collect();

        // self holds records → must roll back, never relinquish.
        let disposition_with_records = failed_handoff_disposition(
            &task,
            &table,
            &members,
            1,
            NodeId(1),
            &live,
            /* has_pending_inbound */ false,
            /* self_holds_records */ true,
            /* target_holds_superset */ false,
            1,
            None,
        );
        assert_eq!(
            disposition_with_records,
            FailedHandoffDisposition::RollbackToSelf,
            "an aborted handoff of a NON-empty shard must keep the source authoritative",
        );

        // Sanity: an EMPTY shard with the same topology IS relinquish-eligible,
        // proving the records guard (not some other condition) is what blocks it.
        let disposition_empty = failed_handoff_disposition(
            &task,
            &table,
            &members,
            1,
            NodeId(1),
            &live,
            false,
            /* self_holds_records */ false,
            /* target_holds_superset */ false,
            1,
            None,
        );
        assert_eq!(
            disposition_empty,
            FailedHandoffDisposition::RelinquishToCommittedMaster,
            "an empty phantom shard is the only no-loss-safe relinquish case",
        );
    }

    /// sc09/sc05 drain convergence (transfer-then-relinquish). A NON-empty
    /// phantom master whose rightful master is a live committed peer that has
    /// been PROVEN to hold a superset of self's records MUST relinquish — the
    /// data is safe in the rightful master, so dropping the phantom copy is
    /// no-loss and lets the drain reach zero. This is the case the bare
    /// no-loss guard left stuck forever (rollback-to-self).
    #[test]
    fn nonempty_phantom_relinquishes_when_target_holds_superset() {
        let (table, shard, self_id, rightful, committed_members, task) = phantom_handoff_fixture();
        assert_eq!(table.effective_assignment(shard).master, self_id);
        assert_eq!(table.target_assignment(shard).master, rightful);
        let live_members: std::collections::HashSet<NodeId> =
            committed_members.iter().copied().collect();

        // FAIL-BEFORE: without the superset proof, a non-empty copy rolls back
        // to self — the non-converging stall this fix targets.
        let stuck = failed_handoff_disposition(
            &task,
            &table,
            &committed_members,
            2,
            self_id,
            &live_members,
            /* has_pending_inbound */ false,
            /* self_holds_records */ true,
            /* target_holds_superset */ false,
            1,
            None,
        );
        assert_eq!(
            stuck,
            FailedHandoffDisposition::RollbackToSelf,
            "without superset proof, a non-empty copy must roll back (no-loss)",
        );

        // PASS-AFTER: the verify-only superset probe confirmed the rightful
        // master holds every one of self's records → relinquish, converging to
        // a single master without losing data.
        let converged = failed_handoff_disposition(
            &task,
            &table,
            &committed_members,
            2,
            self_id,
            &live_members,
            /* has_pending_inbound */ false,
            /* self_holds_records */ true,
            /* target_holds_superset */ true,
            1,
            None,
        );
        assert_eq!(
            converged,
            FailedHandoffDisposition::RelinquishToCommittedMaster,
            "a superset-proven rightful master makes the non-empty drop no-loss",
        );
    }

    /// The superset proof relaxes ONLY the records guard — every OTHER no-loss
    /// condition must still hold. A superset-proven handoff whose rightful
    /// master is DEAD must still roll back (cannot relinquish to a master that
    /// cannot serve).
    #[test]
    fn superset_proof_does_not_override_dead_rightful_master() {
        let (table, _shard, self_id, rightful, committed_members, task) = phantom_handoff_fixture();
        let mut live_members: std::collections::HashSet<NodeId> =
            committed_members.iter().copied().collect();
        live_members.remove(&rightful); // rightful master crashed

        let disposition = failed_handoff_disposition(
            &task,
            &table,
            &committed_members,
            2,
            self_id,
            &live_members,
            /* has_pending_inbound */ false,
            /* self_holds_records */ true,
            /* target_holds_superset */ true,
            1,
            None,
        );
        assert_eq!(
            disposition,
            FailedHandoffDisposition::RollbackToSelf,
            "superset proof never overrides the live-rightful-master requirement",
        );
    }

    /// Re-acquiring a shard as an inbound target clears any prior committed-
    /// handoff record, so a stale entry cannot authorize deleting freshly
    /// re-homed data after a later un-assignment that lacks its own handoff.
    #[test]
    fn committed_handoff_cleared_on_reacquisition() {
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().record_committed_handoff(300, 10);
        assert!(migration.lock().has_committed_handoff(300, 10));

        let inbound = MigrationTask {
            shard: 300,
            from_node: NodeId(2),
            to_node: NodeId(1),
            is_master: true,
        };
        migration.lock().start_outbound(
            std::slice::from_ref(&inbound),
            NodeId(1),
            &std::collections::HashSet::new(),
        );

        assert!(
            !migration.lock().has_committed_handoff(300, 10),
            "re-acquiring the shard as inbound target must clear committed-handoff evidence",
        );
    }

    /// Epoch-exact validity (multi-hop guard): a handoff committed at epoch N
    /// authorizes deletion ONLY while the table is still at epoch N. Once the
    /// topology advances to N+1, the entry is stale — the new owner may be a
    /// different node this source never verified — so cleanup must retain.
    #[test]
    fn committed_handoff_is_stale_after_epoch_bump() {
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().record_committed_handoff(400, 10);
        assert!(
            migration.lock().has_committed_handoff(400, 10),
            "evidence is valid at the epoch it was recorded",
        );
        assert!(
            !migration.lock().has_committed_handoff(400, 11),
            "evidence must be stale once the topology epoch advances",
        );
        assert!(
            !migration.lock().has_committed_handoff(400, 9),
            "evidence must not apply to an earlier epoch either",
        );
    }

    #[test]
    fn per_shard_orphan_cleanup_waits_for_active_same_shard_task() {
        let old_table =
            ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2), NodeId(3)], 2, 10, 1);
        let new_table = ShardTable::compute_with_epoch(&[NodeId(2), NodeId(3)], 2, 11, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                let old = old_table.target_assignment(s);
                old.master == NodeId(1) || old.replicas.contains(&NodeId(1))
            })
            .expect("node1 should hold at least one shard before removal");
        let engine = Arc::new(test_engine());
        let key = tx_key_for_shard(shard, 45);
        create_test_record(&engine, key);

        let shard_table = Arc::new(ShardTableLock::new(new_table.clone()));
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let task = MigrationTask {
            shard,
            from_node: NodeId(1),
            to_node: NodeId(2),
            is_master: true,
        };
        migration.lock().start_outbound(
            &[task],
            NodeId(1),
            &std::collections::HashSet::from([shard]),
        );

        cleanup_orphaned_shard_if_settled(
            NodeId(1),
            &engine,
            &shard_table,
            &migration,
            shard,
            new_table.version,
        );

        assert_eq!(engine.shard_record_count(shard), 1);
    }

    /// Scenario 17 mirror (per-shard path): activity on an UNRELATED shard
    /// must not block reclamation of a settled shard that carries
    /// committed-handoff evidence — the gate is per-shard, not global. The
    /// same-shard wait is pinned separately by
    /// `per_shard_orphan_cleanup_waits_for_active_same_shard_task`.
    #[test]
    fn per_shard_orphan_cleanup_ignores_unrelated_shard_activity() {
        let old_table =
            ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2), NodeId(3)], 2, 10, 1);
        let new_table = ShardTable::compute_with_epoch(&[NodeId(2), NodeId(3)], 2, 11, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                let old = old_table.target_assignment(s);
                let new = new_table.target_assignment(s);
                (old.master == NodeId(1) || old.replicas.contains(&NodeId(1)))
                    && new.master != NodeId(1)
                    && !new.replicas.contains(&NodeId(1))
            })
            .expect("node1 should hold a shard it no longer owns after removal");
        let other_shard = (0..NUM_SHARDS as u16)
            .find(|&s| s != shard)
            .expect("expected a distinct shard");
        let engine = Arc::new(test_engine());
        let key = tx_key_for_shard(shard, 46);
        create_test_record(&engine, key);

        let shard_table = Arc::new(ShardTableLock::new(new_table.clone()));
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration
            .lock()
            .record_committed_handoff(shard, new_table.version);
        let task = MigrationTask {
            shard: other_shard,
            from_node: NodeId(1),
            to_node: NodeId(2),
            is_master: true,
        };
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            NodeId(1),
            &std::collections::HashSet::from([other_shard]),
        );

        cleanup_orphaned_shard_if_settled(
            NodeId(1),
            &engine,
            &shard_table,
            &migration,
            shard,
            new_table.version,
        );

        assert_eq!(
            engine.shard_record_count(shard),
            0,
            "an active task on shard {other_shard} must not block per-shard \
             cleanup of settled shard {shard}",
        );
    }

    #[test]
    fn quiesce_signals_topology_activation_without_pre_mutating_local_state() {
        let members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let table = ShardTable::compute_with_epoch(&members, 2, 7, 1);
        let live_nodes = [
            (NodeId(1), "127.0.0.1:11001".parse().unwrap()),
            (NodeId(2), "127.0.0.1:11002".parse().unwrap()),
            (NodeId(3), "127.0.0.1:11003".parse().unwrap()),
        ];
        let mut cluster = new_test_running_cluster(
            NodeId(1),
            table.clone(),
            &live_nodes,
            &members,
            &[],
            &[],
            &[],
            members.len(),
        );
        let (topology_commit_tx, topology_commit_rx) = std::sync::mpsc::channel();
        cluster.topology_commit_tx = topology_commit_tx;

        cluster.quiesce();

        let (new_members, new_term) = topology_commit_rx
            .recv_timeout(std::time::Duration::from_secs(1))
            .expect("quiesce must signal the committed topology for event-loop activation");
        assert_eq!(new_members, vec![NodeId(2), NodeId(3)]);
        assert_eq!(new_term, table.version + 1);
        assert_eq!(
            cluster.committed_topology_members(),
            vec![NodeId(2), NodeId(3)]
        );
        assert_eq!(cluster.committed_topology_term(), table.version + 1);
        assert_eq!(
            cluster.shard_table.read().version,
            table.version,
            "quiesce should leave shard-table activation to the event loop"
        );
        assert_eq!(
            cluster.shard_table.read().pending_handoff_count(),
            0,
            "quiesce should not begin handoff synchronously"
        );
        assert_eq!(
            cluster.migration.lock().active_count(),
            0,
            "quiesce should not pre-register outbound migrations outside activate_topology"
        );
        assert_eq!(cluster.inbound_pending_count(), 0);
        assert_eq!(cluster.fenced_shard_count(), 0);
    }

    /// E-4: pin the intended graceful-drain trust model. `quiesce()`
    /// fabricates a `TopologyCommit` whose `voters` list trivially satisfies
    /// `has_quorum_voter_proof` without collecting real votes — by design, it
    /// trusts authenticated peers. This test locks in that the fabricated
    /// commit is *accepted* by the topology authority (it shrinks the cluster
    /// as designed) AND that the safety floor it must NOT touch — the
    /// peak-derived quorum — stays put. A future refactor that accidentally
    /// breaks graceful drain (e.g. the fabricated commit stops satisfying the
    /// proof, so `handle_commit` silently drops it) fails here loudly; a
    /// refactor that wrongly lets the drain lower the peak also fails here.
    /// AUDIT M1.1 (CRITICAL) regression — a node that committed an N-member
    /// topology must gate writes on that peak even when the SWIM-fed `peak_size`
    /// atomic never caught up (e.g. a catch-up node that adopted a committed
    /// topology without a corresponding SWIM membership burst).
    ///
    /// Before the fix, `peak_cluster_size()` read only the stale SWIM atomic, so
    /// `check_quorum` used peak=1 and accepted writes that should have returned
    /// `ERR_NO_QUORUM`; `persisted_state` likewise wrote the stale peak,
    /// weakening quorum across restart.
    #[test]
    fn committed_topology_peak_unifies_swim_and_authority() {
        let members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let table = ShardTable::compute_with_epoch(&members, 2, 4, 1);
        let live_nodes = [(NodeId(1), "127.0.0.1:12101".parse().unwrap())];
        // Committed 3-member topology raises ONLY the TopologyAuthority peak
        // (via handle_commit in the helper); the SWIM peak_size atomic is left
        // stale at 1 — the exact divergence the audit flagged.
        let cluster = new_test_running_cluster(
            NodeId(1),
            table,
            &live_nodes,
            &members, // committed members -> authority peak == 3
            &[],
            &[],
            &[],
            1, // SWIM peak_size atomic stays 1
        );

        // Read side (runtime write gating): must see the committed peak.
        assert_eq!(
            cluster.peak_cluster_size(),
            3,
            "peak must unify the committed-topology peak with the SWIM atomic; \
             a quorum gate reading 1 here would accept split-brain writes",
        );

        // Persist side (restart durability): the on-disk peak must not regress
        // below the committed cluster size even when the caller passes the stale
        // SWIM peak.
        let persisted = cluster.topology_authority.persisted_state(1, 0);
        assert_eq!(
            persisted.peak_cluster_size, 3,
            "persisted peak must be clamped to the committed cluster size",
        );
    }

    #[test]
    fn quiesce_fabricated_commit_is_accepted_and_preserves_peak_floor() {
        let members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let table = ShardTable::compute_with_epoch(&members, 2, 4, 1);
        let live_nodes = [
            (NodeId(1), "127.0.0.1:12001".parse().unwrap()),
            (NodeId(2), "127.0.0.1:12002".parse().unwrap()),
            (NodeId(3), "127.0.0.1:12003".parse().unwrap()),
        ];
        let cluster = new_test_running_cluster(
            NodeId(1),
            table.clone(),
            &live_nodes,
            &members,
            &[],
            &[],
            &[],
            members.len(),
        );
        let peak_before = cluster.topology_authority.peak_cluster_size();
        assert_eq!(
            peak_before, 3,
            "precondition: peak reflects the 3-node cluster size",
        );

        cluster.quiesce();

        // The fabricated-voter commit must have been ACCEPTED by
        // `handle_commit` — if `has_quorum_voter_proof` rejected it,
        // `handle_commit` returns `None` and committed members stay [1,2,3].
        assert_eq!(
            cluster.committed_topology_members(),
            vec![NodeId(2), NodeId(3)],
            "quiesce's fabricated commit must shrink the committed member set \
             (proof of acceptance by has_quorum_voter_proof)",
        );
        assert_eq!(
            cluster.committed_topology_term(),
            table.version + 1,
            "drain advances the committed term by exactly one",
        );
        // The recorded voter set is the fabricated full-survivor list — the
        // structural signature of the trust-authenticated-peers design.
        assert_eq!(
            cluster.topology_authority.committed_voters(),
            vec![NodeId(2), NodeId(3)],
            "fabricated voters == surviving members (no real votes collected)",
        );
        // The peak-derived quorum floor (E-01) must be UNCHANGED — the drain
        // is never trusted to lower split-brain safety.
        assert_eq!(
            cluster.topology_authority.peak_cluster_size(),
            peak_before,
            "quiesce must NEVER lower the peak; the fabricated commit carries \
             no proof of old-majority ratification",
        );
    }

    // -----------------------------------------------------------------------
    // G8 stage 3 — coordinator floor collapse + SWIM force-evict + operator
    // verb (complete safe-shrink). Stages 1/2 (topology.rs) built the
    // durable committed_peak + Gate B + propose_shrink; these tests prove
    // the lowered floor actually takes effect at the RunningCluster level
    // and does not re-inflate from a lingering SWIM rumor about a removed
    // node.
    // -----------------------------------------------------------------------

    /// Build a 5-node `RunningCluster` (committed members + `peak_size` both
    /// 5, every peer SWIM-Alive) and a hand-fabricated, Gate-B-satisfying
    /// 5→3 shrink `TopologyCommit` (voters = all 3 survivors — a >50% cut
    /// needs old_peak/2+1 = 3 distinct voters, and Gate B/`has_quorum_voter_
    /// proof` both require voters ⊆ the commit's own 3-member `members`, so
    /// unanimous survivor consent is the only way to satisfy both at once).
    /// Mirrors the `quorum_commit`/`seed_committed` pattern in `topology.rs`'s
    /// stage-2 tests, but built on a real `RunningCluster` so the
    /// COORDINATOR-level reaction (not just the authority) is exercised.
    fn shrink_5_to_3_fixture() -> (RunningCluster, crate::cluster::topology::TopologyCommit) {
        let members5 = vec![NodeId(1), NodeId(2), NodeId(3), NodeId(4), NodeId(5)];
        let table = ShardTable::compute_with_epoch(&members5, 1, 1, 1);
        let live_nodes: Vec<(NodeId, SocketAddr)> = members5
            .iter()
            .enumerate()
            .map(|(i, &n)| (n, format!("127.0.0.1:{}", 15300 + i).parse().unwrap()))
            .collect();
        let cluster =
            new_test_running_cluster(NodeId(1), table, &live_nodes, &members5, &[], &[], &[], 5);
        assert_eq!(
            cluster.peak_cluster_size(),
            5,
            "fixture precondition: 5-node cluster peak is 5",
        );

        let cid = cluster.topology_authority.cluster_id();
        let surviving = vec![NodeId(1), NodeId(2), NodeId(3)];
        let commit = crate::cluster::topology::TopologyCommit {
            term: 2,
            // Matches the fixture table's rf (1) — the rf-mismatch gate
            // rejects a commit whose rf differs from the authority's.
            rf: 1,
            assignment: None,
            proposer: NodeId(1),
            members: surviving.clone(),
            cluster_id: cid,
            placement_version: 1,
            committed_peak: surviving.len() as u64,
            digest: crate::cluster::topology::TopologyTerm::compute_digest(
                2,
                &cid,
                &surviving,
                1,
                surviving.len() as u64,
                1,
                crate::cluster::topology::ASSIGNMENT_ABSENT_DIGEST,
            ),
            voters: surviving,
        };
        (cluster, commit)
    }

    /// `shrink_lowers_effective_coordinator_floor` — RED pre-fix / GREEN
    /// post-fix.
    ///
    /// Pre-fix, `RunningCluster::peak_cluster_size()` computed
    /// `max(peak_size_atom, authority.peak_cluster_size())`. The
    /// coordinator's own `peak_size` atom is monotonic-only (raised by SWIM
    /// bursts, never lowered), so after this exact 5→3 shrink it stayed at
    /// 5 and the getter kept reporting 5 even though the authority's OWN
    /// `committed_peak` had correctly dropped to 3 — the shrink never took
    /// effect at the coordinator/quorum-gating level (this assertion FAILED
    /// with `left: 5, right: 3` before the collapse fix). Post-fix, the
    /// authority is the sole floor source, so the getter reflects the
    /// lowered peak immediately.
    #[test]
    fn shrink_lowers_effective_coordinator_floor() {
        let (cluster, commit) = shrink_5_to_3_fixture();

        let outcome = cluster.apply_committed_topology_durable(&commit);
        assert_eq!(
            outcome,
            crate::cluster::topology::DurableCommitOutcome::Applied(2),
            "a Gate-B-satisfying 5\u{2192}3 shrink commit must apply",
        );

        assert_eq!(
            cluster.peak_cluster_size(),
            3,
            "coordinator floor must reflect the lowered committed_peak (3), \
             not the stale SWIM-fed peak_size atom (5) — the shrink must \
             take effect end-to-end, not just inside the authority",
        );

        // A subsequent activation's quorum arithmetic (mirrors
        // `server::dispatch::check_quorum`) must derive from the new floor.
        let quorum_needed = (cluster.peak_cluster_size() / 2) + 1;
        assert_eq!(
            quorum_needed, 2,
            "post-shrink activation quorum must be derived from peak=3 (needs \
             2), not the stale peak=5 (which would need 3)",
        );

        // Defense-in-depth: the legacy `peak_size` atom itself must also be
        // hard-reset, not merely out-voted by the getter collapse.
        assert_eq!(
            cluster.peak_size.load(Ordering::Relaxed),
            3,
            "peak_size atom must be hard-reset to the new floor on shrink \
             apply, not left stale at 5",
        );
    }

    /// `observed_peak_does_not_reinflate_from_removed_node_rumor` — HARD
    /// REQUIREMENT: a lingering SWIM rumor about a removed node must not
    /// re-inflate the floor a shrink just lowered.
    ///
    /// Proves both halves: (1) force-evict — nodes 4 and 5 no longer read
    /// Alive/Suspect in the local SWIM view once the shrink applies, and (2)
    /// re-observing whatever the (now correctly reduced) alive set reports
    /// — exactly what a real `ClusterEvent::MembershipChanged` handler would
    /// feed into `observe_peak_cluster_size` — does not raise the floor back
    /// toward the stale pre-shrink peak of 5.
    #[test]
    fn observed_peak_does_not_reinflate_from_removed_node_rumor() {
        let (cluster, commit) = shrink_5_to_3_fixture();
        let outcome = cluster.apply_committed_topology_durable(&commit);
        assert_eq!(
            outcome,
            crate::cluster::topology::DurableCommitOutcome::Applied(2)
        );
        assert_eq!(cluster.peak_cluster_size(), 3);

        let alive_now = cluster.test_swim_alive_members();
        assert!(
            !alive_now.contains(&NodeId(4)) && !alive_now.contains(&NodeId(5)),
            "shrink-removed nodes 4 and 5 must be force-evicted (Dead) from \
             the local SWIM view, not still reported Alive/Suspect; got {alive_now:?}",
        );

        // Simulate exactly what the event loop's MembershipChanged handler
        // feeds into observe_peak_cluster_size right after the shrink: the
        // (post-evict) alive count. If eviction had not run, this would
        // still be 5 (nodes 4/5 still Alive) and this call would re-inflate
        // the floor straight back to 5.
        cluster
            .topology_authority
            .observe_peak_cluster_size(alive_now.len() as u64);
        assert_eq!(
            cluster.peak_cluster_size(),
            3,
            "observing the post-evict alive count must not re-inflate the \
             floor back toward the stale pre-shrink peak of 5",
        );
    }

    /// After a shrink, a full persist→restore round trip (simulating a
    /// restart) must keep the LOWERED peak — not resurrect the pre-shrink
    /// value via the vestigial `peak_cluster_size` field or the
    /// `.multinode` marker.
    #[test]
    fn restore_after_shrink_keeps_lowered_peak() {
        let dir = tempfile::tempdir().expect("tempdir");
        let topo_path = dir.path().join("node.cluster.topo");

        let (cluster, commit) = shrink_5_to_3_fixture();

        // Seed disk with the PRE-shrink (5-member) state, mirroring what a
        // real node would have persisted before the shrink commits. This
        // also creates the `.multinode` marker (5-member evidence).
        let pre_state = cluster.topology_authority.persisted_state(5, 1);
        persist_topology_state(&topo_path, &pre_state).expect("seed persist");
        assert!(
            load_topology_multi_node_marker_peak(&topo_path).is_some(),
            "seed persist must create the .multinode marker",
        );

        // Apply the shrink through the DURABLE path so the on-disk state
        // reflects the post-shrink floor.
        let outcome = cluster
            .topology_authority
            .handle_commit_durable(&commit, 5, 1, |state| {
                persist_topology_state(&topo_path, state).is_ok()
            });
        assert_eq!(
            outcome,
            crate::cluster::topology::DurableCommitOutcome::Applied(2)
        );

        let loaded = load_topology_state(&topo_path).expect("state file must load");
        assert_eq!(
            loaded.committed_peak, 3,
            "loaded committed_peak must be the lowered 3, not 5",
        );

        // Simulate a restart: restore from the loaded state into a FRESH
        // authority (a brand-new process would never see the in-memory
        // cluster from `shrink_5_to_3_fixture` above).
        let fresh =
            crate::cluster::topology::TopologyAuthority::new(NodeId(1), Duration::from_secs(1), 2);
        fresh.restore(&loaded);
        assert_eq!(
            fresh.peak_cluster_size(),
            3,
            "restore must NOT resurrect the pre-shrink peak of 5",
        );
    }

    /// The `.multinode` marker is a PRESENCE-only flag: its effect is a
    /// FIXED floor of exactly 2, never the historical peak (e.g. 5) it was
    /// originally written for. This is what distinguishes stage 3 from the
    /// pre-fix monotonic-growth marker, which would have resurrected the
    /// full pre-shrink peak on every restart regardless of what the
    /// freshest `.topo` file itself reported.
    #[test]
    fn multinode_marker_floors_at_2_not_old_peak() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("node.cluster.topo");

        // Seed evidence + marker from a 5-member cluster.
        let five_member = crate::cluster::topology::PersistedTopologyState {
            peak_cluster_size: 5,
            committed_term: 1,
            committed_members: vec![NodeId(1), NodeId(2), NodeId(3), NodeId(4), NodeId(5)],
            committed_voters: vec![NodeId(1), NodeId(2), NodeId(3), NodeId(4), NodeId(5)],
            voted_term: 1,
            incarnation: 0,
            committed_voter_ever_seen: Vec::new(),
            committed_placement_version: 1,
            committed_peak: 5,
            committed_commit: None,
            voted_digest: None,
        };
        persist_topology_state(&path, &five_member).expect("seed persist creates marker");

        // A later shrink overwrites the `.topo` file directly with a
        // genuinely-smaller 3-member state (the marker is presence-only and
        // never re-derives a number from its own stored content, so it is
        // NOT rewritten here — this models the marker surviving untouched
        // across an ordinary, non-terminal shrink).
        let three_member = crate::cluster::topology::PersistedTopologyState {
            peak_cluster_size: 1,
            committed_term: 2,
            committed_members: vec![NodeId(1), NodeId(2), NodeId(3)],
            committed_voters: vec![NodeId(1), NodeId(2), NodeId(3)],
            voted_term: 2,
            incarnation: 0,
            committed_voter_ever_seen: Vec::new(),
            committed_placement_version: 1,
            committed_peak: 1, // pretend the raw .topo content under-reports
            committed_commit: None,
            voted_digest: None,
        };
        std::fs::write(&path, three_member.serialize()).expect("overwrite .topo directly");

        let loaded = load_topology_state(&path).expect("state file must load");
        assert_eq!(
            loaded.committed_peak, 2,
            "marker floors committed_peak at exactly 2, not the old peak of \
             5 the marker was originally written for",
        );
        assert_eq!(
            loaded.peak_cluster_size, 2,
            "marker floors peak_cluster_size at exactly 2 too",
        );
    }

    /// A GENUINE 1-member `.topo` file (the unforgeable signature of a
    /// completed, quorum-approved RF=1 terminal shrink — Gate B makes an
    /// accidental/minority 1-member commit unreachable) must NOT be floored
    /// by a lingering `.multinode` marker, even if the marker's own delete
    /// (tied to the shrink-to-1 commit) hasn't landed yet. Otherwise RF=1 is
    /// unreachable after the very first restart: `ClusterCoordinator::new`
    /// folds the loaded `initial_peak` into the authority via a MONOTONIC
    /// `observe_peak_cluster_size`, so even the marker's fixed floor of 2
    /// can never be un-observed once seeded.
    #[test]
    fn multinode_marker_does_not_block_genuine_rf1_restart() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.path().join("node.cluster.topo");

        let multi = crate::cluster::topology::PersistedTopologyState {
            peak_cluster_size: 3,
            committed_term: 1,
            committed_members: vec![NodeId(1), NodeId(2), NodeId(3)],
            committed_voters: vec![NodeId(1), NodeId(2), NodeId(3)],
            voted_term: 1,
            incarnation: 0,
            committed_voter_ever_seen: Vec::new(),
            committed_placement_version: 1,
            committed_peak: 3,
            committed_commit: None,
            voted_digest: None,
        };
        persist_topology_state(&path, &multi).expect("seed persist creates marker");
        assert!(load_topology_multi_node_marker_peak(&path).is_some());

        // A completed RF=1 shrink overwrites the `.topo` file with a genuine
        // 1-member state but (simulating the residual crash race between
        // committing the shrink and the marker-delete's own fsync) the
        // marker delete has NOT landed yet.
        let rf1 = crate::cluster::topology::PersistedTopologyState {
            peak_cluster_size: 1,
            committed_term: 2,
            committed_members: vec![NodeId(1)],
            committed_voters: vec![NodeId(1)],
            voted_term: 2,
            incarnation: 0,
            committed_voter_ever_seen: Vec::new(),
            committed_placement_version: 1,
            committed_peak: 1,
            committed_commit: None,
            voted_digest: None,
        };
        std::fs::write(&path, rf1.serialize()).expect("overwrite with RF=1 state");

        let loaded = load_topology_state(&path).expect("state file must load");
        assert_eq!(
            loaded.committed_peak, 1,
            "a genuine 1-member .topo file must be trusted over a lingering \
             marker — otherwise RF=1 is unreachable after restart",
        );
    }

    #[test]
    fn empty_shard_completion_failure_rolls_back_master_handoff() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master != new_table.target_assignment(s).master
            })
            .expect("expected a shard whose master moves");
        let old_master = old_table.target_assignment(shard).master;
        let new_master = new_table.target_assignment(shard).master;
        let task = MigrationTask {
            shard,
            from_node: old_master,
            to_node: new_master,
            is_master: true,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| s == shard);
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(4 * 1024 * 1024, 4096).unwrap());
        let alloc = crate::allocator::SlotAllocator::new(dev.clone()).unwrap();
        let index = crate::index::Index::new(128).unwrap();
        let engine = Arc::new(crate::ops::engine::Engine::new(
            dev,
            index,
            alloc,
            crate::locks::StripedLocks::new(64),
            crate::index::DahIndex::new(),
        ));

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            old_master,
            &std::collections::HashSet::new(),
        );

        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(shard);
        let inbound_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        drop(listener);

        run_migration_batch(
            vec![task],
            Some(target_addr),
            &[],
            engine,
            &migration,
            &shard_table,
            &None,
            new_table.version,
            1,
            100,
            fenced_bm,
            migrating_bm,
            inbound_bm,
            old_master,
            None,
            None,
        );

        let table = shard_table.read();
        assert_eq!(
            table.target_assignment(shard).master,
            old_master,
            "the source must not commit a master handoff when the completion signal cannot be delivered"
        );
    }

    /// W8 (defect 1) — a batch disposition that ends with failed tasks at a
    /// still-current epoch must ARM the failed-batch self-retry signal
    /// (`MigrationManager::arm_failed_batch_retry`) so the event loop can
    /// observe the event-repair trigger and schedule the delayed re-drive.
    /// Pre-fix the disposition only logged "awaiting explicit retry on
    /// membership/topology change" — an edge a settled cluster never produces
    /// (runs 31946515845/31946519864: 8 failed shards' one-holder records
    /// never converged).
    #[test]
    fn failed_batch_disposition_arms_self_retry() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master != new_table.target_assignment(s).master
            })
            .expect("expected a shard whose master moves");
        let old_master = old_table.target_assignment(shard).master;
        let new_master = new_table.target_assignment(shard).master;
        let task = MigrationTask {
            shard,
            from_node: old_master,
            to_node: new_master,
            is_master: true,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| s == shard);
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(4 * 1024 * 1024, 4096).unwrap());
        let alloc = crate::allocator::SlotAllocator::new(dev.clone()).unwrap();
        let index = crate::index::Index::new(128).unwrap();
        let engine = Arc::new(crate::ops::engine::Engine::new(
            dev,
            index,
            alloc,
            crate::locks::StripedLocks::new(64),
            crate::index::DahIndex::new(),
        ));

        // A record in the moving shard puts the batch on the DATA path — the
        // observed defect's shape (a resync batch with records failing against
        // an unreachable target).
        let record_key = tx_key_for_shard(shard, 7);
        create_test_record(&engine, record_key);

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            old_master,
            &std::collections::HashSet::new(),
        );

        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(shard);
        let inbound_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        // Unreachable target: bind a listener for a free port, then drop it so
        // the batch's connect fails and the task resolves Failed.
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        drop(listener);

        let (c, f) = run_migration_batch(
            vec![task],
            Some(target_addr),
            &[record_key],
            engine,
            &migration,
            &shard_table,
            &None,
            new_table.version,
            1,
            100,
            fenced_bm,
            migrating_bm,
            inbound_bm,
            old_master,
            None,
            None,
        );
        assert_eq!(c, 0);
        assert!(f > 0, "the batch must have resolved the task as Failed");

        let mut mgr = migration.lock();
        assert!(
            mgr.failed_count() > 0,
            "the failed task must sit in the durable retry queue"
        );
        assert!(
            mgr.take_failed_batch_retry_arm(),
            "a failed disposition at a current epoch must arm the self-retry"
        );
        assert!(
            !mgr.take_failed_batch_retry_arm(),
            "the arm is one-shot until the next failed disposition"
        );
    }

