    #[test]
    fn empty_shard_completion_retries_until_target_is_ready() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master != new_table.target_assignment(s).master
            })
            .expect("expected a shard whose master moves");
        let old_master = old_table.target_assignment(shard).master;
        let new_master = new_table.target_assignment(shard).master;
        let task = MigrationTask {
            shard,
            from_node: old_master,
            to_node: new_master,
            is_master: true,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| s == shard);
        assert_eq!(
            handoff.shard_handoff_state(shard),
            ShardHandoff::Copying,
            "the shard must take the empty-shard handoff path"
        );
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(4 * 1024 * 1024, 4096).unwrap());
        let alloc = crate::allocator::SlotAllocator::new(dev.clone()).unwrap();
        let index = crate::index::Index::new(128).unwrap();
        let engine = Arc::new(crate::ops::engine::Engine::new(
            dev,
            index,
            alloc,
            crate::locks::StripedLocks::new(64),
            crate::index::DahIndex::new(),
        ));

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            old_master,
            &std::collections::HashSet::new(),
        );

        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(shard);
        let inbound_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        drop(listener);
        let (request_tx, request_rx) = std::sync::mpsc::channel();
        let receiver = std::thread::spawn(move || {
            use std::io::{Read, Write};

            // Fresh Docker nodes can take a couple of seconds before they
            // accept migration-complete handshakes during cluster bootstrap.
            std::thread::sleep(Duration::from_millis(2500));
            let listener = std::net::TcpListener::bind(target_addr).unwrap();
            let (mut stream, _) = listener.accept().unwrap();

            let mut header = [0u8; 4];
            stream.read_exact(&mut header).unwrap();
            let payload_len = u32::from_le_bytes(header) as usize;
            let mut rest = vec![0u8; payload_len];
            stream.read_exact(&mut rest).unwrap();

            let mut frame_bytes = header.to_vec();
            frame_bytes.extend_from_slice(&rest);
            let (request, _) = RequestFrame::decode(&frame_bytes).unwrap();
            request_tx
                .send((request.op_code, request.request_id))
                .unwrap();

            let response = ResponseFrame {
                request_id: request.request_id,
                status: STATUS_OK,
                payload: Vec::new(),
            };
            stream.write_all(&response.encode()).unwrap();
        });

        run_migration_batch(
            vec![task.clone()],
            Some(target_addr),
            &[],
            engine,
            &migration,
            &shard_table,
            &None,
            new_table.version,
            1,
            100,
            fenced_bm,
            migrating_bm,
            inbound_bm,
            old_master,
            None,
            None,
        );

        let (op, _req_id) = request_rx.recv_timeout(Duration::from_secs(5)).unwrap();
        assert!(
            op == OP_MIGRATION_COMPLETE || op == OP_MIGRATION_BATCH_COMPLETE,
            "empty-shard migrations must retry the completion handshake until the target can acknowledge it (got op {op})"
        );
        receiver.join().unwrap();
    }

    /// Pipelined-flow analogue of the legacy abort-completion-handshake
    /// test. On baseline streaming failure, the pipelined flow
    /// (`run_migration_batch`) does NOT emit a zero-record
    /// OP_MIGRATION_COMPLETE abort frame (the now-removed legacy per-shard
    /// path emitted one via `fail_shard(true)`).
    /// Instead the pipelined flow marks the task failed locally and
    /// rolls back the shard table; the target eventually clears its
    /// provisional inbound state via `clear_stale_inbound`'s 30 s
    /// timeout (EF-15). This test pins that contract: when streaming
    /// fails, the migration ends up `Failed` locally and `migrating_bm`
    /// is cleared. R-213 (new finding) tracks the work to make the
    /// pipelined flow also emit an abort frame so target inbound state
    /// clears immediately rather than waiting for the staleness timeout.
    #[test]
    fn failed_data_migration_marks_task_failed_in_pipelined_flow() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master != new_table.target_assignment(s).master
            })
            .expect("expected a shard whose master moves");
        let old_master = old_table.target_assignment(shard).master;
        let new_master = new_table.target_assignment(shard).master;
        let task = MigrationTask {
            shard,
            from_node: old_master,
            to_node: new_master,
            is_master: true,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| s == shard);
        assert_eq!(
            handoff.shard_handoff_state(shard),
            ShardHandoff::Copying,
            "the shard must take the data-migration path"
        );
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(4 * 1024 * 1024, 4096).unwrap());
        let alloc = crate::allocator::SlotAllocator::new(dev.clone()).unwrap();
        let index = crate::index::Index::new(128).unwrap();
        let engine = Arc::new(crate::ops::engine::Engine::new(
            dev,
            index,
            alloc,
            crate::locks::StripedLocks::new(64),
            crate::index::DahIndex::new(),
        ));

        let tx_id = {
            let mut nonce = 0u64;
            loop {
                let mut tx_id = [0u8; 32];
                tx_id[..8].copy_from_slice(&nonce.to_le_bytes());
                if ShardTable::shard_for_key(&TxKey { txid: tx_id }) == shard {
                    break tx_id;
                }
                nonce += 1;
            }
        };
        let key = TxKey { txid: tx_id };
        let utxo_hashes = [[0x33u8; 32]];
        engine
            .create(&crate::ops::create::CreateRequest {
                tx_id,
                tx_version: 1,
                locktime: 0,
                fee: 100,
                size_in_bytes: 100,
                extended_size: 0,
                is_coinbase: false,
                spending_height: 0,
                utxo_hashes: &utxo_hashes,
                inputs: None,
                outputs: None,
                inpoints: None,
                is_external: false,
                created_at: 1710000000000,
                block_height: 0,
                mined_block_infos: &[],
                frozen: false,
                conflicting: false,
                locked: false,
                external_ref: None,
                parent_txids: &[],
            })
            .unwrap();
        assert_eq!(engine.shard_record_count(shard), 1);

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let populated: std::collections::HashSet<u16> = [shard].into_iter().collect();
        migration
            .lock()
            .start_outbound(std::slice::from_ref(&task), old_master, &populated);

        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(shard);
        let inbound_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        // "Target dies mid-baseline" failure: accept connections, read each
        // frame, then drop the connection without replying. The source's
        // `exchange_frame` errors on the unread response and `streamed[i]`
        // ends up `false`, which drives the pipelined-flow failure path.
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        let (abort_tx, abort_rx) = std::sync::mpsc::channel();
        let receiver = std::thread::spawn(move || {
            use std::io::{Read, Write};

            listener
                .set_nonblocking(true)
                .expect("non-blocking accept loop with deadline");
            let deadline = std::time::Instant::now() + Duration::from_secs(6);
            'accept_loop: while std::time::Instant::now() < deadline {
                let (mut stream, _) = match listener.accept() {
                    Ok(pair) => pair,
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(Duration::from_millis(10));
                        continue;
                    }
                    Err(_) => continue,
                };
                stream
                    .set_nonblocking(false)
                    .expect("blocking stream for read_exact");
                stream
                    .set_read_timeout(Some(Duration::from_millis(500)))
                    .unwrap();

                let mut header = [0u8; 4];
                if stream.read_exact(&mut header).is_err() {
                    continue 'accept_loop;
                }
                let payload_len = u32::from_le_bytes(header) as usize;
                let mut rest = vec![0u8; payload_len];
                if stream.read_exact(&mut rest).is_err() {
                    continue 'accept_loop;
                }
                let mut frame_bytes = header.to_vec();
                frame_bytes.extend_from_slice(&rest);
                if let Ok((request, _)) = RequestFrame::decode(&frame_bytes)
                    && request.op_code == OP_MIGRATION_COMPLETE
                    && request.payload.len() >= 8
                {
                    let record_count = u64::from_le_bytes(request.payload[..8].try_into().unwrap());
                    if record_count == 0 {
                        let _ = abort_tx.send(request.request_id);
                    }
                    let response = ResponseFrame {
                        request_id: request.request_id,
                        status: STATUS_OK,
                        payload: Vec::new(),
                    };
                    let _ = stream.write_all(&response.encode());
                    break 'accept_loop;
                }
                // Drop the connection without replying — the source's
                // `exchange_frame` errors and the pipelined worker marks
                // the migration failed.
            }
        });

        run_migration_batch(
            vec![task.clone()],
            Some(target_addr),
            &[key],
            engine,
            &migration,
            &shard_table,
            &None,
            new_table.version,
            1,
            100,
            fenced_bm.clone(),
            migrating_bm.clone(),
            inbound_bm,
            old_master,
            None,
            None,
        );

        // Pipelined-flow failure contract observed immediately after
        // `run_migration_batch` returns:
        //   1. `migrating_bm` is cleared by `fail_migration_task_current_epoch`
        //      so writes can resume on the source.
        //   2. The shard handoff is rolled back to `ServingNew` (with the
        //      OLD assignment restored), routing requests back to the old
        //      master.
        //   3. The migration entry remains visible as `Failed` so the
        //      membership/topology retry path can pick it up explicitly.
        // Target's inbound state lingers until `clear_stale_inbound`'s 30 s
        // timeout fires — see R-213 for the gap that the pipelined flow
        // does NOT proactively send an abort completion handshake.
        assert!(
            !migrating_bm.test(shard),
            "after baseline failure migrating_bm must be cleared so writes can resume"
        );
        assert_eq!(
            shard_table.read().shard_handoff_state(shard),
            ShardHandoff::ServingNew,
            "after baseline failure the shard table must be rolled back to the old assignment"
        );
        let abort_request_id = abort_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("baseline failure must emit a zero-record migration-complete abort");
        assert_eq!(abort_request_id, u64::from(shard));
        let mgr = migration.lock();
        let active = mgr.active_migrations();
        assert!(
            active.iter().any(|p| {
                p.shard == shard
                    && p.from_node == task.from_node
                    && p.to_node == task.to_node
                    && p.is_master == task.is_master
                    && p.state == crate::cluster::migration::MigrationState::Failed
            }),
            "the migration entry must still be tracked as Failed for explicit retry; \
             mgr.active_migrations = {active:?}"
        );
        drop(mgr);
        receiver.join().unwrap();
    }

    /// W4 (run 31904708491 scenario 09) — a worker-level abort must not leave
    /// its remaining tasks stranded in a non-terminal state, holding the
    /// same-term re-heal gate (`active_count() == 0` in the event loop's
    /// reactivation block) shut forever.
    ///
    /// Repro shape: two data-shard tasks share one worker chunk; the target
    /// rejects the FIRST baseline with the `ERR_STALE_EPOCH` envelope, so the
    /// worker takes the "peer reports our epoch is superseded" early return —
    /// with the LOCAL table still current (the observed node3 state: 46 such
    /// aborts, 1689 entries frozen in `Preparing`/`Streaming`, `failed_count`
    /// 0, and no re-heal ever firing again). Before the fix both entries
    /// stayed non-terminal after `run_migration_batch` returned; the
    /// batch-end sweep must park them as `Failed` (the durable retry queue),
    /// clear the hot-path bitmaps, and roll the master handoffs back to self
    /// so `active_count()` drains and the re-heal machinery re-plans on its
    /// normal cadence.
    #[test]
    fn peer_superseded_worker_abort_parks_stranded_tasks_and_reopens_the_reheal_gate() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let moving: Vec<u16> = (0..NUM_SHARDS as u16)
            .filter(|&s| {
                old_table.target_assignment(s).master == NodeId(1)
                    && new_table.target_assignment(s).master == NodeId(3)
            })
            .take(2)
            .collect();
        assert_eq!(moving.len(), 2, "need two shards moving 1 -> 3");
        let tasks: Vec<MigrationTask> = moving
            .iter()
            .map(|&shard| MigrationTask {
                shard,
                from_node: NodeId(1),
                to_node: NodeId(3),
                is_master: true,
            })
            .collect();

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| moving.contains(&s));
        for &s in &moving {
            assert_eq!(
                handoff.shard_handoff_state(s),
                ShardHandoff::Copying,
                "both shards must take the data-migration path"
            );
        }
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(4 * 1024 * 1024, 4096).unwrap());
        let alloc = crate::allocator::SlotAllocator::new(dev.clone()).unwrap();
        let index = crate::index::Index::new(128).unwrap();
        let engine = Arc::new(crate::ops::engine::Engine::new(
            dev,
            index,
            alloc,
            crate::locks::StripedLocks::new(64),
            crate::index::DahIndex::new(),
        ));

        // One record per shard so both tasks are DATA tasks (the worker's
        // Phase-1 baseline loop is where the peer-superseded abort lives).
        let mut keys = Vec::new();
        for &shard in &moving {
            let mut nonce = 0u64;
            let tx_id = loop {
                let mut tx_id = [0u8; 32];
                tx_id[..8].copy_from_slice(&nonce.to_le_bytes());
                tx_id[8..16].copy_from_slice(&u64::from(shard).to_le_bytes());
                if ShardTable::shard_for_key(&TxKey { txid: tx_id }) == shard {
                    break tx_id;
                }
                nonce += 1;
            };
            let utxo_hashes = [[0x44u8; 32]];
            engine
                .create(&crate::ops::create::CreateRequest {
                    tx_id,
                    tx_version: 1,
                    locktime: 0,
                    fee: 100,
                    size_in_bytes: 100,
                    extended_size: 0,
                    is_coinbase: false,
                    spending_height: 0,
                    utxo_hashes: &utxo_hashes,
                    inputs: None,
                    outputs: None,
                    inpoints: None,
                    is_external: false,
                    created_at: 1710000000000,
                    block_height: 0,
                    mined_block_infos: &[],
                    frozen: false,
                    conflicting: false,
                    locked: false,
                    external_ref: None,
                    parent_txids: &[],
                })
                .unwrap();
            keys.push(TxKey { txid: tx_id });
        }

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let populated: std::collections::HashSet<u16> = moving.iter().copied().collect();
        migration
            .lock()
            .start_outbound(&tasks, NodeId(1), &populated);

        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        for &s in &moving {
            migrating_bm.set(s);
        }
        let inbound_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        // Target that rejects the first baseline frame with the real
        // ERR_STALE_EPOCH envelope — the worker recognises it via
        // `migration_error_is_stale_epoch` and returns, abandoning the rest
        // of its chunk.
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        let receiver = std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            stream
                .set_read_timeout(Some(Duration::from_secs(5)))
                .unwrap();
            let mut header = [0u8; 4];
            stream.read_exact(&mut header).unwrap();
            let payload_len = u32::from_le_bytes(header) as usize;
            let mut rest = vec![0u8; payload_len];
            stream.read_exact(&mut rest).unwrap();
            let mut frame_bytes = header.to_vec();
            frame_bytes.extend_from_slice(&rest);
            let (request, _) = RequestFrame::decode(&frame_bytes).unwrap();
            let msg = b"stale cluster key";
            let mut payload = Vec::new();
            payload.extend_from_slice(&ERR_STALE_EPOCH.to_le_bytes());
            payload.extend_from_slice(&(msg.len() as u16).to_le_bytes());
            payload.extend_from_slice(msg);
            let response = ResponseFrame {
                request_id: request.request_id,
                status: 1,
                payload,
            };
            stream.write_all(&response.encode()).unwrap();
        });

        run_migration_batch(
            tasks.clone(),
            Some(target_addr),
            &keys,
            engine,
            &migration,
            &shard_table,
            &None,
            new_table.version,
            1,
            100,
            fenced_bm.clone(),
            migrating_bm.clone(),
            inbound_bm,
            NodeId(1),
            None,
            None,
        );
        receiver.join().unwrap();

        // THE deadlocked gate: the event loop's same-term re-heal only fires
        // when `active_count() == 0`. Stranded non-terminal entries held it
        // shut forever (observed: node1 288, node3 1689, both frozen).
        let mut mgr = migration.lock();
        assert_eq!(
            mgr.active_count(),
            0,
            "no task of a finished batch may stay non-terminal — stranded \
             entries hold the re-heal gate (active_count()==0) shut forever; \
             entries: {:?}",
            mgr.active_migrations(),
        );
        // The stranded tasks are PARKED, not lost: they join the Failed
        // durable retry queue the membership/topology re-drive consumes.
        assert_eq!(
            mgr.failed_count(),
            2,
            "both abandoned tasks must be parked as Failed for explicit retry"
        );
        let retry = mgr.take_failed_tasks();
        assert_eq!(
            retry.len(),
            2,
            "the parked tasks must remain re-drivable via take_failed_tasks"
        );
        drop(mgr);

        let table = shard_table.read();
        for &s in &moving {
            assert!(
                !migrating_bm.test(s),
                "shard {s}: migrating_bm must clear when its task is parked"
            );
            assert!(
                !fenced_bm.test(s),
                "shard {s}: no fence may remain once its task is parked"
            );
            assert_eq!(
                table.shard_handoff_state(s),
                ShardHandoff::ServingNew,
                "shard {s}: master handoff must roll back to the old assignment"
            );
            assert_eq!(
                table.target_assignment(s).master,
                NodeId(1),
                "shard {s}: the source must keep authority after the rollback"
            );
        }
    }

    /// W4 — the abandoned-task sweep must NOT touch a stale-epoch batch:
    /// the newer activation's stale-task cancel owns those entries, and a
    /// sweep could brush same-identity entries that activation has already
    /// re-registered.
    #[test]
    fn retire_abandoned_batch_tasks_is_a_no_op_for_a_stale_epoch_batch() {
        let members = vec![NodeId(1), NodeId(2)];
        // Table already advanced to version 3; the batch was planned at 2.
        let table = ShardTable::compute_with_epoch(&members, 2, 3, 1);
        let shard_table = Arc::new(ShardTableLock::new(table));
        let task = MigrationTask {
            shard: 9,
            from_node: NodeId(1),
            to_node: NodeId(2),
            is_master: true,
        };
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            NodeId(1),
            &std::collections::HashSet::new(),
        );
        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        let captured = migration
            .lock()
            .capture_task_attempts(std::slice::from_ref(&task));
        let parked = retire_abandoned_batch_tasks(
            &migration,
            &shard_table,
            &fenced_bm,
            &migrating_bm,
            &captured,
            2,
        );

        assert_eq!(parked, 0, "a stale-epoch batch must not be swept");
        let mgr = migration.lock();
        assert_eq!(
            mgr.active_count(),
            1,
            "the stale entry is left for the newer activation's cancel"
        );
        assert_eq!(mgr.failed_count(), 0);
    }

    /// W4 — table disposition of the sweep: a stranded MASTER handoff rolls
    /// its Copying shard back to the old assignment (no-loss), while a
    /// stranded REPLICA push leaves the table untouched (W3 FIX C:
    /// `rollback_shard` would revert the whole assignment while a master
    /// handoff may still be mid-Copying elsewhere).
    #[test]
    fn retire_abandoned_batch_tasks_rolls_back_master_but_not_replica() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let master_shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master == NodeId(1)
                    && new_table.target_assignment(s).master == NodeId(3)
            })
            .expect("need a master shard moving 1 -> 3");
        let replica_shard = (0..NUM_SHARDS as u16)
            .find(|&s| s != master_shard && new_table.target_assignment(s).master == NodeId(1))
            .expect("need a shard node1 keeps mastering (replica backfill source)");
        let master_task = MigrationTask {
            shard: master_shard,
            from_node: NodeId(1),
            to_node: NodeId(3),
            is_master: true,
        };
        let replica_task = MigrationTask {
            shard: replica_shard,
            from_node: NodeId(1),
            to_node: NodeId(3),
            is_master: false,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| s == master_shard);
        assert_eq!(
            handoff.shard_handoff_state(master_shard),
            ShardHandoff::Copying
        );
        let shard_table = Arc::new(ShardTableLock::new(handoff));
        let replica_master_before = shard_table.read().target_assignment(replica_shard).master;

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().start_outbound(
            &[master_task.clone(), replica_task.clone()],
            NodeId(1),
            &std::collections::HashSet::new(),
        );
        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(master_shard);
        migrating_bm.set(replica_shard);

        let captured = migration
            .lock()
            .capture_task_attempts(&[master_task.clone(), replica_task.clone()]);
        let parked = retire_abandoned_batch_tasks(
            &migration,
            &shard_table,
            &fenced_bm,
            &migrating_bm,
            &captured,
            new_table.version,
        );

        assert_eq!(parked, 2, "both stranded tasks must be parked");
        let mgr = migration.lock();
        assert_eq!(mgr.active_count(), 0, "the re-heal gate condition reopens");
        assert_eq!(mgr.failed_count(), 2);
        drop(mgr);
        assert!(!migrating_bm.test(master_shard));
        assert!(!migrating_bm.test(replica_shard));
        let table = shard_table.read();
        assert_eq!(
            table.shard_handoff_state(master_shard),
            ShardHandoff::ServingNew,
            "the master handoff must roll back"
        );
        assert_eq!(
            table.target_assignment(master_shard).master,
            NodeId(1),
            "the source keeps authority for the rolled-back master shard"
        );
        assert_eq!(
            table.target_assignment(replica_shard).master,
            replica_master_before,
            "a replica push must not revert the shard's assignment (W3 FIX C)"
        );
    }

    /// W4 review P1 — the overlap window: batch A's end-of-batch sweep runs
    /// while the NodeJoined failed-task retry has already RE-DRIVEN one of
    /// A's tasks in place (`take_failed_tasks` -> `retry_failed` resets the
    /// SAME entry to Streaming at the same epoch — no new entry, no term
    /// bump). A's sweep must recognise the entry as re-owned (its
    /// drive-attempt stamp moved past A's capture) and leave it alone:
    /// parking it would lift retry batch B's fence mid
    /// fence-to-completion window, roll the shard back, and let unfenced
    /// source writes race B's committed manifest — the orphan-cleanup
    /// data-loss chain the reviewer traced.
    #[test]
    fn sweep_skips_an_entry_re_driven_by_the_failed_task_retry() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master == NodeId(1)
                    && new_table.target_assignment(s).master == NodeId(3)
            })
            .expect("need a master shard moving 1 -> 3");
        let task = MigrationTask {
            shard,
            from_node: NodeId(1),
            to_node: NodeId(3),
            is_master: true,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| s == shard);
        assert_eq!(handoff.shard_handoff_state(shard), ShardHandoff::Copying);
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            NodeId(1),
            &std::collections::HashSet::new(),
        );
        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(shard);

        // Batch A registers and captures its tasks' drive-attempt stamps.
        let batch_a_capture = migration
            .lock()
            .capture_task_attempts(std::slice::from_ref(&task));
        assert_eq!(batch_a_capture.len(), 1);

        // A's worker fails the task mid-batch; before A's other tasks drain,
        // a NodeJoined retry re-drives it IN PLACE (same entry, same epoch)
        // and spawns retry batch B.
        {
            let mut mgr = migration.lock();
            mgr.mark_failed(&task);
            let retried = mgr.take_failed_tasks();
            assert_eq!(retried.len(), 1, "the retry must pick the task up");
        }

        // A's end-of-batch sweep runs with its STALE capture while B owns
        // the entry (currently Streaming).
        let parked = retire_abandoned_batch_tasks(
            &migration,
            &shard_table,
            &fenced_bm,
            &migrating_bm,
            &batch_a_capture,
            new_table.version,
        );
        assert_eq!(
            parked, 0,
            "the sweep must not park an entry the failed-task retry re-drove"
        );
        {
            let mgr = migration.lock();
            let entry = mgr
                .active_migrations()
                .iter()
                .find(|p| p.shard == shard)
                .expect("the re-driven entry must survive A's sweep");
            assert_eq!(
                entry.state,
                crate::cluster::migration::MigrationState::Streaming,
                "B's re-driven entry must stay Streaming, not be parked as Failed"
            );
            assert_eq!(mgr.failed_count(), 0);
        }
        assert_eq!(
            shard_table.read().shard_handoff_state(shard),
            ShardHandoff::Copying,
            "A's sweep must not roll back the shard B is actively migrating"
        );

        // Worst case from the review: B has advanced into its
        // fence-to-completion window. A's stale sweep must not lift the fence.
        {
            let mut mgr = migration.lock();
            mgr.fence_shard(shard);
            mgr.mark_fenced(&task, 42);
        }
        fenced_bm.set(shard);
        let parked = retire_abandoned_batch_tasks(
            &migration,
            &shard_table,
            &fenced_bm,
            &migrating_bm,
            &batch_a_capture,
            new_table.version,
        );
        assert_eq!(parked, 0, "the fenced re-driven entry must also be skipped");
        {
            let mgr = migration.lock();
            assert!(
                mgr.is_shard_fenced(shard),
                "B's write fence must survive A's stale sweep"
            );
        }
        assert!(
            fenced_bm.test(shard),
            "the hot-path fence bit must survive A's stale sweep"
        );
        assert_eq!(
            shard_table.read().shard_handoff_state(shard),
            ShardHandoff::Copying,
            "the shard must stay in B's handoff after the fenced-window sweep"
        );
    }

    /// Variant of the pipelined-failure test: target never reads or replies
    /// (silent drop). Verifies the source's connect/retry path eventually
    /// gives up cleanly without panicking and the migration is marked failed.
    #[test]
    fn pipelined_migration_marks_failed_when_target_never_acks() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master != new_table.target_assignment(s).master
            })
            .expect("expected a shard whose master moves");
        let old_master = old_table.target_assignment(shard).master;
        let new_master = new_table.target_assignment(shard).master;
        let task = MigrationTask {
            shard,
            from_node: old_master,
            to_node: new_master,
            is_master: true,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| s == shard);
        assert_eq!(handoff.shard_handoff_state(shard), ShardHandoff::Copying);
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(4 * 1024 * 1024, 4096).unwrap());
        let alloc = crate::allocator::SlotAllocator::new(dev.clone()).unwrap();
        let index = crate::index::Index::new(128).unwrap();
        let engine = Arc::new(crate::ops::engine::Engine::new(
            dev,
            index,
            alloc,
            crate::locks::StripedLocks::new(64),
            crate::index::DahIndex::new(),
        ));

        // Seed one record on the migrating shard so the migration takes the
        // data path (rather than the empty-shard fast path).
        let tx_id = {
            let mut nonce = 0u64;
            loop {
                let mut tx_id = [0u8; 32];
                tx_id[..8].copy_from_slice(&nonce.to_le_bytes());
                if ShardTable::shard_for_key(&TxKey { txid: tx_id }) == shard {
                    break tx_id;
                }
                nonce += 1;
            }
        };
        let key = TxKey { txid: tx_id };
        let utxo_hashes = [[0x55u8; 32]];
        engine
            .create(&crate::ops::create::CreateRequest {
                tx_id,
                tx_version: 1,
                locktime: 0,
                fee: 100,
                size_in_bytes: 100,
                extended_size: 0,
                is_coinbase: false,
                spending_height: 0,
                utxo_hashes: &utxo_hashes,
                inputs: None,
                outputs: None,
                inpoints: None,
                is_external: false,
                created_at: 1710000000000,
                block_height: 0,
                mined_block_infos: &[],
                frozen: false,
                conflicting: false,
                locked: false,
                external_ref: None,
                parent_txids: &[],
            })
            .unwrap();

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let populated: std::collections::HashSet<u16> = [shard].into_iter().collect();
        migration
            .lock()
            .start_outbound(std::slice::from_ref(&task), old_master, &populated);

        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(shard);
        let inbound_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        // Receiver: drop every connection without ever replying to anything.
        // The source's baseline retries fail; the final abort completion is
        // sent on a fresh connection that we also accept-and-drop. The test
        // checks the source attempted to emit the abort handshake even when
        // ACKs are lost.
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        let receiver = std::thread::spawn(move || {
            use std::io::Read;

            listener
                .set_nonblocking(true)
                .expect("non-blocking accept loop");
            let deadline = std::time::Instant::now() + Duration::from_secs(8);
            'accept_loop: while std::time::Instant::now() < deadline {
                let (mut stream, _) = match listener.accept() {
                    Ok(pair) => pair,
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(Duration::from_millis(10));
                        continue;
                    }
                    Err(_) => continue,
                };
                stream.set_nonblocking(false).unwrap();
                stream
                    .set_read_timeout(Some(Duration::from_millis(300)))
                    .unwrap();

                // Read one frame so the source sees its request was received,
                // then drop the connection without replying. No ACK is ever
                // delivered — the source must give up cleanly.
                let mut header = [0u8; 4];
                if stream.read_exact(&mut header).is_err() {
                    continue 'accept_loop;
                }
                let payload_len = u32::from_le_bytes(header) as usize;
                let mut rest = vec![0u8; payload_len];
                if stream.read_exact(&mut rest).is_err() {
                    continue 'accept_loop;
                }
                // Stream drops here, no reply.
            }
        });

        run_migration_batch(
            vec![task.clone()],
            Some(target_addr),
            &[key],
            engine,
            &migration,
            &shard_table,
            &None,
            new_table.version,
            1,
            100,
            fenced_bm,
            migrating_bm.clone(),
            inbound_bm,
            old_master,
            None,
            None,
        );

        // Silent-drop variant of the pipelined failure contract. The
        // observables match `failed_data_migration_marks_task_failed_in_pipelined_flow`:
        // migrating_bm cleared, shard_table rolled back, failure retained. The
        // additional thing this variant proves is that the source does not
        // panic or hang when the target silently drops every connection.
        // See R-213 for the gap that the pipelined flow does NOT send an
        // abort completion handshake.
        assert!(
            !migrating_bm.test(shard),
            "after silent target drops migrating_bm must be cleared so writes can resume"
        );
        assert_eq!(
            shard_table.read().shard_handoff_state(shard),
            ShardHandoff::ServingNew,
            "after silent target drops the shard table must be rolled back"
        );
        let mgr = migration.lock();
        let active = mgr.active_migrations();
        assert!(
            active.iter().any(|p| {
                p.shard == shard
                    && p.from_node == task.from_node
                    && p.to_node == task.to_node
                    && p.is_master == task.is_master
                    && p.state == crate::cluster::migration::MigrationState::Failed
            }),
            "the migration entry must still be tracked as Failed for explicit retry; \
             mgr.active_migrations = {active:?}"
        );
        drop(mgr);
        receiver.join().unwrap();
    }

    #[test]
    fn data_migration_verifies_manifest_before_batched_completion() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master != new_table.target_assignment(s).master
            })
            .expect("expected a shard whose master moves");
        let old_master = old_table.target_assignment(shard).master;
        let new_master = new_table.target_assignment(shard).master;
        let task = MigrationTask {
            shard,
            from_node: old_master,
            to_node: new_master,
            is_master: true,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |s| s == shard);
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(4 * 1024 * 1024, 4096).unwrap());
        let alloc = crate::allocator::SlotAllocator::new(dev.clone()).unwrap();
        let index = crate::index::Index::new(128).unwrap();
        let engine = Arc::new(crate::ops::engine::Engine::new(
            dev,
            index,
            alloc,
            crate::locks::StripedLocks::new(64),
            crate::index::DahIndex::new(),
        ));

        let tx_id = {
            let mut nonce = 0u64;
            loop {
                let mut tx_id = [0u8; 32];
                tx_id[..8].copy_from_slice(&nonce.to_le_bytes());
                if ShardTable::shard_for_key(&TxKey { txid: tx_id }) == shard {
                    break tx_id;
                }
                nonce += 1;
            }
        };
        let key = TxKey { txid: tx_id };
        let utxo_hashes = [[0x44u8; 32]];
        engine
            .create(&crate::ops::create::CreateRequest {
                tx_id,
                tx_version: 1,
                locktime: 0,
                fee: 100,
                size_in_bytes: 100,
                extended_size: 0,
                is_coinbase: false,
                spending_height: 0,
                utxo_hashes: &utxo_hashes,
                inputs: None,
                outputs: None,
                inpoints: None,
                is_external: false,
                created_at: 1710000000000,
                block_height: 0,
                mined_block_infos: &[],
                frozen: false,
                conflicting: false,
                locked: false,
                external_ref: None,
                parent_txids: &[],
            })
            .unwrap();

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let populated: std::collections::HashSet<u16> = [shard].into_iter().collect();
        migration
            .lock()
            .start_outbound(std::slice::from_ref(&task), old_master, &populated);

        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(shard);
        let inbound_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        let (request_tx, request_rx) = std::sync::mpsc::channel();
        let receiver = std::thread::spawn(move || {
            use std::io::{Read, Write};

            for _ in 0..2 {
                let (mut stream, _) = listener.accept().unwrap();
                stream
                    .set_read_timeout(Some(Duration::from_millis(200)))
                    .unwrap();
                loop {
                    let mut header = [0u8; 4];
                    match stream.read_exact(&mut header) {
                        Ok(()) => {}
                        Err(e)
                            if e.kind() == std::io::ErrorKind::WouldBlock
                                || e.kind() == std::io::ErrorKind::TimedOut =>
                        {
                            break;
                        }
                        Err(_) => break,
                    }
                    let payload_len = u32::from_le_bytes(header) as usize;
                    let mut rest = vec![0u8; payload_len];
                    stream.read_exact(&mut rest).unwrap();

                    let mut frame_bytes = header.to_vec();
                    frame_bytes.extend_from_slice(&rest);
                    let (request, _) = RequestFrame::decode(&frame_bytes).unwrap();
                    request_tx
                        .send((request.op_code, request.flags, request.request_id))
                        .unwrap();

                    let response = ResponseFrame {
                        request_id: request.request_id,
                        status: STATUS_OK,
                        payload: Vec::new(),
                    };
                    stream.write_all(&response.encode()).unwrap();

                    if request.op_code == OP_MIGRATION_COMPLETE {
                        break;
                    }
                }
            }
        });

        run_migration_batch(
            vec![task.clone()],
            Some(target_addr),
            &[key],
            engine,
            &migration,
            &shard_table,
            &None,
            new_table.version,
            1,
            100,
            fenced_bm,
            migrating_bm,
            inbound_bm,
            old_master,
            None,
            None,
        );

        let mut seen = Vec::new();
        while let Ok(request) = request_rx.recv_timeout(Duration::from_millis(200)) {
            seen.push(request);
            if request.0 == OP_MIGRATION_BATCH_COMPLETE {
                break;
            }
        }
        assert!(
            seen.iter()
                .any(|(op, flags, req_id)| *op == OP_MIGRATION_COMPLETE
                    && *flags & FLAG_MIGRATION_VERIFY_ONLY != 0
                    && *req_id == shard as u64),
            "data migrations must verify the exact manifest before batched completion; saw {seen:?}"
        );
        assert!(
            seen.iter()
                .any(|(op, _flags, _req_id)| *op == OP_MIGRATION_BATCH_COMPLETE),
            "verified data migrations must clear inbound state with a batched completion; saw {seen:?}"
        );
        receiver.join().unwrap();
    }

    #[test]
    fn already_serving_completion_retries_until_target_is_ready() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master != new_table.target_assignment(s).master
            })
            .expect("expected a shard whose master moves");
        let old_master = old_table.target_assignment(shard).master;
        let new_master = new_table.target_assignment(shard).master;
        let task = MigrationTask {
            shard,
            from_node: old_master,
            to_node: new_master,
            is_master: true,
        };

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |_| false);
        assert_eq!(
            handoff.shard_handoff_state(shard),
            ShardHandoff::ServingNew,
            "the shard must use the completion-only fast path"
        );
        let shard_table = Arc::new(ShardTableLock::new(handoff));

        let dev: Arc<dyn crate::device::BlockDevice> =
            Arc::new(crate::device::MemoryDevice::new(4 * 1024 * 1024, 4096).unwrap());
        let alloc = crate::allocator::SlotAllocator::new(dev.clone()).unwrap();
        let index = crate::index::Index::new(128).unwrap();
        let engine = Arc::new(crate::ops::engine::Engine::new(
            dev,
            index,
            alloc,
            crate::locks::StripedLocks::new(64),
            crate::index::DahIndex::new(),
        ));

        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            old_master,
            &std::collections::HashSet::new(),
        );

        let fenced_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        migrating_bm.set(shard);
        let inbound_bm = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        drop(listener);
        let (request_tx, request_rx) = std::sync::mpsc::channel();
        let receiver = std::thread::spawn(move || {
            use std::io::{Read, Write};

            std::thread::sleep(Duration::from_millis(300));
            let listener = std::net::TcpListener::bind(target_addr).unwrap();
            let (mut stream, _) = listener.accept().unwrap();

            let mut header = [0u8; 4];
            stream.read_exact(&mut header).unwrap();
            let payload_len = u32::from_le_bytes(header) as usize;
            let mut rest = vec![0u8; payload_len];
            stream.read_exact(&mut rest).unwrap();

            let mut frame_bytes = header.to_vec();
            frame_bytes.extend_from_slice(&rest);
            let (request, _) = RequestFrame::decode(&frame_bytes).unwrap();
            request_tx
                .send((request.op_code, request.request_id))
                .unwrap();

            let response = ResponseFrame {
                request_id: request.request_id,
                status: STATUS_OK,
                payload: Vec::new(),
            };
            stream.write_all(&response.encode()).unwrap();
        });

        run_migration_batch(
            vec![task.clone()],
            Some(target_addr),
            &[],
            engine,
            &migration,
            &shard_table,
            &None,
            new_table.version,
            1,
            100,
            fenced_bm,
            migrating_bm,
            inbound_bm,
            old_master,
            None,
            None,
        );

        let (op, _req_id) = request_rx.recv_timeout(Duration::from_secs(3)).unwrap();
        assert!(
            op == OP_MIGRATION_COMPLETE || op == OP_MIGRATION_BATCH_COMPLETE,
            "the source must retry completion-only handshakes until the target can acknowledge them (got op {op})"
        );
        receiver.join().unwrap();
    }

    #[test]
    fn restored_outbound_state_forces_reactivation_even_without_assignment_mismatch() {
        assert!(should_trigger_topology_reactivation(true, false, 0, 0));
        assert!(should_trigger_topology_reactivation(false, true, 0, 1));
        assert!(should_trigger_topology_reactivation(false, true, 2, 0));
        assert!(!should_trigger_topology_reactivation(false, true, 0, 0));
    }

    #[test]
    fn prompt_activation_fires_only_when_committed_term_is_ahead() {
        // committed_term ahead of the active table version → prompt activate.
        assert!(
            should_promptly_activate_committed_term(2, 1, 3),
            "a node whose committed term (2) is ahead of its active table (1) \
             must activate promptly, not wait for the 30s reactivation cooldown",
        );
        // Same term — this is same-term mismatch repair, which must stay on
        // the throttled reactivation path, not the prompt path.
        assert!(
            !should_promptly_activate_committed_term(2, 2, 3),
            "an already-activated term must NOT re-fire the prompt path",
        );
        // Active table somehow ahead of committed (stale read) → never fire.
        assert!(!should_promptly_activate_committed_term(1, 2, 3));
        // Single-node committed term carries no peers to migrate from; the
        // single-node commit-signal path handles it directly.
        assert!(
            !should_promptly_activate_committed_term(2, 1, 1),
            "a single-member committed term must not take the multi-node prompt path",
        );
        // No commit yet (term 0) → never fire.
        assert!(!should_promptly_activate_committed_term(0, 0, 3));
    }

    #[test]
    fn self_drain_re_drives_on_short_cadence_while_making_progress() {
        let floor = DRAIN_REACTIVATION_INTERVAL;
        let below_floor = floor.checked_sub(Duration::from_millis(1)).unwrap();
        // Arg order: (self_is_member, no_active_migrations, work_remaining,
        //             work_at_last_fast_reactivation, since_last_reactivation)

        // First fast round of a self-drain (self NOT a member, no prior fast
        // watermark): the previous batch settled, work remains, the short floor
        // elapsed → re-drive now instead of waiting out the 30 s cooldown.
        assert!(
            drain_reactivation_due(false, true, 485, None, floor),
            "the first self-drain round must re-drive on the short cadence",
        );

        // Subsequent round that made progress (485 -> 254 < 485) → keep going.
        assert!(
            drain_reactivation_due(false, true, 254, Some(485), floor),
            "a round that shrank the backlog must stay on the fast cadence",
        );

        // Scope guard: a node that is STILL a committed member (any member
        // rebalance — rejoin, absorbing a departed node) must NEVER take the
        // fast path; member rebalances stay on the 30 s cadence to pace redo
        // pressure on the receivers (see `drain_reactivation_due` rationale).
        assert!(
            !drain_reactivation_due(true, true, 485, None, Duration::from_secs(120)),
            "a node that remains a member must stay on the 30 s cadence",
        );
        assert!(!drain_reactivation_due(true, true, 254, Some(485), floor));

        // Plateau / regression (254 >= 254): backlog stopped shrinking → fall
        // back to the 30 s storm guard so a stuck drain can never busy-loop.
        assert!(
            !drain_reactivation_due(false, true, 254, Some(254), floor),
            "a stalled backlog must fall back to the 30 s cooldown (storm guard)",
        );
        assert!(
            !drain_reactivation_due(false, true, 300, Some(254), floor),
            "a growing backlog must fall back to the 30 s cooldown (storm guard)",
        );

        // Zero work remaining → drained; must never re-fire.
        assert!(
            !drain_reactivation_due(false, true, 0, None, floor),
            "a fully drained node must not re-fire",
        );
        assert!(!drain_reactivation_due(false, true, 0, Some(10), floor));

        // Previous batch still in flight (active_count > 0) → would only contend.
        assert!(
            !drain_reactivation_due(false, false, 485, None, floor),
            "must not re-drive while the previous batch is still active",
        );

        // Below the short floor → debounce so a run of fast rounds cannot
        // busy-spawn an activation on every event-loop tick.
        assert!(
            !drain_reactivation_due(false, true, 485, None, below_floor),
            "must respect the short re-drive floor to avoid per-tick respawn",
        );
        assert!(!drain_reactivation_due(
            false,
            true,
            254,
            Some(485),
            below_floor
        ));
    }

    #[test]
    fn committed_reactivation_metrics_use_committed_term_assignments() {
        let members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let rf = 2;
        let committed_term = 4;
        let table = ShardTable::compute_with_epoch(&members, rf, committed_term, 1);

        let (mismatched, pending_handoffs) =
            committed_topology_reactivation_metrics(&table, &members, rf, committed_term, 1);

        assert_eq!(
            mismatched, 0,
            "a shard table that already matches the committed term must not trigger reactivation"
        );
        assert_eq!(pending_handoffs, 0);
    }

    /// W1.1 FIX C — the reactivation mismatch metric must compare the
    /// active table against the activation's *election-refined* intent,
    /// not raw round-robin. Repro recipe 3: a partition view in which one
    /// node holds all the data drives `apply_master_election` away from
    /// the round-robin picks; a settled cluster must then report
    /// `mismatched == 0` so the reactivation loop never fires spuriously.
    #[test]
    fn reactivation_metrics_zero_after_master_election_refinement() {
        let members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let rf = 2;
        let term = 7;
        let prev = ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2)], rf, 6, 1);
        let mut table = ShardTable::compute_with_epoch(&members, rf, term, 1);

        // Node 1 reports full data for every shard; the other candidates
        // report nothing — the election prefers node 1 wherever it is in
        // the candidate set, deviating from round-robin.
        let mut view: std::collections::HashMap<NodeId, Vec<PartitionVersionEntry>> =
            std::collections::HashMap::new();
        view.insert(
            NodeId(1),
            (0..NUM_SHARDS as u16)
                .map(|shard| PartitionVersionEntry {
                    shard,
                    flags: 0,
                    replica_count: 1,
                    last_applied_seq: 5,
                    manifest_digest: 0,
                    max_generation: 0,
                })
                .collect(),
        );
        view.insert(NodeId(2), Vec::new());
        view.insert(NodeId(3), Vec::new());
        apply_master_election(
            &mut table,
            &prev,
            &view,
            &std::collections::HashSet::new(),
            false,
        );

        // Sanity: the election actually deviated from round-robin,
        // otherwise this test would not exercise FIX C at all.
        let round_robin = ShardTable::compute_with_epoch(&members, rf, term, 1);
        let deviated = (0..NUM_SHARDS as u16)
            .any(|s| table.target_assignment(s).master != round_robin.target_assignment(s).master);
        assert!(
            deviated,
            "election with a one-node-holds-all view must deviate from round-robin"
        );

        let (mismatched, pending_handoffs) =
            committed_topology_reactivation_metrics(&table, &members, rf, term, 1);
        assert_eq!(
            mismatched, 0,
            "an election-refined settled table must never trigger reactivation"
        );
        assert_eq!(pending_handoffs, 0);
    }

    /// W1.1 FIX C — the metric must still flag genuine divergence from
    /// the activation's intent: a handoff rolled back after a failed
    /// migration leaves the shard's assignment differing from
    /// `intended_master`, and reactivation must fire to repair it.
    #[test]
    fn reactivation_metrics_flag_rolled_back_handoff() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let rf = 2;
        let new_table = ShardTable::compute_with_epoch(&new_members, rf, 2, 1);
        let mut table = ShardTable::compute_with_epoch(&old_members, rf, 1, 1);
        let moved_shard = (0..NUM_SHARDS as u16)
            .find(|&s| table.target_assignment(s).master != new_table.target_assignment(s).master)
            .expect("a shard must change master when a third node joins");
        table.begin_handoff_with(&new_table, |s| s == moved_shard);

        // The handoff fails: roll the shard back to the old assignment.
        table.rollback_shard(moved_shard);
        assert_ne!(
            table.target_assignment(moved_shard).master,
            table.intended_master(moved_shard),
            "rollback must leave the shard diverged from the activation intent"
        );

        let (mismatched, _pending) =
            committed_topology_reactivation_metrics(&table, &new_members, rf, 2, 1);
        assert!(
            mismatched >= 1,
            "a rolled-back handoff must keep triggering reactivation (got {mismatched})"
        );
    }

    /// W1.1 FIX C — a node whose shard table never activated the
    /// committed term (the CI deadlock's node3) must report a mismatch
    /// even before any per-shard comparison, so reactivation installs
    /// the committed topology.
    #[test]
    fn reactivation_metrics_force_reactivation_when_term_not_activated() {
        let rf = 2;
        let committed_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        // Active table is the stale 2-member term-1 table.
        let table = ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2)], rf, 1, 1);
        let (mismatched, _pending) =
            committed_topology_reactivation_metrics(&table, &committed_members, rf, 2, 1);
        assert!(
            mismatched >= 1,
            "a table behind the committed term must trigger reactivation"
        );
    }

    /// W1.1 FIX A (sender) — a target replying
    /// `ERR_MIGRATION_TARGET_NOT_READY` (it has not activated the
    /// migration's epoch yet) is retryable-pending: the sender must keep
    /// retrying and succeed once the target acknowledges, never treating
    /// the rejection as "delivered".
    #[test]
    fn batch_complete_retries_not_ready_target_until_acknowledged() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        let receiver = std::thread::spawn(move || {
            use std::io::{Read as _, Write as _};
            // First connection: reject with ERR_MIGRATION_TARGET_NOT_READY.
            // Second connection: acknowledge with STATUS_OK.
            for attempt in 0..2 {
                let (mut stream, _) = listener.accept().unwrap();
                stream
                    .set_read_timeout(Some(Duration::from_secs(5)))
                    .unwrap();
                let mut header = [0u8; 4];
                stream.read_exact(&mut header).unwrap();
                let len = u32::from_le_bytes(header) as usize;
                let mut rest = vec![0u8; len];
                stream.read_exact(&mut rest).unwrap();
                let mut frame_bytes = header.to_vec();
                frame_bytes.extend_from_slice(&rest);
                let (request, _) = RequestFrame::decode(&frame_bytes).unwrap();
                assert_eq!(request.op_code, OP_MIGRATION_BATCH_COMPLETE);
                // The frame must carry the trailing topology epoch.
                let count = u32::from_le_bytes(request.payload[..4].try_into().unwrap()) as usize;
                let epoch_off = 4 + count * 2 + 8;
                let epoch = u64::from_le_bytes(
                    request.payload[epoch_off..epoch_off + 8]
                        .try_into()
                        .unwrap(),
                );
                assert_eq!(epoch, 42, "sender must stamp the activation epoch");
                let response = if attempt == 0 {
                    let mut payload = Vec::new();
                    payload.extend_from_slice(&ERR_MIGRATION_TARGET_NOT_READY.to_le_bytes());
                    payload.extend_from_slice(&0u16.to_le_bytes());
                    ResponseFrame {
                        request_id: request.request_id,
                        status: STATUS_ERROR,
                        payload,
                    }
                } else {
                    ResponseFrame {
                        request_id: request.request_id,
                        status: STATUS_OK,
                        payload: Vec::new(),
                    }
                };
                stream.write_all(&response.encode()).unwrap();
            }
        });

        let tasks = vec![MigrationTask {
            shard: 17,
            from_node: NodeId(1),
            to_node: NodeId(3),
            is_master: true,
        }];
        let delivered = send_completion_only_handshakes(target_addr, &tasks, NodeId(1), 42, None);
        assert_eq!(
            delivered,
            vec![HandshakeOutcome::Delivered],
            "after the target activates the epoch, the retried handshake must succeed"
        );
        receiver.join().unwrap();
    }

    /// W1.1 FIX A (sender) — any other rejection is a hard NO: the batch
    /// must be reported NOT delivered (pre-fix every non-OK response was
    /// treated as delivered, silently completing unacknowledged handoffs).
    #[test]
    fn batch_complete_hard_rejection_is_not_treated_as_delivered() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = listener.local_addr().unwrap();
        let receiver = std::thread::spawn(move || {
            use std::io::{Read as _, Write as _};
            let (mut stream, _) = listener.accept().unwrap();
            stream
                .set_read_timeout(Some(Duration::from_secs(5)))
                .unwrap();
            let mut header = [0u8; 4];
            stream.read_exact(&mut header).unwrap();
            let len = u32::from_le_bytes(header) as usize;
            let mut rest = vec![0u8; len];
            stream.read_exact(&mut rest).unwrap();
            let mut frame_bytes = header.to_vec();
            frame_bytes.extend_from_slice(&rest);
            let (request, _) = RequestFrame::decode(&frame_bytes).unwrap();
            let mut payload = Vec::new();
            payload.extend_from_slice(&ERR_PAYLOAD_MALFORMED.to_le_bytes());
            payload.extend_from_slice(&0u16.to_le_bytes());
            let response = ResponseFrame {
                request_id: request.request_id,
                status: STATUS_ERROR,
                payload,
            };
            stream.write_all(&response.encode()).unwrap();
        });

        let tasks = vec![
            MigrationTask {
                shard: 5,
                from_node: NodeId(1),
                to_node: NodeId(2),
                is_master: true,
            },
            MigrationTask {
                shard: 6,
                from_node: NodeId(1),
                to_node: NodeId(2),
                is_master: false,
            },
        ];
        let delivered = send_completion_only_handshakes(target_addr, &tasks, NodeId(1), 3, None);
        assert_eq!(
            delivered,
            vec![HandshakeOutcome::HardReject, HandshakeOutcome::HardReject],
            "a hard rejection must never be reported as delivered"
        );
        receiver.join().unwrap();
    }

    /// W1.1 FIX B — `split_transfer_request_tasks` classification:
    /// requester-as-target-master → master task; requester-as-replica →
    /// replica task; rolled-back shard (intent says requester, table no
    /// longer does) → diverged; unrelated shard → ignored.
    #[test]
    fn split_transfer_request_tasks_classifies_shards() {
        let rf = 2;
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let new_table = ShardTable::compute_with_epoch(&new_members, rf, 2, 1);
        let mut table = ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2)], rf, 1, 1);

        let master_shard = (0..NUM_SHARDS as u16)
            .find(|&s| new_table.target_assignment(s).master == NodeId(3))
            .expect("node 3 must master some shard");
        let replica_shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                new_table.target_assignment(s).master != NodeId(3)
                    && new_table.target_assignment(s).replicas.contains(&NodeId(3))
            })
            .expect("node 3 must replicate some shard");
        let unrelated_shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                let a = new_table.target_assignment(s);
                a.master != NodeId(3) && !a.replicas.contains(&NodeId(3))
            })
            .expect("some shard must not involve node 3");
        let rolled_back_shard = (master_shard + 3..NUM_SHARDS as u16)
            .find(|&s| new_table.target_assignment(s).master == NodeId(3))
            .expect("node 3 must master another shard");

        table.begin_handoff_with(&new_table, |s| s == master_shard || s == rolled_back_shard);
        table.rollback_shard(rolled_back_shard);

        let (tasks, diverged) = split_transfer_request_tasks(
            &table,
            NodeId(1),
            NodeId(3),
            &[
                master_shard,
                replica_shard,
                unrelated_shard,
                rolled_back_shard,
            ],
        );
        assert_eq!(diverged, 1, "the rolled-back shard must count as diverged");
        assert_eq!(tasks.len(), 2);
        let master_task = tasks.iter().find(|t| t.shard == master_shard).unwrap();
        assert!(master_task.is_master);
        assert_eq!(master_task.from_node, NodeId(1));
        assert_eq!(master_task.to_node, NodeId(3));
        let replica_task = tasks.iter().find(|t| t.shard == replica_shard).unwrap();
        assert!(!replica_task.is_master);
        assert!(
            !tasks.iter().any(|t| t.shard == unrelated_shard),
            "shards the requester does not own must be ignored"
        );
        assert!(
            !tasks.iter().any(|t| t.shard == rolled_back_shard),
            "diverged shards are repaired via re-activation, not direct tasks"
        );
    }

    // -----------------------------------------------------------------------
    // Reverse-heal Phase 2b — per-record manifest-diff DIRECTION
    // -----------------------------------------------------------------------

    /// A distinct 32-byte txid for the manifest-diff tests.
    fn hk(b: u8) -> TxKey {
        let mut txid = [0u8; 32];
        txid[0] = b;
        txid[5] = 0xC3;
        TxKey { txid }
    }

    /// P1-2: the source is ONE generation ahead on a record while the shard
    /// record count is flat and `max_generation` unchanged (a steady sub-max
    /// spend the ex-master lost). Per-record direction must still put that
    /// record in the ship-set — the exact case shard-recency (count / max_gen)
    /// is blind to.
    #[test]
    fn manifest_diff_ships_submax_lost_record() {
        let k_lost = hk(1);
        let k_same = hk(2);
        // Ex-master LIVE view: k_lost@4 (behind), k_same@9 (matches source).
        let dst_live = vec![(k_lost, 4u32), (k_same, 9u32)];
        // Source LIVE view: k_lost@5 (one ahead), k_same@9.
        let source = vec![(k_lost, 5u32), (k_same, 9u32)];
        let ship = compute_heal_ship_set(&dst_live, |_| None, &source);
        assert_eq!(
            ship.records,
            vec![ShipRecord {
                key: k_lost,
                source_generation: 5,
            }],
            "only the sub-max lost record ships; the equal-generation record does not",
        );
        assert!(ship.is_self_behind());
    }

    /// P1-3: the ex-master correctly DELETED `k` at generation N (tombstone
    /// `k@N`); a laggard source still holds `k` at a generation <= N. Direction
    /// must classify `k` as never-pull — it is NOT in the ship-set (no
    /// resurrection).
    #[test]
    fn manifest_diff_excludes_tombstoned_record() {
        let k_deleted = hk(7);
        let n: u32 = 12;
        // Ex-master holds NO live entry for k_deleted; it carries a tombstone@N.
        let dst_live: Vec<(TxKey, u32)> = Vec::new();
        let tombs: std::collections::HashMap<TxKey, u32> = [(k_deleted, n)].into_iter().collect();
        // Source still holds k at N (equal) — a terminal fully-spent record
        // admits no further mutation, so the source can never be strictly ahead
        // of the delete.
        let source = vec![(k_deleted, n)];
        let ship = compute_heal_ship_set(&dst_live, |k| tombs.get(k).copied(), &source);
        assert!(
            ship.records.is_empty(),
            "a record tombstoned at >= the source generation must never ship (P1-3)",
        );
        assert!(!ship.is_self_behind());

        // A source strictly BEHIND the delete (N-1) is likewise never pulled.
        let source_behind = vec![(k_deleted, n - 1)];
        let ship2 = compute_heal_ship_set(&dst_live, |k| tombs.get(k).copied(), &source_behind);
        assert!(ship2.records.is_empty());
    }

    /// The DIRECTION contract: `is_self_behind()` is true IFF the ship-set is
    /// non-empty — across a deficit, a level, and an ahead manifest.
    #[test]
    fn manifest_diff_direction_self_behind_iff_shipset_nonempty() {
        let k = hk(3);
        // (a) source holds a record the ex-master lacks -> behind.
        let behind = compute_heal_ship_set(&[], |_| None, &[(k, 1)]);
        assert!(behind.is_self_behind());
        assert_eq!(behind.records.len(), 1);
        // (b) identical single record -> not behind.
        let level = compute_heal_ship_set(&[(k, 1)], |_| None, &[(k, 1)]);
        assert!(!level.is_self_behind());
        assert!(level.records.is_empty());
        // (c) ex-master strictly AHEAD -> not behind (never-pull, no downgrade).
        let ahead = compute_heal_ship_set(&[(k, 5)], |_| None, &[(k, 3)]);
        assert!(!ahead.is_self_behind());
    }

    /// A record the ex-master lost ENTIRELY (no live entry, no tombstone) but
    /// the source still holds must ship — the record has to be recovered.
    #[test]
    fn manifest_diff_ships_record_source_has_that_exmaster_lost_entirely() {
        let k = hk(9);
        let ship = compute_heal_ship_set(&[], |_| None, &[(k, 2)]);
        assert_eq!(
            ship.records,
            vec![ShipRecord {
                key: k,
                source_generation: 2,
            }],
        );
    }

    /// Identical manifests (same keys + generations, no tombstones) -> empty
    /// ship-set, not self-behind.
    #[test]
    fn manifest_diff_empty_when_manifests_identical() {
        let m = vec![(hk(1), 3u32), (hk(2), 7u32), (hk(3), 0u32)];
        let ship = compute_heal_ship_set(&m, |_| None, &m);
        assert!(ship.records.is_empty());
        assert!(!ship.is_self_behind());
    }

    /// Source selection must reject a fresher-looking but NON-quorum-current
    /// node: (a) a committed replica flagged PENDING_INBOUND (subset, still
    /// receiving inbound data) and (b) a node absent from the committed replica
    /// set — even with a strictly higher `max_generation` — are never chosen
    /// over a lower-recency, current committed replica.
    #[test]
    fn source_selection_rejects_non_quorum_current() {
        let self_id = NodeId(1);
        let current = NodeId(2); // committed replica, current, max_gen 5
        let pending = NodeId(3); // committed replica, PENDING_INBOUND, max_gen 100
        let outsider = NodeId(4); // NOT a committed replica, current, max_gen 200
        let shard = 0u16;
        let committed_replicas = vec![self_id, current, pending];

        let mk = |g: u32, flags: u8| PartitionVersionEntry {
            shard,
            flags,
            replica_count: 1,
            last_applied_seq: 10,
            manifest_digest: g as u64,
            max_generation: g,
        };
        let mut view: std::collections::HashMap<NodeId, Vec<PartitionVersionEntry>> =
            std::collections::HashMap::new();
        view.insert(current, vec![mk(5, 0)]);
        view.insert(pending, vec![mk(100, PARTITION_FLAG_PENDING_INBOUND)]);
        view.insert(outsider, vec![mk(200, 0)]);

        assert_eq!(
            select_heal_source(self_id, &committed_replicas, &view, shard),
            Some(current),
            "must pick the lower-recency but quorum-current replica, never the \
             fresher pending-inbound or non-member node",
        );

        // No quorum-current candidate at all -> None (heal is not attempted).
        let only_pending = vec![self_id, pending];
        assert_eq!(
            select_heal_source(self_id, &only_pending, &view, shard),
            None,
        );
    }

    /// Among two quorum-current committed replicas, the higher-recency one wins.
    #[test]
    fn source_selection_picks_argmax_recency_among_current() {
        let self_id = NodeId(1);
        let lo = NodeId(2);
        let hi = NodeId(3);
        let shard = 4u16;
        let committed = vec![self_id, lo, hi];
        let mk = |g: u32| PartitionVersionEntry {
            shard,
            flags: 0,
            replica_count: 1,
            last_applied_seq: 1,
            manifest_digest: 0,
            max_generation: g,
        };
        let mut view: std::collections::HashMap<NodeId, Vec<PartitionVersionEntry>> =
            std::collections::HashMap::new();
        view.insert(lo, vec![mk(7)]);
        view.insert(hi, vec![mk(11)]);
        assert_eq!(
            select_heal_source(self_id, &committed, &view, shard),
            Some(hi),
        );
    }

    /// #74 F3 — an EMPTY quorum-current report (zero records for the shard)
    /// is not heal evidence while a NON-empty candidate exists: an empty
    /// source can heal nothing, and its recency fields can still outrank the
    /// real holder (`max_generation` is a coarse proxy, not per-key
    /// currency). Rejected unless ALL candidates report empty — a genuinely
    /// empty shard heals trivially and must still unfence.
    #[test]
    fn source_selection_rejects_empty_report_when_nonzero_candidate_exists() {
        let self_id = NodeId(1);
        let empty = NodeId(2); // zero records, but HIGHER max_generation
        let holder = NodeId(3); // 5 records, lower max_generation
        let shard = 2u16;
        let committed = vec![self_id, empty, holder];
        let mk = |count: u64, g: u32| PartitionVersionEntry {
            shard,
            flags: 0,
            replica_count: 1,
            last_applied_seq: count,
            manifest_digest: 1,
            max_generation: g,
        };

        let mut view: std::collections::HashMap<NodeId, Vec<PartitionVersionEntry>> =
            std::collections::HashMap::new();
        view.insert(empty, vec![mk(0, 9)]);
        view.insert(holder, vec![mk(5, 3)]);
        assert_eq!(
            select_heal_source(self_id, &committed, &view, shard),
            Some(holder),
            "an empty report must never outrank a non-empty holder — an empty \
             source can heal nothing",
        );

        // ALL candidates report empty → still pick one (the heal of a
        // genuinely-empty shard completes trivially and unfences).
        let mut all_empty: std::collections::HashMap<NodeId, Vec<PartitionVersionEntry>> =
            std::collections::HashMap::new();
        all_empty.insert(empty, vec![mk(0, 0)]);
        all_empty.insert(holder, vec![mk(0, 0)]);
        assert_eq!(
            select_heal_source(self_id, &committed, &all_empty, shard),
            Some(holder),
            "all-empty candidates: selection still yields a source \
             (deterministic tiebreak) so an empty shard's fence can clear",
        );
    }

    /// The heal-manifest entry wire marker round-trips LIVE and TOMB kinds; a
    /// short slice or an unknown kind byte decodes to `None` (a peer rejects a
    /// malformed diff rather than guessing).
    #[test]
    fn heal_manifest_entry_roundtrips_live_and_tomb() {
        for (kind, g) in [(HealEntryKind::Live, 3u32), (HealEntryKind::Tomb, 12u32)] {
            let key = hk(42);
            let bytes = encode_heal_manifest_entry(&key, g, kind);
            assert_eq!(bytes.len(), HEAL_MANIFEST_ENTRY_SIZE);
            let (dk, dg, dkind) = decode_heal_manifest_entry(&bytes).expect("roundtrip decodes");
            assert_eq!(dk, key);
            assert_eq!(dg, g);
            assert_eq!(dkind, kind);
        }
        assert!(
            decode_heal_manifest_entry(&[0u8; 10]).is_none(),
            "a short slice must not decode",
        );
        let mut bad = encode_heal_manifest_entry(&hk(1), 0, HealEntryKind::Live);
        bad[36] = 0x7F; // unknown kind byte
        assert!(
            decode_heal_manifest_entry(&bad).is_none(),
            "an unknown kind byte must not decode",
        );
    }

    /// W1.1 residual fix (FIX 2) — the self-heal backstop. After the
    /// settled-inbound GC reaps a late node's inbound plan, the node is left
    /// as the assigned+intended master of shards stuck in master_subset but
    /// with NO pending inbound and NO active migration. The steady-state
    /// mismatch metric reads zero in that state (target == intended), so
    /// reactivation would NOT re-fire on `mismatched` alone — the node would
    /// sit masterless forever. `stuck_subset_master_count` must detect these
    /// shards so the trigger fires; and it must NOT fire while a pending
    /// inbound entry / active migration still covers them.
    #[test]
    fn stuck_subset_count_re_fires_reactivation_after_inbound_gc() {
        let rf = 2;
        let committed = vec![NodeId(1), NodeId(2), NodeId(3)];
        let committed_term = 2u64;
        let new_table = ShardTable::compute_with_epoch(&committed, rf, committed_term, 1);

        // Build node 3's table exactly as a late reactivation does: handoff
        // from the 2-member term-1 table to the 3-member term-2 table, with
        // one shard data-carrying so the handoff stays active and the
        // master_subset flags persist for every shard node 3 now masters.
        let mut table = ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2)], rf, 1, 1);
        let any_n3 = (0..NUM_SHARDS as u16)
            .find(|&s| new_table.target_assignment(s).master == NodeId(3))
            .expect("node 3 must master some shard");
        table.begin_handoff_with(&new_table, |s| s == any_n3);
        // The single data-carrying shard's handoff completes (its resend
        // arrived), draining the handoff state to zero pending entries — but
        // the OTHER shards node 3 masters stay flagged in master_subset.
        // This is the real CI deadlock state: pending_handoffs == 0,
        // mismatched == 0, yet ~1364 shards stuck masterless.
        table.commit_shard(any_n3);

        // The committed term IS activated locally (version == committed_term)
        // and target == intended for node 3's shards, so the steady-state
        // mismatch metric is zero — reactivation would never fire on it.
        let (mismatched, pending_handoffs) =
            committed_topology_reactivation_metrics(&table, &committed, rf, committed_term, 1);
        assert_eq!(
            mismatched, 0,
            "post-activation mismatch must be zero (the bug: nothing re-fires)"
        );
        assert_eq!(
            pending_handoffs, 0,
            "the only handoff completed; nothing else triggers reactivation"
        );

        // CASE A — inbound entries still present (the healthy in-progress
        // state right after reactivation, before the GC race): node 3 has a
        // pending inbound entry for every shard it masters. stuck_subset
        // must be ZERO — the pull-based request loop owns recovery, not the
        // reactivation backstop.
        let mut mgr_inflight = MigrationManager::new();
        let inflight_tasks: Vec<MigrationTask> = (0..NUM_SHARDS as u16)
            .filter(|&s| new_table.target_assignment(s).master == NodeId(3))
            .map(|s| MigrationTask {
                shard: s,
                from_node: NodeId(1),
                to_node: NodeId(3),
                is_master: true,
            })
            .collect();
        mgr_inflight.start_outbound(
            &inflight_tasks,
            NodeId(3),
            &std::collections::HashSet::new(),
        );
        assert!(mgr_inflight.inbound_count() > 1000, "test precondition");
        assert_eq!(
            stuck_subset_master_count(&table, &mgr_inflight, NodeId(3)),
            0,
            "shards with a live inbound entry must NOT count as stuck"
        );
        assert!(
            !should_trigger_topology_reactivation(false, true, mismatched, pending_handoffs),
            "no reactivation while inbound entries are live"
        );

        // CASE B — the settled GC has reaped every inbound entry (the race):
        // node 3 now has NO pending inbound and NO active migration, yet
        // still owns those shards stuck in master_subset. stuck_subset must
        // be large, and folding it into the trigger must re-fire
        // reactivation — the self-heal that recovers from the GC race.
        let mgr_empty = MigrationManager::new();
        let stuck = stuck_subset_master_count(&table, &mgr_empty, NodeId(3));
        assert!(
            stuck > 1000,
            "after the GC reaped inbound, every owned subset master is stuck (stuck={stuck})"
        );
        // Pre-FIX-2 behaviour: trigger on `mismatched` alone stays false.
        assert!(
            !should_trigger_topology_reactivation(false, true, mismatched, pending_handoffs),
            "pre-fix: reactivation does not fire — the masterless deadlock"
        );
        // Post-FIX-2: folding stuck_subset into the count re-fires it.
        assert!(
            should_trigger_topology_reactivation(
                false,
                true,
                mismatched.saturating_add(stuck as u32),
                pending_handoffs,
            ),
            "post-fix: stuck subset masters re-fire reactivation"
        );
    }

    /// Task #22 — post-rebalance dual-master non-convergence.
    ///
    /// A node can settle on a local shard table that is stamped with the
    /// current committed term (`version == committed_term`) and is
    /// internally self-consistent (`target_assignment == intended_master`
    /// for every shard) yet still masters shards the committed-members term
    /// does NOT assign to it. Across the cluster the per-node master counts
    /// then sum to more than `NUM_SHARDS` — the same shard is mastered by
    /// two nodes at runtime — and it never self-corrects: the steady-state
    /// `committed_topology_reactivation_metrics` reads `mismatched == 0`
    /// (it only compares the table against its OWN recorded intent, never
    /// against the committed-members assignment), `pending_handoffs == 0`,
    /// and `stuck_subset == 0`, so the reactivation trigger never fires.
    ///
    /// `phantom_master_shard_count` is the missing local detector: a shard
    /// this node locally masters whose deterministic round-robin master under
    /// `committed_members` is a DIFFERENT node is over-ownership that a
    /// same-term empty-view reactivation will hand back. Folding the count
    /// into the trigger must re-fire reactivation, which recomputes the
    /// round-robin table (election is a no-op with an empty view) and hands
    /// the shard off to its rightful master, collapsing the cluster to a
    /// single master per shard.
    #[test]
    fn phantom_master_count_re_fires_reactivation_on_over_ownership() {
        let rf = 2;
        // Committed cluster is the 3-member term-2 set.
        let committed = vec![NodeId(1), NodeId(2), NodeId(3)];
        let committed_term = 2u64;
        let committed_table = ShardTable::compute_with_epoch(&committed, rf, committed_term, 1);

        // This node's LOCAL table was computed from the stale 2-member set
        // {1,2} but stamped with the current committed term — exactly the
        // post-rebalance phantom: node 2 still masters every shard the
        // 2-member round-robin gave it, including shards the 3-member
        // committed term reassigned to node 3.
        let stale_table =
            ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2)], rf, committed_term, 1);
        let self_id = NodeId(2);

        // The local table is at the committed term and target == intended
        // for every shard, so the steady-state metric reads zero — the bug.
        let (mismatched, pending_handoffs) = committed_topology_reactivation_metrics(
            &stale_table,
            &committed,
            rf,
            committed_term,
            1,
        );
        assert_eq!(
            mismatched, 0,
            "stale-but-same-term table reads mismatched==0 (the blind spot)"
        );
        assert_eq!(pending_handoffs, 0);

        // There must genuinely be over-ownership: node 2 locally masters
        // shards whose round-robin (committed-members) master is node 3.
        let over_owned = (0..NUM_SHARDS as u16)
            .filter(|&s| {
                stale_table.target_assignment(s).master == self_id
                    && committed_table.target_assignment(s).master != self_id
            })
            .count();
        assert!(
            over_owned > 0,
            "test precondition: node 2's stale table must over-own committed-node-3 shards",
        );

        // Pre-fix: the trigger does not fire on mismatched + stuck alone.
        assert!(
            !should_trigger_topology_reactivation(false, true, mismatched, pending_handoffs),
            "pre-fix: reactivation never fires — the dual-master deadlock",
        );

        // The new detector flags exactly the phantom-mastered shards.
        let phantom = phantom_master_shard_count(&stale_table, &committed, rf, self_id, 1, None);
        assert_eq!(
            phantom, over_owned,
            "phantom_master_shard_count must flag every committed-non-owned local master",
        );
        assert!(
            phantom > 0,
            "phantom count must be positive in the over-owned state"
        );

        // Post-fix: folding the phantom count into the trigger re-fires
        // reactivation, which recomputes from committed members.
        assert!(
            should_trigger_topology_reactivation(
                false,
                true,
                mismatched.saturating_add(phantom as u32),
                pending_handoffs,
            ),
            "post-fix: phantom masters re-fire reactivation",
        );
    }

    /// Task #22 — convergence: once the committed-members topology is
    /// installed, `phantom_master_shard_count` must read zero and the
    /// per-node master counts must sum to exactly `NUM_SHARDS` with each
    /// shard single-mastered. This guards against the fix oscillating: a
    /// correctly-activated committed table is a fixed point of the detector.
    #[test]
    fn phantom_master_count_zero_and_single_mastered_after_convergence() {
        let rf = 2;
        let committed = vec![NodeId(1), NodeId(2), NodeId(3)];
        let term = 2u64;
        let table = ShardTable::compute_with_epoch(&committed, rf, term, 1);

        // Every node's correctly-activated committed table reports zero
        // phantom masters.
        for &node in &committed {
            assert_eq!(
                phantom_master_shard_count(&table, &committed, rf, node, 1, None,),
                0,
                "a node activated on the committed term must report no phantom masters",
            );
        }

        // Cluster-wide, each shard has exactly one master and the per-node
        // master counts sum to NUM_SHARDS (no double-ownership).
        let counts = table.shard_counts();
        let total: usize = counts.values().sum();
        assert_eq!(
            total, NUM_SHARDS,
            "master ownership must sum to exactly the shard count",
        );
        for shard in 0..NUM_SHARDS as u16 {
            let m = table.target_assignment(shard).master;
            assert!(
                committed.contains(&m),
                "shard {shard} master {m:?} must be a committed member",
            );
        }
    }

    /// Task #22 — the phantom detector must flag *election-deviated* masters,
    /// because `apply_master_election` runs against each node's LOCAL view and
    /// reaches NO cluster-wide agreement: two nodes can each elect themselves
    /// master for the same shard at the same committed term (the real
    /// 4671/4096 dual-master state). The only cluster-wide deterministic
    /// assignment is round-robin, which a same-term empty-view reactivation
    /// installs; so a self-master that differs from the round-robin master is
    /// exactly what must be relinquished for the cluster to converge. The
    /// detector must therefore count those shards (a settled election
    /// deviation is NOT a fixed point — it is reverted to round-robin).
    #[test]
    fn phantom_master_count_flags_election_deviation_from_round_robin() {
        let rf = 2;
        let committed = vec![NodeId(1), NodeId(2), NodeId(3)];
        let term = 5u64;
        let prev = ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2)], rf, 4, 1);
        let mut table = ShardTable::compute_with_epoch(&committed, rf, term, 1);

        // Drive election so node 1 (which reports all data) wins every shard
        // where it is a candidate — deviating from round-robin. On a single
        // node this looks "legitimate", but nothing guarantees the OTHER
        // nodes elected node 1 too: each ran election against its own view,
        // so the same shard can end up self-mastered on two nodes. Round-robin
        // is the only assignment all nodes agree on.
        let mut view: std::collections::HashMap<NodeId, Vec<PartitionVersionEntry>> =
            std::collections::HashMap::new();
        view.insert(
            NodeId(1),
            (0..NUM_SHARDS as u16)
                .map(|shard| PartitionVersionEntry {
                    shard,
                    flags: 0,
                    replica_count: 1,
                    last_applied_seq: 9,
                    manifest_digest: 0,
                    max_generation: 0,
                })
                .collect(),
        );
        view.insert(NodeId(2), Vec::new());
        view.insert(NodeId(3), Vec::new());
        apply_master_election(
            &mut table,
            &prev,
            &view,
            &std::collections::HashSet::new(),
            false,
        );

        // Election must have deviated from round-robin (otherwise the test
        // does not exercise the convergence path).
        let round_robin = ShardTable::compute_with_epoch(&committed, rf, term, 1);
        let deviated: usize = (0..NUM_SHARDS as u16)
            .filter(|&s| {
                table.target_assignment(s).master == NodeId(1)
                    && round_robin.target_assignment(s).master != NodeId(1)
            })
            .count();
        assert!(deviated > 0, "election must deviate to exercise this path");

        // The detector flags exactly node 1's deviated masters — the shards a
        // same-term empty-view reactivation will hand back to their
        // round-robin masters, collapsing the cluster to single-mastership.
        assert_eq!(
            phantom_master_shard_count(&table, &committed, rf, NodeId(1), 1, None,),
            deviated,
            "election-deviated self-masters must be flagged for reconciliation",
        );
    }

    /// F7 (CI run 31787458246, scenario 09) — the reactivation detectors are
    /// self-centric: `phantom_master_shard_count` counts only self-mastered
    /// shards, `missing_master_shard_count` only shards the baseline assigns
    /// to self, and the settled-branch intent metric is internal
    /// self-consistency. A node whose table deviates shard S from det-master
    /// B to holder C, with self neither B nor C, measures ZERO work on every
    /// existing detector and never re-heals — how equal-version divergence
    /// persisted unnoticed (scenario 09's node2 holding 90% of the ring saw
    /// nothing wrong). `third_party_deviation_shard_count` closes the blind
    /// spot: it counts ALL shards whose local master differs from the
    /// committed-baseline expectation while self is neither side, arming the
    /// same re-heal trigger.
    #[test]
    fn third_party_deviation_count_flags_deviation_self_detectors_miss() {
        let committed = vec![NodeId(1), NodeId(2), NodeId(3)];
        let rf = 2;
        let term = 5u64;
        let det = ShardTable::compute_with_epoch(&committed, rf, term, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                det.target_assignment(s).master == NodeId(1)
                    && det.target_assignment(s).replicas.contains(&NodeId(2))
            })
            .expect("some shard has master N1 with replica N2 in a 3-member ring");

        // The deviated table: shard's master moved from det-master N1 to
        // holder N2. From N3's point of view this is a THIRD-PARTY deviation.
        let mut table = det.clone();
        table.set_master_for_shard(shard, NodeId(2));

        // Every existing detector on N3 reads zero — the blindness under test.
        let (mismatched, _pending) =
            committed_topology_reactivation_metrics(&table, &committed, rf, term, 1);
        assert_eq!(
            mismatched, 0,
            "the settled-branch intent metric is self-consistent and blind to the deviation",
        );
        assert_eq!(
            phantom_master_shard_count(&table, &committed, rf, NodeId(3), 1, None),
            0,
            "phantom detector only counts self-mastered shards",
        );
        assert_eq!(
            missing_master_shard_count(&table, &committed, rf, NodeId(3), 1, None),
            0,
            "missing detector only counts shards the baseline assigns to self",
        );

        // The new detector must flag exactly the one deviated shard.
        assert_eq!(
            third_party_deviation_shard_count(&table, &committed, rf, NodeId(3), 1, None),
            1,
            "a third-party deviation (self neither det master nor deviated master) must arm re-heal",
        );

        // No false fire on the undisturbed deterministic table.
        assert_eq!(
            third_party_deviation_shard_count(&det, &committed, rf, NodeId(3), 1, None),
            0,
            "a table matching the committed baseline must not arm re-heal",
        );

        // When self IS a side of the deviation the existing detectors already
        // count it; the third-party detector must not double count.
        assert_eq!(
            third_party_deviation_shard_count(&table, &committed, rf, NodeId(1), 1, None),
            0,
            "det-master side is missing_master_shard_count's job",
        );
        assert_eq!(
            missing_master_shard_count(&table, &committed, rf, NodeId(1), 1, None),
            1,
            "sanity: the det-master side is indeed counted by the missing detector",
        );
        assert_eq!(
            third_party_deviation_shard_count(&table, &committed, rf, NodeId(2), 1, None),
            0,
            "deviated-master side is phantom_master_shard_count's job",
        );

        // §8 — a committed elected assignment that ITSELF deviates the shard
        // is the cluster-agreed baseline; the detector must not fight it.
        let masters: Vec<NodeId> = (0..NUM_SHARDS as u16)
            .map(|s| {
                if s == shard {
                    NodeId(2)
                } else {
                    det.target_assignment(s).master
                }
            })
            .collect();
        let assignment =
            crate::cluster::election::CommittedAssignment::new(masters, &[false; NUM_SHARDS]);
        assert_eq!(
            third_party_deviation_shard_count(
                &table,
                &committed,
                rf,
                NodeId(3),
                1,
                Some(&assignment),
            ),
            0,
            "a deviation matching the committed elected assignment is not a deviation",
        );
    }

    /// F7 — `diagnose_key_routing` must expose the SERVING side of the shard
    /// table (effective master + the lock-free serving fence `is_master`
    /// actually reads), not just the target assignment: CI run 31787458246's
    /// diagnostics could not distinguish a serving-vs-target split from a
    /// settled table, so equal-version master divergence was invisible in the
    /// run dumps.
    #[test]
    fn diagnose_key_routing_reports_effective_master_and_serving_fence() {
        let members = vec![NodeId(1), NodeId(2)];
        let old = ShardTable::compute_with_epoch(&[NodeId(1)], 1, 2, 1);
        let new = ShardTable::compute_with_epoch(&members, 2, 3, 1);
        let split_shard = (0..NUM_SHARDS as u16)
            .find(|&s| new.target_assignment(s).master == NodeId(2))
            .expect("some shard mastered by N2 in a 2-member ring");
        let fenced_shard = (0..NUM_SHARDS as u16)
            .find(|&s| s != split_shard)
            .expect("a second shard exists");

        // Mid-handoff table: target(split_shard) is N2, but N1 keeps SERVING
        // it until the handoff commits (effective assignment = previous).
        let mut table = old.clone();
        table.begin_handoff_with(&new, |s| s == split_shard);

        let cluster = new_test_running_cluster(
            NodeId(1),
            table,
            &[(NodeId(1), "127.0.0.1:4899".parse().unwrap())],
            &members,
            &[fenced_shard], // inbound_shards → serving fence bit set
            &[],
            &[],
            2,
        );

        let split = cluster.diagnose_key_routing(split_shard);
        assert_eq!(
            split.local_view_canonical_master_id, 2,
            "target assignment must name the handoff destination",
        );
        assert_eq!(
            split.local_view_effective_master_id, 1,
            "the effective (serving) master must remain the pre-handoff owner until commit",
        );
        assert!(
            !split.is_serving_fenced,
            "no pending inbound for the split shard on this node",
        );

        let fenced = cluster.diagnose_key_routing(fenced_shard);
        assert!(
            fenced.is_serving_fenced,
            "the serving-fence bit must mirror the lock-free inbound bitmap `is_master` reads",
        );
        assert_eq!(
            fenced.local_view_effective_master_id, fenced.local_view_canonical_master_id,
            "no handoff in flight for the fenced shard: serving == target",
        );
    }

    /// W1.1 FIX D — persisting topology state must succeed even when the
    /// parent directory does not exist yet (persist racing data-dir
    /// creation at boot produced `No such file or directory`, failing the
    /// H10 vote persist and delaying the node's topology activation).
    #[test]
    fn persist_topology_state_creates_missing_parent_dirs() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp
            .path()
            .join("data")
            .join("cluster")
            .join("node.cluster.topo");
        assert!(!path.parent().unwrap().exists());

        let authority = Arc::new(crate::cluster::topology::TopologyAuthority::new(
            NodeId(1),
            Duration::from_secs(1),
            2,
        ));
        let state = authority.persisted_state(3, 1);
        persist_topology_state(&path, &state).expect("persist must create missing parent dirs");
        assert!(
            path.exists(),
            "topology state file must exist after persist"
        );

        let loaded = load_topology_state(&path).expect("state file must load");
        assert_eq!(loaded.peak_cluster_size, 3);
    }

    /// REL-002 / REL-111 — the persist paths now fsync the parent directory
    /// after the atomic rename (so the rename's directory entry is durable, not
    /// just the file contents). This exercises that path end-to-end: a persist
    /// into a real directory must succeed (the added `fsync_parent_dir` call
    /// must not error) and the safety-critical peak/committed_term must reload
    /// intact. Real crash/power-loss rollback can't be unit-tested without a
    /// crash-injecting filesystem, but this pins the durable round-trip and
    /// guards against the fsync call regressing into an error on a normal path.
    #[test]
    fn persist_topology_state_dir_fsync_round_trips_peak_and_term() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("node.cluster.topo");

        let authority = Arc::new(crate::cluster::topology::TopologyAuthority::new(
            NodeId(1),
            Duration::from_secs(1),
            2,
        ));
        // Persist into an existing directory; the added post-rename
        // `fsync_parent_dir` call must not error on a normal path, and the
        // safety-critical peak/committed_term must reload intact.
        persist_topology_state(&path, &authority.persisted_state(3, 7))
            .expect("persist (with dir fsync) must succeed");

        let loaded = load_topology_state(&path).expect("state file must load");
        assert_eq!(loaded.peak_cluster_size, 3, "peak must round-trip");
        assert_eq!(loaded.incarnation, 7, "incarnation must round-trip");
    }

    /// A MISSING state file is a fresh node — the one case that may default.
    #[test]
    fn load_topology_state_treats_a_missing_file_as_fresh() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("absent.cluster.topo");

        let loaded = load_topology_state(&path).expect("a missing file must not be an error");
        assert_eq!(loaded.committed_term, 0);
        assert_eq!(loaded.voted_term, 0);
        assert_eq!(loaded.peak_cluster_size, 1);
        assert!(loaded.committed_members.is_empty());
        assert_eq!(loaded.committed_commit, None);
    }

    /// A PRESENT but corrupt state file must fail closed. Defaulting it would
    /// reset `voted_term` (licensing a second vote in a term already voted in)
    /// and collapse the G8 split-brain floor to 1 — the node would come back
    /// looking like a legitimate fresh single-node cluster.
    #[test]
    fn load_topology_state_fails_closed_on_a_corrupt_file() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("node.cluster.topo");

        let authority = Arc::new(crate::cluster::topology::TopologyAuthority::new(
            NodeId(1),
            Duration::from_secs(1),
            2,
        ));
        persist_topology_state(&path, &authority.persisted_state(5, 3)).expect("persist");
        assert!(load_topology_state(&path).is_ok(), "baseline must load");

        // Flip one byte in the middle of the record.
        let mut bytes = std::fs::read(&path).expect("read back");
        let mid = bytes.len() / 2;
        bytes[mid] ^= 0xFF;
        std::fs::write(&path, &bytes).expect("write corrupted");

        match load_topology_state(&path) {
            Err(TopologyStateLoadError::Corrupt { path: p, .. }) => assert_eq!(p, path),
            other => panic!("a corrupt state file must fail closed, got {other:?}"),
        }
    }

    /// Truncation is the realistic corruption mode, and the one the pre-v2
    /// format handled worst: it decoded into a SHORTER member list under an
    /// unchanged committed term.
    #[test]
    fn load_topology_state_fails_closed_on_a_truncated_file() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("node.cluster.topo");

        let authority = Arc::new(crate::cluster::topology::TopologyAuthority::new(
            NodeId(1),
            Duration::from_secs(1),
            2,
        ));
        persist_topology_state(&path, &authority.persisted_state(5, 3)).expect("persist");

        let bytes = std::fs::read(&path).expect("read back");
        std::fs::write(&path, &bytes[..bytes.len() - 9]).expect("write truncated");

        assert!(
            matches!(
                load_topology_state(&path),
                Err(TopologyStateLoadError::Corrupt { .. })
            ),
            "a truncated state file must fail closed",
        );
    }

    #[test]
    fn cleanup_completed_clears_atomic_fence_shadow() {
        let task = MigrationTask {
            shard: 42,
            from_node: NodeId(1),
            to_node: NodeId(2),
            is_master: true,
        };
        let populated: std::collections::HashSet<u16> = [42u16].into_iter().collect();
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let fenced_bitmap = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating_bitmap = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let inbound_bitmap = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        {
            let mgr = &mut migration.lock();
            mgr.start_outbound(std::slice::from_ref(&task), NodeId(1), &populated);
            mgr.fence_shard(42);
            fenced_bitmap.load_from(mgr.fenced_bitmap());
            for progress in mgr.active_migrations() {
                if !progress.is_complete()
                    && progress.state != crate::cluster::migration::MigrationState::Failed
                {
                    migrating_bitmap.set(progress.shard);
                }
            }
            mgr.mark_complete(&task);
        }

        {
            let mut mgr = migration.lock();
            mgr.cleanup_completed();
            sync_atomic_migration_bitmaps(&mgr, &fenced_bitmap, &migrating_bitmap, &inbound_bitmap);
        }

        assert!(!fenced_bitmap.test(42));
        assert!(!migrating_bitmap.test(42));
        assert!(!inbound_bitmap.test(42));
    }

    #[test]
    fn preserved_reactivation_filters_tasks_by_full_identity() {
        let master_task = MigrationTask {
            shard: 42,
            from_node: NodeId(1),
            to_node: NodeId(2),
            is_master: true,
        };
        let replica_task = MigrationTask {
            shard: 42,
            from_node: NodeId(1),
            to_node: NodeId(3),
            is_master: false,
        };
        let populated: std::collections::HashSet<u16> = [42u16].into_iter().collect();

        let mut mgr = MigrationManager::new();
        mgr.start_outbound(
            &[master_task.clone(), replica_task.clone()],
            NodeId(1),
            &populated,
        );

        let new_task_set: std::collections::HashSet<(u16, NodeId, NodeId, bool)> =
            [(42u16, NodeId(1), NodeId(2), true)].into_iter().collect();

        let preserved_tasks: std::collections::HashSet<(u16, NodeId, NodeId, bool)> = mgr
            .active_migrations()
            .iter()
            .filter(|p| {
                p.state != crate::cluster::migration::MigrationState::Complete
                    && p.state != crate::cluster::migration::MigrationState::Failed
                    && new_task_set.contains(&(p.shard, p.from_node, p.to_node, p.is_master))
            })
            .map(|p| (p.shard, p.from_node, p.to_node, p.is_master))
            .collect();

        let stale_tasks: Vec<MigrationTask> = mgr
            .active_migrations()
            .iter()
            .filter(|p| {
                p.state != crate::cluster::migration::MigrationState::Complete
                    && p.state != crate::cluster::migration::MigrationState::Failed
                    && !preserved_tasks.contains(&(p.shard, p.from_node, p.to_node, p.is_master))
            })
            .map(|p| MigrationTask {
                shard: p.shard,
                from_node: p.from_node,
                to_node: p.to_node,
                is_master: p.is_master,
            })
            .collect();

        assert_eq!(preserved_tasks.len(), 1);
        assert!(preserved_tasks.contains(&(42, NodeId(1), NodeId(2), true)));
        assert_eq!(stale_tasks, vec![replica_task]);
    }

    #[test]
    fn peak_cluster_size_persists_and_loads() {
        let dir = tempfile::tempdir().expect("create temp dir");
        let path = dir.path().join("cluster.state");

        // Initially no file → returns 1
        assert_eq!(load_peak_cluster_size(&path), 1);

        // Persist and reload
        persist_peak_cluster_size(&path, 5);
        assert_eq!(load_peak_cluster_size(&path), 5);

        // Higher value persisted over lower
        persist_peak_cluster_size(&path, 3);
        assert_eq!(load_peak_cluster_size(&path), 3); // actually stores whatever we pass

        // Zero or corrupt data → returns 1
        std::fs::write(&path, [0u8; 4]).unwrap(); // too short
        assert_eq!(load_peak_cluster_size(&path), 1);

        std::fs::write(&path, 0u64.to_le_bytes()).unwrap(); // zero
        assert_eq!(load_peak_cluster_size(&path), 1); // max(0, 1) = 1
    }

    #[test]
    fn persist_failure_increments_counter() {
        let before = persist_failure_count();
        // Attempt to persist to a path that cannot be written
        // (directory that doesn't exist).
        let bad_path = std::path::Path::new("/nonexistent_dir_xyz/cluster.state");
        persist_cluster_state(bad_path, 5, 1);
        assert!(
            persist_failure_count() > before,
            "persist_failure_count should increment on failure",
        );
    }

    #[test]
    fn exchange_frame_rejects_oversized_response() {
        use std::io::Write as _;
        use std::net::TcpListener;

        // Spin up a mock server that sends a response with a huge length prefix.
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();

        let server = std::thread::spawn(move || {
            let (mut conn, _) = listener.accept().unwrap();
            // Read and discard the request.
            let mut discard = [0u8; 4096];
            let _ = conn.read(&mut discard);
            // Send a response with total_length = MAX_FRAME_SIZE + 1.
            let huge: u32 = crate::protocol::opcodes::MAX_FRAME_SIZE + 1;
            conn.write_all(&huge.to_le_bytes()).unwrap();
        });

        let mut stream = TcpStream::connect_timeout(&addr, Duration::from_secs(1)).unwrap();
        stream
            .set_read_timeout(Some(Duration::from_secs(2)))
            .unwrap();
        let request = RequestFrame {
            request_id: 0,
            op_code: 0,
            flags: 0,
            payload: vec![].into(),
        };
        let result = exchange_frame(&mut stream, &request, None);
        assert!(result.is_err(), "should reject oversized response");
        let err = result.unwrap_err();
        assert!(err.contains("response too large"), "error: {err}");
        server.join().unwrap();
    }

    fn tk(b: u8) -> TxKey {
        let mut txid = [0u8; 32];
        txid[0] = b;
        TxKey { txid }
    }

    /// The regression: a snapshot key that Phase 1 SKIPPED must still be
    /// streamed after the fence, or the manifest lists a key the target never
    /// received and the handshake rejects with `TxNotFound`.
    #[test]
    fn late_keys_include_snapshot_keys_phase1_skipped() {
        let snapshot: std::collections::HashSet<TxKey> =
            [tk(1), tk(2), tk(3)].into_iter().collect();
        // K=2 was deleted mid-stream (skipped), then re-created before the fence.
        let skipped: std::collections::HashSet<TxKey> = [tk(2)].into_iter().collect();
        let fenced = vec![tk(1), tk(2), tk(3)];
        assert_eq!(
            late_keys_needing_stream(&fenced, &snapshot, &skipped),
            vec![tk(2)],
            "a skipped-then-recreated snapshot key must be re-streamed",
        );
    }

    /// The original purpose of the late-key set: keys created after the
    /// snapshot must still be picked up.
    #[test]
    fn late_keys_include_keys_created_after_the_snapshot() {
        let snapshot: std::collections::HashSet<TxKey> = [tk(1)].into_iter().collect();
        let skipped = std::collections::HashSet::new();
        let fenced = vec![tk(1), tk(9)];
        assert_eq!(
            late_keys_needing_stream(&fenced, &snapshot, &skipped),
            vec![tk(9)],
        );
    }

    /// Nothing is re-streamed when Phase 1 sent everything it was given —
    /// the fix must not turn every migration into a full re-send.
    #[test]
    fn late_keys_empty_when_phase1_streamed_the_whole_snapshot() {
        let snapshot: std::collections::HashSet<TxKey> = [tk(1), tk(2)].into_iter().collect();
        let skipped = std::collections::HashSet::new();
        let fenced = vec![tk(1), tk(2)];
        assert!(late_keys_needing_stream(&fenced, &snapshot, &skipped).is_empty(),);
    }

    /// A key skipped in Phase 1 and still absent at the fence is genuinely
    /// deleted: it is not in `fenced_keys`, so it must not be resurrected.
    #[test]
    fn late_keys_exclude_keys_deleted_for_good() {
        let snapshot: std::collections::HashSet<TxKey> = [tk(1), tk(2)].into_iter().collect();
        let skipped: std::collections::HashSet<TxKey> = [tk(2)].into_iter().collect();
        let fenced = vec![tk(1)];
        assert!(
            late_keys_needing_stream(&fenced, &snapshot, &skipped).is_empty(),
            "a key deleted before the fence must stay deleted",
        );
    }

    /// F3 — the production wire format: the target's `code=19` completion
    /// rejection names the missing key only via `TxKey`'s truncated Debug form
    /// (`TxKey(<16 hex>...)`); it must resolve back to the FULL manifest key.
    #[test]
    fn missing_exact_keys_resolve_truncated_debug_names_against_the_manifest() {
        let manifest = vec![(tk(1), 3u32), (tk(2), 7u32)];
        let err = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(2),
        );
        assert_eq!(
            completion_rejection_missing_keys(&err, &manifest),
            vec![tk(2)],
            "the truncated Debug name must resolve to the full manifest key",
        );
    }

    /// F3 — only the exact-key rejection engages the escalation. Other code=19
    /// rejections (count mismatch — the sc09/sc05 relinquish case) and other
    /// codes carrying a similar phrase must resolve to NO keys.
    #[test]
    fn missing_exact_keys_ignore_other_rejections() {
        let manifest = vec![(tk(1), 3u32)];
        let count_mismatch = "target rejected: status 4 (code=19: shard 227 record count \
                              mismatch: expected 5, got 9)"
            .to_string();
        assert!(
            completion_rejection_missing_keys(&count_mismatch, &manifest).is_empty(),
            "count-mismatch rejections must not be treated as missing keys",
        );
        let other_code = format!(
            "target rejected: status 4 (code=22: shard 227 missing exact key {:?}: TxNotFound)",
            tk(1),
        );
        assert!(
            completion_rejection_missing_keys(&other_code, &manifest).is_empty(),
            "only code=19 carries the exact-key verify rejection",
        );
        let unknown_key = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(9),
        );
        assert!(
            completion_rejection_missing_keys(&unknown_key, &manifest).is_empty(),
            "a named key absent from the manifest cannot be re-pushed",
        );
        // Review finding 4: the code match must be exact — a future code in
        // the 190..=199 range must not satisfy the code=19 discriminator.
        let code_190 = format!(
            "target rejected: status 4 (code=190: shard 227 missing exact key {:?}: TxNotFound)",
            tk(1),
        );
        assert!(
            completion_rejection_missing_keys(&code_190, &manifest).is_empty(),
            "code=190 must not match the code=19 discriminator",
        );
    }

    /// F3 (a) — a completion rejection naming a missing exact key triggers a
    /// re-push of that key (resolved to its full txid) and the following
    /// completion retry verifies.
    #[test]
    fn exact_key_escalation_repushes_named_key_then_verifies() {
        let manifest = vec![(tk(1), 3u32), (tk(2), 7u32)];
        let initial = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(2),
        );
        let mut pushed: Vec<Vec<TxKey>> = Vec::new();
        let outcome = escalate_missing_exact_keys(initial, &manifest, 3, true, |action| {
            let EscalationAction::Repush(missing) = action else {
                panic!("this shape must re-push, not reduce: {action:?}");
            };
            pushed.push(missing.to_vec());
            Ok(())
        });
        assert_eq!(outcome, ExactKeyEscalation::Verified);
        assert_eq!(
            pushed,
            vec![vec![tk(2)]],
            "exactly the named key must be re-pushed, once",
        );
    }

    /// F3 (b) — attempts are bounded: a target that keeps naming a key the
    /// source cannot deliver exhausts the escalation (terminal for this task).
    #[test]
    fn exact_key_escalation_exhausts_after_bounded_attempts() {
        let manifest = vec![(tk(2), 7u32)];
        let reject = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(2),
        );
        let mut attempts = 0usize;
        let outcome = escalate_missing_exact_keys(reject.clone(), &manifest, 3, true, |action| {
            let EscalationAction::Repush(missing) = action else {
                panic!("this shape must re-push, not reduce: {action:?}");
            };
            attempts += 1;
            assert_eq!(missing, [tk(2)]);
            Err(EscalationAttemptError::Completion(reject.clone()))
        });
        assert_eq!(attempts, 3, "escalation must stop at the attempt bound");
        match outcome {
            ExactKeyEscalation::Exhausted { last_err } => {
                assert!(last_err.contains("missing exact key"), "got: {last_err}");
            }
            other => panic!("expected Exhausted, got {other:?}"),
        }
    }

    /// Review finding 1 — an indexed key whose record the SOURCE cannot read
    /// back (e.g. blob destroyed by GC) fails the RE-PUSH itself, not the
    /// completion retry. Those source-read failures must burn escalation
    /// attempts so exhaustion still reaches the terminal rollback; otherwise
    /// the task falls back to the retryable path and the re-drive loops
    /// forever (the exact wedge F3 exists to close).
    #[test]
    fn exact_key_escalation_exhausts_when_the_source_cannot_read_the_named_record() {
        let manifest = vec![(tk(2), 7u32)];
        let initial = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(2),
        );
        let mut attempts = 0usize;
        let outcome = escalate_missing_exact_keys(initial, &manifest, 3, true, |action| {
            let EscalationAction::Repush(missing) = action else {
                panic!("this shape must re-push, not reduce: {action:?}");
            };
            attempts += 1;
            assert_eq!(missing, [tk(2)]);
            Err(EscalationAttemptError::Repush(
                "baseline shard 227: read_record_snapshot TxKey(0200000000000000...): \
                 external blob missing"
                    .to_string(),
            ))
        });
        assert_eq!(
            attempts, 3,
            "source-read failures must burn attempts toward the terminal bound",
        );
        match outcome {
            ExactKeyEscalation::Exhausted { last_err } => {
                assert!(
                    last_err.contains("external blob missing"),
                    "got: {last_err}"
                );
            }
            other => panic!("expected Exhausted, got {other:?}"),
        }
    }

    /// sc09/sc05 guard: a rejection that is NOT an exact-key rejection keeps
    /// the historical probe/relinquish failure handling — the escalation must
    /// not engage at all.
    #[test]
    fn exact_key_escalation_leaves_other_rejections_to_the_historical_path() {
        let manifest = vec![(tk(1), 1u32)];
        let err = "target rejected: status 4 (code=19: shard 227 record count mismatch: \
                   expected 5, got 9)"
            .to_string();
        let mut called = false;
        let outcome = escalate_missing_exact_keys(err.clone(), &manifest, 3, true, |_action| {
            called = true;
            Ok(())
        });
        assert_eq!(outcome, ExactKeyEscalation::NotExactKey { last_err: err });
        assert!(
            !called,
            "count-mismatch (relinquish path) must not trigger a re-push",
        );
    }

    /// F3 — a rejection that STOPS naming missing keys mid-escalation (e.g.
    /// the re-push landed but the retry now fails differently) returns to the
    /// historical failure handling with the newest error.
    #[test]
    fn exact_key_escalation_falls_back_when_rejection_stops_naming_keys() {
        let manifest = vec![(tk(2), 7u32)];
        let initial = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(2),
        );
        let mut attempts = 0usize;
        let outcome = escalate_missing_exact_keys(initial, &manifest, 3, true, |_action| {
            attempts += 1;
            Err(EscalationAttemptError::Completion(
                "target rejected: status 4 (code=37: target not on epoch)".to_string(),
            ))
        });
        assert_eq!(attempts, 1, "a changed error must stop the escalation");
        match outcome {
            ExactKeyEscalation::NotExactKey { last_err } => {
                assert!(last_err.contains("code=37"), "got: {last_err}");
            }
            other => panic!("expected NotExactKey, got {other:?}"),
        }
    }

    /// W3 FIX B tests — a captured completion: `(manifest_hash, entries)`.
    type SentCompletion = ([u8; 32], Vec<(TxKey, u32)>);

    /// W3 FIX B — the escalation re-push reports the keys the SOURCE itself
    /// can no longer read back (`Ok(None)` from `build_record_replay_ops`:
    /// deleted/quarantined since the fence-time manifest was built). Demanding
    /// those of the target is unsatisfiable by construction, so the retried
    /// completion must carry a manifest REDUCED by them — recomputed hash,
    /// reduced count — never the identical doomed handshake.
    #[test]
    fn repush_reduces_completion_manifest_by_source_skipped_keys() {
        let mut reduced = vec![(tk(1), 3u32), (tk(2), 7u32), (tk(3), 9u32)];
        let mut hash = compute_manifest_for_entries(&reduced);
        let original_hash = hash;
        let mut sent: Option<SentCompletion> = None;
        let result = repush_and_retry_reduced_completion(
            &mut (),
            &[tk(2)],
            &mut reduced,
            &mut hash,
            |_, refs| {
                assert_eq!(refs, [&tk(2)]);
                Ok(vec![tk(2)])
            },
            |_, h, entries| {
                sent = Some((*h, entries.to_vec()));
                Ok(())
            },
        );
        assert_eq!(result, Ok(()));
        let expected_entries = vec![(tk(1), 3u32), (tk(3), 9u32)];
        assert_eq!(
            reduced, expected_entries,
            "the skipped key must be removed from the escalation's manifest",
        );
        let (sent_hash, sent_entries) = sent.expect("the completion must be sent");
        assert_eq!(
            sent_entries, expected_entries,
            "the completion must carry the REDUCED manifest",
        );
        assert_eq!(
            sent_hash,
            compute_manifest_for_entries(&expected_entries),
            "the manifest hash must be recomputed over the reduced entries",
        );
        assert_ne!(sent_hash, original_hash);
    }

    /// W3 FIX B — a re-push that skips nothing must retry the completion with
    /// the manifest UNCHANGED (same entries, same hash).
    #[test]
    fn repush_without_skips_keeps_the_manifest_intact() {
        let original = vec![(tk(1), 3u32), (tk(2), 7u32)];
        let mut reduced = original.clone();
        let mut hash = compute_manifest_for_entries(&reduced);
        let original_hash = hash;
        let mut sent: Option<SentCompletion> = None;
        let result = repush_and_retry_reduced_completion(
            &mut (),
            &[tk(2)],
            &mut reduced,
            &mut hash,
            |_, _refs| Ok(Vec::new()),
            |_, h, entries| {
                sent = Some((*h, entries.to_vec()));
                Ok(())
            },
        );
        assert_eq!(result, Ok(()));
        assert_eq!(reduced, original);
        let (sent_hash, sent_entries) = sent.expect("the completion must be sent");
        assert_eq!(sent_entries, original);
        assert_eq!(sent_hash, original_hash);
    }

    /// W3 FIX B — the wedge end-to-end: the target rejects `code=19` for a
    /// key the source can no longer ship. Re-sending the identical manifest
    /// is guaranteed `Exhausted` (observed verbatim across 8+ re-heal
    /// rounds); with the reduction the very next completion carries a
    /// manifest without the unshippable key and verifies.
    #[test]
    fn escalation_verifies_with_reduced_manifest_when_source_lacks_a_key() {
        let manifest = vec![(tk(1), 3u32), (tk(2), 7u32)];
        let initial = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(2),
        );
        let mut reduced = manifest.clone();
        let mut hash = compute_manifest_for_entries(&reduced);
        let mut completions: Vec<Vec<(TxKey, u32)>> = Vec::new();
        let outcome = escalate_missing_exact_keys(initial, &manifest, 3, true, |action| {
            let EscalationAction::Repush(missing) = action else {
                panic!("this shape must re-push, not reduce: {action:?}");
            };
            repush_and_retry_reduced_completion(
                &mut (),
                missing,
                &mut reduced,
                &mut hash,
                |_, _refs| Ok(vec![tk(2)]),
                |_, _h, entries| {
                    completions.push(entries.to_vec());
                    if entries.iter().any(|(k, _)| *k == tk(2)) {
                        Err(format!(
                            "target rejected: status 4 (code=19: shard 227 missing exact \
                             key {:?}: TxNotFound)",
                            tk(2),
                        ))
                    } else {
                        Ok(())
                    }
                },
            )
        });
        assert_eq!(outcome, ExactKeyEscalation::Verified);
        assert_eq!(
            completions,
            vec![vec![(tk(1), 3u32)]],
            "exactly one completion retry, carrying the reduced manifest",
        );
    }

    /// W3 FIX B — a reduction that EMPTIES the manifest is terminal. The
    /// attempt is burned as a source-side failure (no completion is sent), so
    /// the bounded escalation exhausts into
    /// `terminally_abort_unshippable_task` — the zero-shippable disposition
    /// of today. See `repush_and_retry_reduced_completion` for why an
    /// empty-manifest completion cannot verify here.
    #[test]
    fn escalation_exhausts_terminally_when_reduction_empties_the_manifest() {
        let manifest = vec![(tk(2), 7u32)];
        let initial = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(2),
        );
        let mut reduced = manifest.clone();
        let mut hash = compute_manifest_for_entries(&reduced);
        let mut attempts = 0usize;
        let mut completion_sent = false;
        let outcome = escalate_missing_exact_keys(initial, &manifest, 3, true, |action| {
            let EscalationAction::Repush(missing) = action else {
                panic!("this shape must re-push, not reduce: {action:?}");
            };
            attempts += 1;
            repush_and_retry_reduced_completion(
                &mut (),
                missing,
                &mut reduced,
                &mut hash,
                |_, _refs| Ok(vec![tk(2)]),
                |_, _h, _entries| {
                    completion_sent = true;
                    Ok(())
                },
            )
        });
        assert_eq!(
            attempts, 3,
            "the empty reduction must stay inside the bound"
        );
        assert!(
            !completion_sent,
            "an emptied manifest must never be sent as a completion",
        );
        match outcome {
            ExactKeyEscalation::Exhausted { last_err } => {
                assert!(last_err.contains("zero shippable"), "got: {last_err}");
            }
            other => panic!("expected Exhausted, got {other:?}"),
        }
    }

    /// W8 (defect 2) — builds the target's vetoed-key rejection as the source
    /// sees it through the completion error envelope.
    fn vetoed_reject(key: TxKey, tomb_gen: u32) -> String {
        format!(
            "target rejected: status 4 (code=19: shard 227 exact key {:?} vetoed by \
             deletion tombstone (cause=ClientDelete gen={} height=900): TxNotFound)",
            key, tomb_gen,
        )
    }

    /// W8 (defect 2) — the vetoed-key parser resolves the truncated Debug
    /// name back to the full manifest key WITH the tombstone generation, and
    /// rejects near-miss shapes (wrong code, missing marker, unknown key).
    /// The `missing exact key` shape must NOT match — the two parsers split
    /// the code=19 space between them.
    #[test]
    fn completion_rejection_vetoed_keys_parses_the_veto_shape_only() {
        let manifest = vec![(tk(1), 3u32), (tk(2), 7u32)];
        assert_eq!(
            completion_rejection_vetoed_keys(&vetoed_reject(tk(2), 9), &manifest),
            vec![(tk(2), 9u32)],
            "the veto shape must resolve to the full key and tombstone generation",
        );
        // The missing-key shape is NOT a veto.
        let missing = format!(
            "target rejected: status 4 (code=19: shard 227 missing exact key {:?}: TxNotFound)",
            tk(2),
        );
        assert!(completion_rejection_vetoed_keys(&missing, &manifest).is_empty());
        // And the veto shape is NOT a missing key (no re-push attempts burned).
        assert!(completion_rejection_missing_keys(&vetoed_reject(tk(2), 9), &manifest).is_empty());
        // Wrong code: only code=19 carries the verify rejection.
        let wrong_code = vetoed_reject(tk(2), 9).replace("code=19:", "code=22:");
        assert!(completion_rejection_vetoed_keys(&wrong_code, &manifest).is_empty());
        // A named key absent from the manifest resolves to nothing.
        assert!(completion_rejection_vetoed_keys(&vetoed_reject(tk(9), 4), &manifest).is_empty());
        // A veto without a parseable generation resolves to nothing.
        let no_gen = format!(
            "target rejected: status 4 (code=19: shard 227 exact key {:?} vetoed by \
             deletion tombstone (cause=ClientDelete): TxNotFound)",
            tk(2),
        );
        assert!(completion_rejection_vetoed_keys(&no_gen, &manifest).is_empty());
        // Review P2-5 — an AMBIGUOUS truncated name (two manifest keys share
        // the named 8-byte prefix) resolves to nothing: a reduction must
        // never touch a key the target did not veto, so exactly-one match is
        // required (the re-push parser's collision tolerance does not apply
        // to deletions).
        let mut twin_a = [0u8; 32];
        twin_a[0] = 0x77;
        let mut twin_b = twin_a;
        twin_b[31] = 1; // differs only past the truncated Debug prefix
        let ambiguous_manifest = vec![
            (TxKey { txid: twin_a }, 3u32),
            (TxKey { txid: twin_b }, 3u32),
        ];
        assert!(
            completion_rejection_vetoed_keys(
                &vetoed_reject(TxKey { txid: twin_a }, 9),
                &ambiguous_manifest,
            )
            .is_empty(),
            "an ambiguous prefix must reduce NOTHING",
        );
    }

    /// W8 (defect 2) — a vetoed key whose tombstone generation is at-or-ahead
    /// of the source's manifest generation is REDUCED from the manifest with
    /// NO re-push and NO attempt burned; the retried completion succeeds for
    /// the rest of the shard. Pre-fix this shape burned all 3 re-push
    /// attempts (each re-pushed create vetoed again) and terminally aborted.
    #[test]
    fn escalation_reduces_vetoed_key_without_burning_repush_attempts() {
        let manifest = vec![(tk(1), 3u32), (tk(2), 7u32)];
        let initial = vetoed_reject(tk(2), 9); // tombstone ahead of gen 7: sound
        let mut reduced = manifest.clone();
        let mut hash = compute_manifest_for_entries(&reduced);
        let mut repushes = 0usize;
        let mut completions: Vec<Vec<(TxKey, u32)>> = Vec::new();
        let outcome =
            escalate_missing_exact_keys(initial, &manifest, 3, true, |action| match action {
                EscalationAction::Repush(_) => {
                    repushes += 1;
                    Ok(())
                }
                EscalationAction::ReduceVetoed(vetoed) => {
                    assert_eq!(vetoed, [tk(2)]);
                    reduce_vetoed_and_retry_completion(
                        &mut (),
                        vetoed,
                        &mut reduced,
                        &mut hash,
                        |_, h, entries| {
                            assert_eq!(h, &compute_manifest_for_entries(entries));
                            completions.push(entries.to_vec());
                            Ok(())
                        },
                    )
                }
            });
        assert_eq!(outcome, ExactKeyEscalation::Verified);
        assert_eq!(repushes, 0, "a veto must never be re-pushed");
        assert_eq!(
            completions,
            vec![vec![(tk(1), 3u32)]],
            "exactly one completion retry, carrying the veto-reduced manifest",
        );
    }

    /// W8 (defect 2, data safety) — a veto whose tombstone generation is
    /// strictly BEHIND the source's manifest generation is vetoing a NEWER
    /// same-lineage record (the generation-blind ClientDelete veto). The
    /// reduction is REFUSED — reducing would let the committed-handoff
    /// orphan cleanup delete the newest copy — and the rejection falls
    /// through to the historical (fail/rollback, source keeps its copy)
    /// handling.
    #[test]
    fn escalation_refuses_vetoed_reduction_when_source_generation_is_ahead() {
        let manifest = vec![(tk(2), 7u32)];
        let initial = vetoed_reject(tk(2), 3); // tombstone BEHIND gen 7: unsound
        let mut called = false;
        let outcome = escalate_missing_exact_keys(initial.clone(), &manifest, 3, true, |_action| {
            called = true;
            Ok(())
        });
        assert_eq!(
            outcome,
            ExactKeyEscalation::NotExactKey { last_err: initial }
        );
        assert!(
            !called,
            "an unsound veto must neither reduce nor re-push — historical path only",
        );
    }

    /// W8 (defect 2) — the all-vetoed shard: the reduction empties the
    /// manifest, which is terminal (Exhausted -> terminal abort, the
    /// zero-shippable disposition) without sending an empty completion and
    /// without burning re-push attempts on the way.
    #[test]
    fn escalation_vetoed_reduction_that_empties_the_manifest_is_terminal() {
        let manifest = vec![(tk(2), 7u32)];
        let initial = vetoed_reject(tk(2), 9);
        let mut reduced = manifest.clone();
        let mut hash = compute_manifest_for_entries(&reduced);
        let mut completion_sent = false;
        let outcome =
            escalate_missing_exact_keys(initial, &manifest, 3, true, |action| match action {
                EscalationAction::Repush(_) => panic!("a veto must never be re-pushed"),
                EscalationAction::ReduceVetoed(vetoed) => reduce_vetoed_and_retry_completion(
                    &mut (),
                    vetoed,
                    &mut reduced,
                    &mut hash,
                    |_, _h, _entries| {
                        completion_sent = true;
                        Ok(())
                    },
                ),
            });
        assert!(
            !completion_sent,
            "an emptied manifest must never be sent as a completion",
        );
        match outcome {
            ExactKeyEscalation::Exhausted { last_err } => {
                assert!(
                    last_err.contains("vetoed every"),
                    "the terminal error must name the veto cause: {last_err}"
                );
            }
            other => panic!("expected Exhausted, got {other:?}"),
        }
    }

    /// W8 review P0-1 — the DEFAULT: with `migration_vetoed_reduction_enabled`
    /// off, a sound vetoed rejection takes the pre-W8 disposition — terminal
    /// Exhausted (→ terminal abort → rollback to source, data-safe) — with
    /// NO reduction and NO re-push attempts burned on the unwinnable veto.
    #[test]
    fn escalation_flag_off_vetoed_rejection_is_terminal_without_reduction() {
        let manifest = vec![(tk(1), 3u32), (tk(2), 7u32)];
        let initial = vetoed_reject(tk(2), 9); // sound veto — would reduce if armed
        let mut called = false;
        let outcome =
            escalate_missing_exact_keys(initial.clone(), &manifest, 3, false, |_action| {
                called = true;
                Ok(())
            });
        assert!(
            !called,
            "with the reduction disarmed, neither a reduce nor a re-push may run"
        );
        match outcome {
            ExactKeyEscalation::Exhausted { last_err } => {
                assert_eq!(
                    last_err, initial,
                    "the terminal disposition must carry the veto-naming rejection"
                );
            }
            other => panic!("expected Exhausted (pre-W8 disposition), got {other:?}"),
        }
    }

    /// W8 review P1-3 — the reduction-round backstop: a target that names a
    /// NEW vetoed key on every completion retry (instead of the full set at
    /// once) is cut off after `VETOED_REDUCTION_ROUNDS_MAX` rounds rather
    /// than walking the manifest down one write-fenced round-trip at a time.
    #[test]
    fn escalation_caps_vetoed_reduction_rounds() {
        let manifest: Vec<(TxKey, u32)> = (1..=6).map(|i| (tk(i), 3u32)).collect();
        let initial = vetoed_reject(tk(1), 9);
        let mut reduced = manifest.clone();
        let mut hash = compute_manifest_for_entries(&reduced);
        let mut rounds = 0usize;
        let outcome = escalate_missing_exact_keys(initial, &manifest, 3, true, |action| {
            let EscalationAction::ReduceVetoed(vetoed) = action else {
                panic!("a veto must never be re-pushed: {action:?}");
            };
            rounds += 1;
            let next = tk(rounds as u8 + 1);
            reduce_vetoed_and_retry_completion(
                &mut (),
                vetoed,
                &mut reduced,
                &mut hash,
                |_, _h, _entries| {
                    // The drifting target vetoes ANOTHER key every retry.
                    Err(vetoed_reject(next, 9))
                },
            )
        });
        assert_eq!(
            rounds, VETOED_REDUCTION_ROUNDS_MAX,
            "the reduction must stop at the round cap"
        );
        match outcome {
            ExactKeyEscalation::Exhausted { last_err } => {
                assert!(
                    last_err.contains("vetoed by deletion tombstone"),
                    "the terminal error names the veto: {last_err}"
                );
            }
            other => panic!("expected Exhausted at the round cap, got {other:?}"),
        }
    }

    /// W8 (defect 2) — mixed shape: a veto reduction whose completion retry
    /// then names a genuinely-MISSING key hands over to the re-push path with
    /// the full attempt budget intact.
    #[test]
    fn escalation_handles_veto_then_missing_key_in_sequence() {
        let manifest = vec![(tk(1), 3u32), (tk(2), 7u32)];
        let initial = vetoed_reject(tk(2), 9);
        let mut reduced = manifest.clone();
        let mut hash = compute_manifest_for_entries(&reduced);
        let mut actions: Vec<String> = Vec::new();
        let outcome =
            escalate_missing_exact_keys(initial, &manifest, 3, true, |action| match action {
                EscalationAction::ReduceVetoed(vetoed) => {
                    actions.push(format!("reduce:{}", vetoed.len()));
                    reduce_vetoed_and_retry_completion(
                        &mut (),
                        vetoed,
                        &mut reduced,
                        &mut hash,
                        |_, _h, _entries| {
                            // The retried completion now names a MISSING key.
                            Err(format!(
                                "target rejected: status 4 (code=19: shard 227 missing exact \
                             key {:?}: TxNotFound)",
                                tk(1),
                            ))
                        },
                    )
                }
                EscalationAction::Repush(missing) => {
                    actions.push(format!("repush:{}", missing.len()));
                    assert_eq!(missing, [tk(1)]);
                    Ok(())
                }
            });
        assert_eq!(outcome, ExactKeyEscalation::Verified);
        assert_eq!(
            actions,
            vec!["reduce:1".to_string(), "repush:1".to_string()],
            "the veto reduces first (attempt-free), then the missing key re-pushes",
        );
    }

    /// F3 (b) — the terminal abort after an exhausted escalation: the shard
    /// rolls back to the SOURCE as the single serving master and the task is
    /// RETIRED — no Failed entry remains for the failed-task re-drive to
    /// re-send the same doomed handshake (the scenario 05/07/11 wedge at
    /// serving = target+1).
    #[test]
    fn terminal_abort_rolls_back_to_single_serving_master_and_retires_task() {
        use crate::cluster::shards::ShardHandoff;
        let old_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3), NodeId(4)];
        let mut table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let (shard, new_master) = (0..NUM_SHARDS as u16)
            .find_map(|s| {
                let old_master = table.target_assignment(s).master;
                let new_master = new_table.target_assignment(s).master;
                (old_master == NodeId(1) && new_master != NodeId(1)).then_some((s, new_master))
            })
            .expect("scale-out must move some node1 master");
        table.begin_handoff(&new_table);
        assert_eq!(table.shard_handoff_state(shard), ShardHandoff::Copying);

        let shard_table = Arc::new(ShardTableLock::new(table));
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let fenced = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let task = MigrationTask {
            shard,
            from_node: NodeId(1),
            to_node: new_master,
            is_master: true,
        };
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            NodeId(1),
            &std::collections::HashSet::from([shard]),
        );

        let counted = terminally_abort_unshippable_task(
            &migration,
            &shard_table,
            &fenced,
            &migrating,
            &task,
            new_table.version,
        );
        assert!(counted, "the terminal abort must count as a failed task");

        // Exactly ONE serving master: the source, restored as the canonical
        // (and effective) assignment with the handoff resolved.
        {
            let t = shard_table.read();
            assert_eq!(t.effective_assignment(shard).master, NodeId(1));
            assert_eq!(t.target_assignment(shard).master, NodeId(1));
            assert_eq!(t.shard_handoff_state(shard), ShardHandoff::ServingNew);
        }

        // Terminal task state: nothing left for the failed-task re-drive.
        let mut mgr = migration.lock();
        assert_eq!(mgr.failed_count(), 0, "the task must not stay Failed");
        assert!(
            mgr.take_failed_tasks().is_empty(),
            "the re-drive must have nothing to re-send",
        );
        assert!(
            mgr.active_migrations().is_empty(),
            "the tracking entry must be retired",
        );
    }

    /// W3 FIX C — a REPLICA-push terminal abort must never revert the shard's
    /// MASTER assignment. `rollback_shard` restores the shard's whole
    /// previous assignment, so a failed replica backfill aborting while the
    /// shard's master handoff is still Copying would yank mastership back to
    /// the old owner mid-flight (scenario 17's single divergent shard at
    /// 4097/4096: all nine of node1's terminal aborts there were
    /// replica-side). The replica task must be retired and counted with the
    /// table left untouched.
    #[test]
    fn replica_task_terminal_abort_leaves_master_assignment_intact() {
        use crate::cluster::shards::ShardHandoff;
        let old_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3), NodeId(4)];
        let mut table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let (shard, new_master) = (0..NUM_SHARDS as u16)
            .find_map(|s| {
                let old_master = table.target_assignment(s).master;
                let new_master = new_table.target_assignment(s).master;
                (old_master == NodeId(1) && new_master != NodeId(1)).then_some((s, new_master))
            })
            .expect("scale-out must move some node1 master");
        table.begin_handoff(&new_table);
        assert_eq!(table.shard_handoff_state(shard), ShardHandoff::Copying);

        let shard_table = Arc::new(ShardTableLock::new(table));
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        let fenced = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        // A REPLICA backfill task for the same shard (e.g. the new topology
        // also names NodeId(4) a replica elsewhere) that terminally fails.
        let task = MigrationTask {
            shard,
            from_node: NodeId(1),
            to_node: NodeId(4),
            is_master: false,
        };
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            NodeId(1),
            &std::collections::HashSet::from([shard]),
        );

        let counted = terminally_abort_unshippable_task(
            &migration,
            &shard_table,
            &fenced,
            &migrating,
            &task,
            new_table.version,
        );
        assert!(
            counted,
            "the terminal abort must still count as a failed task"
        );

        // The in-flight MASTER handoff must be untouched: still Copying, the
        // target assignment still naming the new master.
        {
            let t = shard_table.read();
            assert_eq!(
                t.target_assignment(shard).master,
                new_master,
                "a replica-push abort must not revert the shard's master assignment",
            );
            assert_eq!(
                t.shard_handoff_state(shard),
                ShardHandoff::Copying,
                "the shard's master handoff must stay in flight",
            );
            assert_eq!(
                t.effective_assignment(shard).master,
                NodeId(1),
                "the old master keeps serving mid-handoff exactly as before the abort",
            );
        }

        // Terminal task state: nothing left for the failed-task re-drive.
        let mut mgr = migration.lock();
        assert_eq!(mgr.failed_count(), 0, "the task must not stay Failed");
        assert!(
            mgr.take_failed_tasks().is_empty(),
            "the re-drive must have nothing to re-send",
        );
        assert!(
            mgr.active_migrations().is_empty(),
            "the tracking entry must be retired",
        );
    }

    /// The reaper must treat `Preparing` exactly like `Fenced`.
    ///
    /// A scenario-05 nightly settled with masters at 4096/4096, handoffs 0 and
    /// inbound 0 — fully converged — while node1 held eight zero-progress tasks
    /// stuck in `Preparing` (shards 11/323/324/344/878/887/895/3270, all
    /// `total_records == 0`), pinning `active_migrations` at 8 forever. The
    /// reaper only matched `Fenced`, so nothing retired them and every gate
    /// waiting on "no active migrations" waited forever.
    #[test]
    fn stranded_candidate_covers_both_transient_states_with_no_progress() {
        use crate::cluster::migration::MigrationState;
        for state in [MigrationState::Preparing, MigrationState::Fenced] {
            assert!(
                task_is_stranded_candidate(&state, 0, 0, false),
                "{state:?} with zero progress and an unserved queue must be reapable",
            );
        }
    }

    /// The guard that keeps the `Preparing` reap from eating a live drain.
    ///
    /// An EMPTY shard's handoff moves no bytes and no records by definition,
    /// and `Preparing` doubles as the enqueued state, so a healthy task can sit
    /// there past the timeout waiting for a worker slot. Scenario 09 had node3
    /// mid-drain with 2904 active tasks (1680 `Preparing`, 1224 `Streaming`),
    /// every one of them `total_records == 0` — reaping on dwell alone would
    /// have aborted the whole drain. Anything streaming means the pool is
    /// working the queue.
    ///
    /// `Fenced` is unaffected: it is entered per task immediately before the
    /// completion handshake, so a live task never dwells there regardless of
    /// what the rest of the queue is doing.
    #[test]
    fn stranded_candidate_spares_queued_preparing_while_the_pool_is_streaming() {
        use crate::cluster::migration::MigrationState;
        assert!(
            !task_is_stranded_candidate(&MigrationState::Preparing, 0, 0, true),
            "a queued Preparing task must be spared while other tasks stream",
        );
        assert!(
            task_is_stranded_candidate(&MigrationState::Fenced, 0, 0, true),
            "Fenced is a per-task cutover state — a live queue does not excuse a stall",
        );
    }

    /// A task that has moved data has a live worker behind it — reaping it
    /// would abort a real in-flight migration.
    #[test]
    fn stranded_candidate_excludes_tasks_that_made_progress() {
        use crate::cluster::migration::MigrationState;
        for state in [MigrationState::Preparing, MigrationState::Fenced] {
            for served in [false, true] {
                assert!(
                    !task_is_stranded_candidate(&state, 1, 0, served),
                    "{state:?} that sent bytes must not be reaped (served={served})",
                );
                assert!(
                    !task_is_stranded_candidate(&state, 0, 1, served),
                    "{state:?} that migrated records must not be reaped (served={served})",
                );
            }
        }
    }

    /// `Streaming` is excluded even at zero progress: it is a long-running
    /// state a healthy worker legitimately occupies before the first byte
    /// lands. Terminal states are already retired and must not be re-reaped.
    #[test]
    fn stranded_candidate_excludes_streaming_and_terminal_states() {
        use crate::cluster::migration::MigrationState;
        for state in [
            MigrationState::Streaming,
            MigrationState::Complete,
            MigrationState::Failed,
        ] {
            for served in [false, true] {
                assert!(
                    !task_is_stranded_candidate(&state, 0, 0, served),
                    "{state:?} must never be reaped as stranded (served={served})",
                );
            }
        }
    }

    /// A node holding too FEW masters must be detected as work outstanding.
    ///
    /// The settled-state reactivation metric compares the table against its own
    /// `intended_master`, which a rolled-back table satisfies, so it reports
    /// zero. Task #22's phantom counter catches only the over-ownership
    /// direction. A scenario-05 failure settled with every node agreeing on
    /// term, placement version and members and zero migrations anywhere, yet:
    /// node1 m=1366, node2 m=848, node3 m=1365 — 517 shards mastered by nobody,
    /// permanently, with the cluster believing it had converged.
    #[test]
    fn missing_master_count_sees_under_ownership_that_the_mismatch_metric_cannot() {
        let members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let rf = 2u8;
        let pv = 1u16;
        let committed = ShardTable::compute_with_epoch(&members, rf, 4, pv);

        // A converged node has nothing outstanding in either direction.
        for node in &members {
            assert_eq!(
                missing_master_shard_count(&committed, &members, rf, *node, pv, None,),
                0,
                "a table equal to the committed placement owes nothing"
            );
            assert_eq!(
                phantom_master_shard_count(&committed, &members, rf, *node, pv, None,),
                0
            );
        }

        // Now model the captured failure: node2 never acquired a set of shards,
        // so its local table still names node1 as their master. Its table stays
        // internally self-consistent, which is exactly why the mismatch metric
        // is blind to it.
        // `set_master_for_shard` only promotes a node already in the shard's
        // replica set, so hand each shard to whichever replica it actually has
        // and count the mutations that really landed.
        let mut rolled_back = committed.clone();
        let mut handed_off = 0usize;
        for shard in 0..NUM_SHARDS as u16 {
            let a = committed.target_assignment(shard);
            if a.master != NodeId(2) {
                continue;
            }
            let Some(&replica) = a.replicas.first() else {
                continue;
            };
            rolled_back.set_master_for_shard(shard, replica);
            if rolled_back.target_assignment(shard).master != NodeId(2) {
                handed_off += 1;
            }
        }
        assert!(
            handed_off > 0,
            "precondition: some of node2's shards were rolled back to a replica"
        );

        assert_eq!(
            missing_master_shard_count(&rolled_back, &members, rf, NodeId(2), pv, None,),
            handed_off,
            "node2 must be seen to owe every master it failed to acquire"
        );
        assert_eq!(
            phantom_master_shard_count(&rolled_back, &members, rf, NodeId(2), pv, None,),
            0,
            "node2 is not OVER-owning — the existing counter cannot see this"
        );

        // And the settled-state mismatch metric genuinely reports nothing,
        // which is the reason the repair never fired.
        let (mismatched, _) =
            committed_topology_reactivation_metrics(&rolled_back, &members, rf, 4, pv);
        assert_eq!(
            mismatched, 0,
            "the rolled-back table is internally self-consistent, so the existing \
             metric sees no work — this is the blindness being fixed"
        );
    }

    /// The stale-epoch detector must recognise what the producer actually emits.
    ///
    /// `migration_error_is_stale_epoch` reads a string built by
    /// `decode_migration_batch_error_detail`, so this feeds the real encoder
    /// output through the real decoder and then the detector — if either side's
    /// format changes, this fails rather than silently never matching again.
    #[test]
    fn stale_epoch_detail_is_recognised() {
        use crate::protocol::opcodes::{ERR_MIGRATION_IN_PROGRESS, ERR_STALE_EPOCH};

        let envelope = |code: u16, msg: &str| {
            let mut p = Vec::new();
            p.extend_from_slice(&code.to_le_bytes());
            p.extend_from_slice(&(msg.len() as u16).to_le_bytes());
            p.extend_from_slice(msg.as_bytes());
            p
        };

        let stale = format!(
            "migration batch failed with status 1{}",
            decode_migration_batch_error_detail(&envelope(ERR_STALE_EPOCH, "stale cluster key"))
        );
        assert!(
            migration_error_is_stale_epoch(&stale),
            "the real ERR_STALE_EPOCH envelope must be recognised, got: {stale}"
        );

        // A different code must NOT abort the worker — those are per-shard
        // failures the worker should carry on past.
        let other = format!(
            "migration batch failed with status 1{}",
            decode_migration_batch_error_detail(&envelope(ERR_MIGRATION_IN_PROGRESS, "fenced"))
        );
        assert!(
            !migration_error_is_stale_epoch(&other),
            "only stale-epoch may abort the worker, got: {other}"
        );

        // A ReplicaAck::Error payload decodes down the other branch entirely.
        let ack_err = format!(
            "migration batch failed with status 1{}",
            decode_migration_batch_error_detail(&{
                let mut p = vec![1u8];
                p.extend_from_slice(&7u64.to_le_bytes());
                p.extend_from_slice(&5u32.to_le_bytes());
                p.extend_from_slice(b"boom!");
                p
            })
        );
        assert!(!migration_error_is_stale_epoch(&ack_err));
    }

    /// A failure reported against a SUPERSEDED epoch must still retire the task.
    ///
    /// Skipping the shard-table rollback is correct — the table has moved on and
    /// this task's ownership view is stale. But the task itself is dead: the
    /// epoch bump means the target rejects its batches with ERR_STALE_EPOCH, so
    /// it can never complete. Leaving it in the active set made it permanent,
    /// because the only thing that reaps stale actives is the next topology
    /// activation, which never comes once the cluster settles. A rolling restart
    /// left node2 holding two empty-shard handoffs in state `Fenced` for the
    /// entire 120s convergence wait.
    #[test]
    fn stale_epoch_migration_failure_retires_the_task_without_touching_the_table() {
        let migration = Arc::new(Mutex::new(MigrationManager::new()));
        // Table is at version 5; the failing task was planned at epoch 3.
        let table = ShardTable::compute_with_epoch(&[NodeId(1), NodeId(2)], 2, 5, 1);
        let shard_table = Arc::new(ShardTableLock::new(table));
        let fenced = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());
        let migrating = Arc::new(crate::cluster::migration::AtomicShardBitmap::new());

        let task = MigrationTask {
            shard: 3506,
            from_node: NodeId(2),
            to_node: NodeId(1),
            is_master: true,
        };
        migration.lock().start_outbound(
            std::slice::from_ref(&task),
            NodeId(2),
            &Default::default(),
        );
        assert_eq!(
            migration.lock().active_count(),
            1,
            "precondition: the task is tracked as active"
        );

        let version_before = shard_table.read().version;
        let rolled_back = fail_migration_task_current_epoch(
            &migration,
            &shard_table,
            &fenced,
            &migrating,
            &task,
            /* topology_epoch */ 3,
            FailedTaskTableAction::Rollback,
        );

        assert!(
            !rolled_back,
            "a stale failure must NOT roll back the newer table"
        );
        assert_eq!(
            shard_table.read().version,
            version_before,
            "the newer table is left untouched"
        );
        assert_eq!(
            migration.lock().active_count(),
            0,
            "but the dead task must leave the active set — otherwise it is stuck \
             non-terminal forever once the cluster stops changing topology"
        );
    }

    /// Concurrent `TopologyStale` observations must collapse to ONE catch-up.
    ///
    /// Every duplicate that got through used to re-propose and mint a topology
    /// term, and each new term invalidates the migrations already streaming
    /// under the previous one (the target rejects them with `ERR_STALE_EPOCH`).
    #[test]
    fn topology_catch_up_slot_admits_one_and_releases_on_drop() {
        let inflight = Arc::new(std::sync::atomic::AtomicU64::new(0));

        let first = try_begin_topology_catch_up(&inflight, 5);
        assert!(first.is_some(), "the first observation must win the slot");
        assert!(
            try_begin_topology_catch_up(&inflight, 5).is_none(),
            "a concurrent duplicate of the SAME term must NOT spawn a second catch-up"
        );
        assert!(
            try_begin_topology_catch_up(&inflight, 5).is_none(),
            "nor a third — a 3-node cluster gossips the same stale term thrice"
        );
        assert!(
            try_begin_topology_catch_up(&inflight, 4).is_none(),
            "an OLDER term is already covered by the in-flight catch-up"
        );

        drop(first);
        assert!(
            try_begin_topology_catch_up(&inflight, 5).is_some(),
            "the slot must be reusable once the catch-up finishes"
        );
    }

    /// A stalled catch-up must never swallow a strictly NEWER term.
    ///
    /// A catch-up talks to peers over TCP and can sit in `connect_timeout`
    /// against an unreachable node during a partition. With a plain busy-flag
    /// guard that stalled thread swallowed every later observation, so a
    /// majority needing to commit a topology that excludes the isolated node
    /// never acted on it — scenario 08 failed deterministically at 8a.1 with
    /// the client partition map still routing to the isolated node after 30s.
    #[test]
    fn topology_catch_up_slot_lets_a_newer_term_supersede_a_stalled_one() {
        let inflight = Arc::new(std::sync::atomic::AtomicU64::new(0));

        // Term 5 is in flight and (pretend) stalled on a dead peer.
        let stalled = try_begin_topology_catch_up(&inflight, 5).expect("term 5 wins the slot");

        let newer = try_begin_topology_catch_up(&inflight, 6)
            .expect("a strictly newer term must NOT be blocked by a stalled catch-up");

        // The stalled one finishing must not cancel the superseding claim.
        drop(stalled);
        assert!(
            try_begin_topology_catch_up(&inflight, 6).is_none(),
            "term 6 still owns the slot after the older catch-up unwound"
        );

        drop(newer);
        assert!(
            try_begin_topology_catch_up(&inflight, 7).is_some(),
            "the slot is free once the newest claimant finishes"
        );
    }

    /// A panicking catch-up must not wedge the slot forever.
    #[test]
    fn topology_catch_up_slot_is_released_when_the_thread_panics() {
        let inflight = Arc::new(std::sync::atomic::AtomicU64::new(0));
        let for_thread = inflight.clone();

        let handle = std::thread::spawn(move || {
            let _guard = try_begin_topology_catch_up(&for_thread, 3)
                .expect("the only claimant must win the slot");
            panic!("catch-up blew up");
        });
        assert!(handle.join().is_err(), "the thread really did panic");

        assert!(
            try_begin_topology_catch_up(&inflight, 3).is_some(),
            "the RAII guard must release the slot even on unwind"
        );
    }

    /// Scenario-09 fixture — an authority whose committed history is term 4 =
    /// {1,2,3} (so node 2 is an ever-seen committed voter) followed by term 5
    /// = {1,3} (node 2 quiesced itself out; graceful leave keeps the peak).
    /// Self is node 1, the deterministic (lowest-id) proposer.
    fn authority_with_committed_quiesce() -> crate::cluster::topology::TopologyAuthority {
        use crate::cluster::topology::{
            ASSIGNMENT_ABSENT_DIGEST, ClusterId, TopologyAuthority, TopologyCommit, TopologyTerm,
        };
        let auth = TopologyAuthority::new(NodeId(1), Duration::from_secs(1), 2);
        let full = vec![NodeId(1), NodeId(2), NodeId(3)];
        let term4 = TopologyCommit {
            term: 4,
            proposer: NodeId(1),
            members: full.clone(),
            cluster_id: ClusterId::UNSET,
            placement_version: 1,
            committed_peak: 3,
            digest: TopologyTerm::compute_digest(
                4,
                &ClusterId::UNSET,
                &full,
                1,
                3,
                2,
                ASSIGNMENT_ABSENT_DIGEST,
            ),
            voters: full.clone(),
            rf: 2,
            assignment: None,
        };
        assert_eq!(
            auth.handle_commit(&term4),
            Some(4),
            "fixture: the full-membership term applies"
        );
        let quiesced = vec![NodeId(1), NodeId(3)];
        let term5 = TopologyCommit {
            term: 5,
            proposer: NodeId(1),
            members: quiesced.clone(),
            cluster_id: ClusterId::UNSET,
            placement_version: 1,
            committed_peak: 3,
            digest: TopologyTerm::compute_digest(
                5,
                &ClusterId::UNSET,
                &quiesced,
                1,
                3,
                2,
                ASSIGNMENT_ABSENT_DIGEST,
            ),
            voters: quiesced.clone(),
            rf: 2,
            assignment: None,
        };
        assert_eq!(
            auth.handle_commit(&term5),
            Some(5),
            "fixture: the quiesce term applies"
        );
        auth
    }

    fn three_node_addr_book() -> RwLock<std::collections::HashMap<NodeId, SocketAddr>> {
        RwLock::new(std::collections::HashMap::from([
            (NodeId(1), "127.0.0.1:7101".parse().unwrap()),
            (NodeId(2), "127.0.0.1:7102".parse().unwrap()),
            (NodeId(3), "127.0.0.1:7103".parse().unwrap()),
        ]))
    }

    /// Scenario 09 (quiesce revert) — node2 quiesced itself out at term 5,
    /// and the commit broadcast landed WHILE this node's catch-up thread was
    /// still direct-fetching (the dispatch worker applied it, so the fetch
    /// loop saw `NotApplied` and `caught_up` stayed false). The fallback then
    /// re-proposed from the address book — quiesced node2 included — putting
    /// node2 straight back in at term 6 one millisecond after it left. Once
    /// the committed term has caught up to the remote term that triggered the
    /// catch-up, the fallback must SKIP: no proposal, membership untouched.
    #[test]
    fn catch_up_fallback_skips_reproposal_when_commit_already_caught_up() {
        let auth = authority_with_committed_quiesce();
        let addrs = three_node_addr_book();

        // The catch-up was triggered by remote_term 5 — the very term the
        // broadcast just committed locally.
        let proposal = catch_up_fallback_proposal(&auth, &addrs, 5);
        assert!(
            proposal.is_none(),
            "no re-proposal once committed_term >= remote_term — the \
             catch-up's goal is already achieved"
        );
        assert_eq!(auth.committed_term(), 5, "committed term untouched");
        assert_eq!(
            auth.committed_members(),
            vec![NodeId(1), NodeId(3)],
            "the quiesce is NOT reverted — node2 stays excluded"
        );
    }

    /// The genuinely-stale case must keep converging: the catch-up target is
    /// STRICTLY ahead of the committed term and no peer handed the newer
    /// topology over, so the fallback still re-proposes from the address book
    /// (the newer membership is unknown by definition here) and the votes of
    /// already-caught-up peers resolve it.
    #[test]
    fn catch_up_fallback_still_reproposes_when_genuinely_stale() {
        let auth = authority_with_committed_quiesce();
        let addrs = three_node_addr_book();

        let proposal = catch_up_fallback_proposal(&auth, &addrs, 6)
            .expect("committed_term 5 < remote_term 6 — the fallback must still propose");
        assert_eq!(proposal.term, 6, "proposes the next term above committed");
        assert_eq!(
            proposal.members,
            vec![NodeId(1), NodeId(2), NodeId(3)],
            "membership assembled from the address book, exactly as before"
        );
    }

    /// `send_delta_ops` must read the frame STATUS before trying to decode the
    /// payload as a `ReplicaAck`.
    ///
    /// A `STATUS_ERROR` frame carries the `[code:u16][msg_len:u16][msg]` error
    /// envelope, NOT a `ReplicaAck`. Feeding that envelope to
    /// `ReplicaAck::deserialize` reads the low byte of the error code as an ack
    /// tag — so `ERR_STALE_EPOCH` (24) surfaced as the nonsense
    /// "failed to parse delta ack: unknown op type: 24", and the migration was
    /// classified as a permanent protocol failure instead of the retryable
    /// stale-epoch condition it actually is. Observed 130× in one nightly
    /// rolling-restart run, where it stranded the shard table unconverged.
    ///
    /// The baseline (non-delta) migration path already gets this right; this
    /// test pins the delta path to the same ordering.
    #[test]
    fn send_delta_ops_surfaces_stale_epoch_envelope_not_bogus_ack_tag() {
        use crate::protocol::opcodes::{ERR_STALE_EPOCH, STATUS_ERROR};
        use std::io::Write as _;
        use std::net::TcpListener;

        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();

        // Mock target: replies exactly as the receiver's pre-apply epoch gate
        // does — STATUS_ERROR with a [code][msg_len][msg] envelope.
        let server = std::thread::spawn(move || {
            let (mut conn, _) = listener.accept().unwrap();
            let mut discard = [0u8; 8192];
            let _ = conn.read(&mut discard);
            let msg = b"stale cluster key";
            let mut payload = Vec::new();
            payload.extend_from_slice(&ERR_STALE_EPOCH.to_le_bytes());
            payload.extend_from_slice(&(msg.len() as u16).to_le_bytes());
            payload.extend_from_slice(msg);
            let resp = ResponseFrame {
                request_id: 7,
                status: STATUS_ERROR,
                payload,
            };
            conn.write_all(&resp.encode()).unwrap();
        });

        let mut stream = TcpStream::connect_timeout(&addr, Duration::from_secs(1)).unwrap();
        stream
            .set_read_timeout(Some(Duration::from_secs(2)))
            .unwrap();
        let err = send_delta_ops(&mut stream, 7, &[], 99, 1, None, None)
            .expect_err("a STATUS_ERROR delta response must fail the send");

        assert!(
            !err.contains("unknown op type"),
            "the error envelope must not be mis-parsed as an ack tag, got: {err}"
        );
        assert!(
            err.contains(&format!("code={ERR_STALE_EPOCH}")),
            "the real error code must be surfaced, got: {err}"
        );
        assert!(
            err.contains("stale cluster key"),
            "the receiver's message must be surfaced, got: {err}"
        );
        server.join().unwrap();
    }

    /// Read one framed request off a mock migration-target connection.
    fn read_request_frame(conn: &mut std::net::TcpStream) -> RequestFrame {
        use std::io::Read as _;
        let mut header = [0u8; 4];
        conn.read_exact(&mut header).unwrap();
        let len = u32::from_le_bytes(header) as usize;
        let mut body = vec![0u8; len];
        conn.read_exact(&mut body).unwrap();
        let mut frame = header.to_vec();
        frame.extend_from_slice(&body);
        let (request, _) = RequestFrame::decode(&frame).unwrap();
        request
    }

    /// Scenario 11 (staging backpressure): a delta sub-batch NAKed `Busy`
    /// (STATUS_ERROR envelope — the receiver's chunk-staging or full-redo
    /// pressure NAK) must be re-sent IDENTICALLY after a backoff instead of
    /// failing the shard, and the send must succeed once the target admits it.
    #[test]
    fn send_delta_ops_retries_identical_batch_on_busy_nak() {
        use crate::protocol::opcodes::{STATUS_ERROR, STATUS_OK};
        use crate::replication::protocol::{ReplicaAck, ReplicaOp};
        use std::io::Write as _;
        use std::net::TcpListener;

        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut conn, _) = listener.accept().unwrap();
            let first = read_request_frame(&mut conn);
            let busy = ResponseFrame {
                request_id: first.request_id,
                status: STATUS_ERROR,
                payload: ReplicaAck::Busy { first_sequence: 0 }.serialize(),
            };
            conn.write_all(&busy.encode()).unwrap();
            let second = read_request_frame(&mut conn);
            let ok = ResponseFrame {
                request_id: second.request_id,
                status: STATUS_OK,
                payload: ReplicaAck::Ok {
                    through_sequence: 0,
                }
                .serialize(),
            };
            conn.write_all(&ok.encode()).unwrap();
            (first.payload, second.payload)
        });

        let mut stream = TcpStream::connect_timeout(&addr, Duration::from_secs(1)).unwrap();
        stream
            .set_read_timeout(Some(Duration::from_secs(2)))
            .unwrap();
        let ops = vec![ReplicaOp::Freeze {
            tx_key: TxKey { txid: [7u8; 32] },
            offset: 0,
            master_generation: 1,
        }];
        send_delta_ops(&mut stream, 7, &ops, 99, 1, None, None)
            .expect("a Busy NAK must back off and retry the same sub-batch, then succeed");

        let (first, second) = server.join().unwrap();
        assert_eq!(
            first, second,
            "the Busy retry must re-send the IDENTICAL sub-batch"
        );
    }

    /// F5: `decode_migration_busy_nak` keys on payload byte 0 (the ack tag)
    /// plus an exact 9-byte length, so a `[code:u16][msg_len:u16][msg]`
    /// error envelope can only masquerade as `Busy` when its code's LOW byte
    /// equals the Busy ack tag (3) and its message is exactly 5 bytes. Pin
    /// that no envelope code emitted on the `OP_REPLICA_BATCH` response path
    /// has that low byte. The list mirrors the emission sites: the dispatch
    /// migration-batch guard (`ERR_INVARIANT_VIOLATION`), the receiver's
    /// stale-epoch gate (`ERR_STALE_EPOCH`), and the frame layer
    /// (`ERR_CLUSTER_AUTH_FAILED`, `ERR_PAYLOAD_MALFORMED`,
    /// `ERR_RATE_LIMITED`, `ERR_RESPONSE_TOO_LARGE`); extend it when a new
    /// envelope code is added to that path. `ERR_ALREADY_SPENT` (3) is the
    /// one defined collision-shaped code — a client spend-path code that
    /// must never be emitted there.
    #[test]
    fn replica_batch_envelope_codes_never_collide_with_busy_ack_tag() {
        use crate::protocol::opcodes::{
            ERR_ALREADY_SPENT, ERR_CLUSTER_AUTH_FAILED, ERR_INVARIANT_VIOLATION,
            ERR_PAYLOAD_MALFORMED, ERR_RATE_LIMITED, ERR_RESPONSE_TOO_LARGE, ERR_STALE_EPOCH,
        };
        const BUSY_ACK_TAG: u16 = 3;
        assert_eq!(
            ERR_ALREADY_SPENT, BUSY_ACK_TAG,
            "collision premise: ERR_ALREADY_SPENT is the defined code whose low byte \
             is the Busy ack tag — if this moved, update decode_migration_busy_nak's doc"
        );
        for code in [
            ERR_INVARIANT_VIOLATION,
            ERR_STALE_EPOCH,
            ERR_CLUSTER_AUTH_FAILED,
            ERR_PAYLOAD_MALFORMED,
            ERR_RATE_LIMITED,
            ERR_RESPONSE_TOO_LARGE,
        ] {
            assert_ne!(
                code & 0xFF,
                BUSY_ACK_TAG,
                "an OP_REPLICA_BATCH envelope code whose low byte equals the Busy ack \
                 tag could misclassify a terminal error as a retriable Busy NAK in \
                 decode_migration_busy_nak (code {code})"
            );
        }
    }

    /// Scenario 11 (staging backpressure): same contract for the shard
    /// baseline — a `Busy` NAK re-sends the identical sub-batch instead of
    /// failing the whole baseline (which would re-run the entire shard
    /// migration later, amplifying churn under the very memory pressure
    /// that caused the NAK).
    #[test]
    fn stream_shard_baseline_retries_identical_batch_on_busy_nak() {
        use crate::protocol::opcodes::{STATUS_ERROR, STATUS_OK};
        use crate::replication::protocol::ReplicaAck;
        use std::io::Write as _;

        let engine = test_engine();
        let shard = 77u16;
        let live_key = tx_key_for_shard(shard, 1);
        create_test_record(&engine, live_key);

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let receiver = std::thread::spawn(move || {
            let (mut conn, _) = listener.accept().unwrap();
            let first = read_request_frame(&mut conn);
            let busy = ResponseFrame {
                request_id: first.request_id,
                status: STATUS_ERROR,
                payload: ReplicaAck::Busy { first_sequence: 0 }.serialize(),
            };
            conn.write_all(&busy.encode()).unwrap();
            let second = read_request_frame(&mut conn);
            let ok = ResponseFrame {
                request_id: second.request_id,
                status: STATUS_OK,
                payload: ReplicaAck::Ok {
                    through_sequence: 0,
                }
                .serialize(),
            };
            conn.write_all(&ok.encode()).unwrap();
            (first.payload, second.payload)
        });

        let mut stream = std::net::TcpStream::connect(addr).unwrap();
        let task = MigrationTask {
            shard,
            from_node: NodeId(1),
            to_node: NodeId(2),
            is_master: true,
        };
        stream_shard_baseline(&task, &[&live_key], &engine, &mut stream, 64, 0, None, None)
            .expect("a Busy NAK must back off and retry the same sub-batch, then succeed");

        let (first, second) = receiver.join().unwrap();
        assert_eq!(
            first, second,
            "the Busy retry must re-send the IDENTICAL sub-batch"
        );
    }

    fn key_for_shard(shard: u16) -> TxKey {
        let mut txid = [0u8; 32];
        txid[..2].copy_from_slice(&shard.to_le_bytes());
        TxKey { txid }
    }

    #[test]
    fn route_prefers_effective_master_while_old_master_is_alive() {
        let old_members = vec![NodeId(1), NodeId(2)];
        let new_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let old_table = ShardTable::compute_with_epoch(&old_members, 2, 1, 1);
        let new_table = ShardTable::compute_with_epoch(&new_members, 2, 2, 1);
        let shard = (0..NUM_SHARDS as u16)
            .find(|&s| {
                old_table.target_assignment(s).master != new_table.target_assignment(s).master
            })
            .unwrap();
        let old_master = old_table.target_assignment(shard).master;
        let new_master = new_table.target_assignment(shard).master;

        let mut handoff = old_table.clone();
        handoff.begin_handoff_with(&new_table, |_| true);

        let cluster = new_test_running_cluster(
            new_master,
            handoff,
            &[
                (NodeId(1), "127.0.0.1:4101".parse().unwrap()),
                (NodeId(2), "127.0.0.1:4102".parse().unwrap()),
                (NodeId(3), "127.0.0.1:4103".parse().unwrap()),
            ],
            &new_members,
            &[],
            &[],
            &[],
            3,
        );

        let key = key_for_shard(shard);
        assert_eq!(cluster.is_master(&key), MasterQueryResult::No);
        assert_eq!(
            cluster.route(&key),
            RouteDecision::RedirectTo {
                node: old_master,
                shard_table_version: 2,
            }
        );
    }

