    fn partition_map_committed_members_match_active_table_version() {
        let active_members = vec![NodeId(1), NodeId(3)];
        let active_table = ShardTable::compute_with_epoch(&active_members, 2, 3, 1);
        let cluster = new_test_running_cluster(
            NodeId(3),
            active_table,
            &[
                (NodeId(1), "127.0.0.1:4601".parse().unwrap()),
                (NodeId(2), "127.0.0.1:4602".parse().unwrap()),
                (NodeId(3), "127.0.0.1:4603".parse().unwrap()),
            ],
            &active_members,
            &[],
            &[],
            &[],
            3,
        );

        // E-2: the commit-apply guard mirrors the propose side, so the
        // {1,3} → {1,2,3} growth needs a matching cluster_id (node 2 is an
        // unseen member the ever-seen fallback rejects when unset).
        let cid = crate::cluster::topology::ClusterId([0x5C; 16]);
        cluster.topology_authority().set_cluster_id(cid);

        let next_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let next_commit = crate::cluster::topology::TopologyCommit {
            term: 4,
            rf: 2,
            assignment: None,
            proposer: NodeId(1),
            members: next_members.clone(),
            cluster_id: cid,
            placement_version: 1,
            committed_peak: (next_members.clone()).len() as u64,
            digest: crate::cluster::topology::TopologyTerm::compute_digest(
                4,
                &cid,
                &next_members,
                1,
                (next_members).len() as u64,
                2,
                crate::cluster::topology::ASSIGNMENT_ABSENT_DIGEST,
            ),
            voters: next_members.clone(),
        };
        assert_eq!(
            cluster.topology_authority().handle_commit(&next_commit),
            Some(4)
        );

        let routing = crate::cluster::routing::RoutingInfo::decode(&cluster.encode_partition_map())
            .expect("partition map should decode");

        assert_eq!(routing.shard_table_version, 3);
        assert_eq!(routing.committed_members, active_members);
    }

    #[test]
    fn synthetic_commit_requires_quorum_proof() {
        let committed_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let routing = crate::cluster::routing::RoutingInfo {
            shard_table_version: 7,
            nodes: Vec::new(),
            shard_assignments: Vec::new(),
            committed_members: committed_members.clone(),
            placement_version: 1,
        };
        let authority =
            crate::cluster::topology::TopologyAuthority::new(NodeId(2), Duration::from_secs(1), 2);

        let maybe_commit = committed_topology_from_routing_snapshot(&routing);
        assert!(
            maybe_commit.is_none(),
            "partition-map committed_members alone must not synthesize a committed topology"
        );
        if let Some(commit) = maybe_commit {
            let _ = authority.handle_commit(&commit);
        }
        assert_eq!(
            authority.committed_term(),
            0,
            "a single peer's routing snapshot must not advance committed_term"
        );

        let proof = crate::cluster::topology::TopologyCommit {
            term: routing.shard_table_version,
            rf: 2,
            assignment: None,
            proposer: NodeId(1),
            members: committed_members.clone(),
            cluster_id: crate::cluster::topology::ClusterId::UNSET,
            placement_version: 1,
            committed_peak: (committed_members.clone()).len() as u64,
            digest: crate::cluster::topology::TopologyTerm::compute_digest(
                routing.shard_table_version,
                &crate::cluster::topology::ClusterId::UNSET,
                &committed_members,
                1,
                (committed_members).len() as u64,
                2,
                crate::cluster::topology::ASSIGNMENT_ABSENT_DIGEST,
            ),
            voters: vec![NodeId(1), NodeId(2)],
        };
        assert_eq!(
            authority.handle_commit(&proof),
            Some(routing.shard_table_version),
            "serialized committed topology with quorum voters remains accepted"
        );
    }

    #[test]
    fn committed_topology_encoding_tracks_latest_committed_term() {
        let active_members = vec![NodeId(1), NodeId(3)];
        let active_table = ShardTable::compute_with_epoch(&active_members, 2, 3, 1);
        let cluster = new_test_running_cluster(
            NodeId(3),
            active_table,
            &[
                (NodeId(1), "127.0.0.1:4701".parse().unwrap()),
                (NodeId(2), "127.0.0.1:4702".parse().unwrap()),
                (NodeId(3), "127.0.0.1:4703".parse().unwrap()),
            ],
            &active_members,
            &[],
            &[],
            &[],
            3,
        );

        // E-2: the commit-apply guard now mirrors the propose side, so a
        // matching cluster_id is required for legitimate growth ({1,3} →
        // {1,2,3} introduces an unseen member that the ever-seen fallback
        // would otherwise reject when cluster_id is unset).
        let cid = crate::cluster::topology::ClusterId([0x5A; 16]);
        cluster.topology_authority().set_cluster_id(cid);

        let committed_members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let next_commit = crate::cluster::topology::TopologyCommit {
            term: 4,
            rf: 2,
            assignment: None,
            proposer: NodeId(1),
            members: committed_members.clone(),
            cluster_id: cid,
            placement_version: 1,
            committed_peak: (committed_members.clone()).len() as u64,
            digest: crate::cluster::topology::TopologyTerm::compute_digest(
                4,
                &cid,
                &committed_members,
                1,
                (committed_members).len() as u64,
                2,
                crate::cluster::topology::ASSIGNMENT_ABSENT_DIGEST,
            ),
            voters: committed_members.clone(),
        };
        assert_eq!(
            cluster.topology_authority().handle_commit(&next_commit),
            Some(4)
        );

        let encoded = cluster.encode_committed_topology();
        let decoded = crate::cluster::topology::TopologyCommit::deserialize(&encoded)
            .expect("committed topology should decode");

        assert_eq!(decoded.term, 4);
        assert_eq!(decoded.members, committed_members);
        assert_eq!(
            decoded.digest,
            crate::cluster::topology::TopologyTerm::compute_digest(
                4,
                &cid,
                &committed_members,
                1,
                (committed_members).len() as u64,
                2,
                crate::cluster::topology::ASSIGNMENT_ABSENT_DIGEST
            ),
        );
        // E5 — the catch-up payload is the WINNING commit's own bytes, not a
        // fabrication. The fabricated form defaults `proposer` to `members[0]`
        // (NodeId(1) here, which happens to match) and `voters` to the member
        // set; only the real bytes carry the actual proposer and voter list,
        // which is what makes a receiver's quorum proof and proposer rule
        // mean anything.
        assert_eq!(
            encoded,
            next_commit.serialize(),
            "encode_committed_topology must replay the winning commit verbatim",
        );
    }

    /// E5 — a node holding a committed term but NO commit (the partition-map
    /// catch-up path carries none by design) still serves a usable payload.
    #[test]
    fn committed_topology_encoding_falls_back_when_no_commit_is_held() {
        let members = vec![NodeId(1), NodeId(2), NodeId(3)];
        let table = ShardTable::compute_with_epoch(&members, 2, 3, 1);
        let cluster = new_test_running_cluster(
            NodeId(1),
            table,
            &[
                (NodeId(1), "127.0.0.1:4711".parse().unwrap()),
                (NodeId(2), "127.0.0.1:4712".parse().unwrap()),
                (NodeId(3), "127.0.0.1:4713".parse().unwrap()),
            ],
            &members,
            &[],
            &[],
            &[],
            3,
        );
        // Restore a committed term WITHOUT a commit blob — exactly the state a
        // partition-map catch-up leaves behind.
        cluster
            .topology_authority()
            .restore(&crate::cluster::topology::PersistedTopologyState {
                peak_cluster_size: 3,
                committed_term: 8,
                committed_members: members.clone(),
                committed_voters: members.clone(),
                voted_term: 8,
                incarnation: 0,
                committed_voter_ever_seen: members.clone(),
                committed_placement_version: 1,
                committed_peak: 3,
                committed_commit: None,
                voted_digest: None,
            });
        assert_eq!(
            cluster.topology_authority().committed_commit_bytes(),
            None,
            "precondition: no commit held"
        );

        let encoded = cluster.encode_committed_topology();
        let decoded = crate::cluster::topology::TopologyCommit::deserialize(&encoded)
            .expect("fallback payload must still decode");
        assert_eq!(decoded.term, 8);
        assert_eq!(decoded.members, members);
    }

